function eventsRangeWindowSec(range: string) {
  switch (range) {
    case "24h":
      return 24 * 3600;
    case "12h":
      return 12 * 3600;
    case "6h":
      return 6 * 3600;
    case "3h":
      return 3 * 3600;
    case "1h":
      return 3600;
    case "30m":
      return 1800;
    case "10m":
      return 600;
    case "5m":
    default:
      return 300;
  }
}

function timelineFollowRefreshMs(windowSec: number) {
