/** Three missing per-second snapshots indicate an unavailable monitoring interval. */
export const AVAILABILITY_MAX_INTERVAL_SEC = 3;

export async function queryTimelineDataGaps(options: QueryOptions): Promise<TimelineDataGap[]> {
  if (!existsSync(config.timelineAvailabilityDir)) return [];

  const prior = await readLatestAvailabilityAtOrBefore(options.from);
  if (!prior) return [];

  const points = [prior, ...await readAvailabilityFiles(listAvailabilityFiles(options.from, options.to))];
  return deriveTimelineDataGaps(points, options.from, options.to);
}

export function deriveTimelineDataGaps(
  points: AvailabilityPoint[],
  from: number,
  to: number,
  maxIntervalSec = AVAILABILITY_MAX_INTERVAL_SEC
): TimelineDataGap[] {
  const uniquePoints = [...new Set(points
    .map((point) => point.time)
    .filter((time) => Number.isFinite(time) && time <= to))]
    .sort((a, b) => a - b);
  const gaps: TimelineDataGap[] = [];

  for (let index = 1; index < uniquePoints.length; index += 1) {
    const gapFrom = uniquePoints[index - 1] + maxIntervalSec;
    const gapTo = uniquePoints[index];
    if (gapTo <= gapFrom) continue;
    const clippedFrom = Math.max(from, gapFrom);
    const clippedTo = Math.min(to, gapTo);
    if (clippedTo > clippedFrom) gaps.push({ from: clippedFrom, to: clippedTo, reason: "monitor-unavailable" });
  }

  return gaps;
}

async function readLatestAvailabilityAtOrBefore(to: number): Promise<AvailabilityPoint | undefined> {
  const files = listAvailabilityFilesBefore(to);
  for (let index = files.length - 1; index >= 0; index -= 1) {
    const points = await readAvailabilityFiles([files[index]]);
    const latest = points.reduce<AvailabilityPoint | undefined>((current, point) => {
      if (point.time > to || (current && point.time <= current.time)) return current;
      return point;
    }, undefined);
    if (latest) return latest;
  }
  return undefined;
}

async function readAvailabilityFiles(files: string[]): Promise<AvailabilityPoint[]> {
  const points: AvailabilityPoint[] = [];
  for (const file of files) {
    const input = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of input) {
      const point = parseAvailabilityLine(line);
      if (point) points.push(point);
    }
  }
  return points;
}

function parseAvailabilityLine(line: string): AvailabilityPoint | undefined {
  try {
    const value = JSON.parse(line) as { record_type?: unknown; time?: unknown };
    if (value.record_type !== "timeline_availability" || !Number.isFinite(value.time)) return undefined;
    return { time: Number(value.time) };
  } catch {
    return undefined;
  }
}

function listAvailabilityFiles(from: number, to: number) {
  const files: string[] = [];
  const current = new Date(Math.floor(from) * 1000);
  current.setUTCMinutes(0, 0, 0);
  const end = new Date(Math.floor(to) * 1000);
  end.setUTCMinutes(0, 0, 0);

  while (current.getTime() <= end.getTime()) {
    files.push(...availabilityFilesForHour(current));
    current.setUTCHours(current.getUTCHours() + 1);
