#include "journal_reader.h"
#include "trace.h"

#include <algorithm>
#include <fstream>
#include <system_error>
#include <utility>

namespace {
std::string first_record_id(const std::filesystem::path &path) {
	std::ifstream input(path);
	std::string line;
	while(std::getline(input, line)) {
		if(line.empty()) continue;
		try {
			const json record = json::parse(line);
			if(record.is_object()) return record.value("record_id", std::string{});
		}
		catch(const json::parse_error &) {
			break;
		}
	}
	return {};
}

void reset_replaced_cursor(journal_reader::cursor &cursor,
	                        const std::string &path,
	                        std::uint64_t file_size,
	                        const char *reason) {
	trace(1, "journal reader: cursor reset path=%s reason=%s old_offset=%llu file_size=%llu",
	      path.c_str(), reason,
	      static_cast<unsigned long long>(cursor.offset),
	      static_cast<unsigned long long>(file_size));
	cursor.offset = 0;
	cursor.record_id.clear();
	cursor.file_start_record_id.clear();
}

void advance_cursor(journal_reader::cursor &cursor,
	                const std::string &path,
	                std::uint64_t offset,
	                const std::string &record_id) {
	if(cursor.path != path) {
		cursor.path = path;
		cursor.file_start_record_id.clear();
	}
	cursor.offset = offset;
	cursor.record_id = record_id;
	if(cursor.file_start_record_id.empty() && !record_id.empty()) {
		cursor.file_start_record_id = record_id;
	}
}
}

journal_reader::journal_reader(std::filesystem::path root)
	: m_root(std::move(root)) {
}

journal_reader::result journal_reader::read_after(cursor &cursor, const record_handler &handler) const {
	result out{};
	for(const auto &path : list_files()) {
		const auto relative = std::filesystem::relative(path, m_root).generic_string();
		if(!cursor.path.empty() && relative < cursor.path) {
			continue;
		}

		if(relative == cursor.path) {
			std::error_code ec{};
			const auto file_size = std::filesystem::file_size(path, ec);
			if(!ec && file_size < cursor.offset) {
				reset_replaced_cursor(cursor, relative, file_size, "truncated");
			}
			else if(!cursor.file_start_record_id.empty()) {
				const auto current_start = first_record_id(path);
				if(!current_start.empty() && current_start != cursor.file_start_record_id) {
					reset_replaced_cursor(cursor, relative, ec ? 0 : file_size, "start-record-changed");
				}
			}
		}

		std::ifstream input(path);
		if(!input) {
			continue;
		}

		std::uint64_t offset = 0;
		std::string line;
		while(std::getline(input, line)) {
			const std::uint64_t next_offset = offset + static_cast<std::uint64_t>(line.size()) + 1U;
			if(relative == cursor.path && next_offset <= cursor.offset) {
				offset = next_offset;
				continue;
			}
			offset = next_offset;
			if(line.empty()) {
				continue;
			}

			json record;
			try {
				record = json::parse(line);
			}
			catch(const json::parse_error &) {
				// A writer can leave a partial final line while it is appending. Keep it for the next pass.
				break;
			}
			if(!record.is_object()) {
				cursor = journal_reader::cursor{.path = relative, .offset = next_offset, .record_id = {}};
				out.advanced = true;
				continue;
			}
			if(handler(record) != 0) {
				return out;
			}
			cursor = journal_reader::cursor{
				.path = relative,
				.offset = next_offset,
				.record_id = record.value("record_id", std::string{}),
			};
			++out.records;
			out.advanced = true;
		}
	}
	return out;
}

json journal_reader::cursor_json(const cursor &cursor) {
	return json{
		{"path", cursor.path},
		{"offset", cursor.offset},
		{"record_id", cursor.record_id},
	};
}

journal_reader::cursor journal_reader::cursor_from_json(const json &value) {
	if(!value.is_object()) {
		return {};
	}
	return cursor{
		.path = value.value("path", std::string{}),
		.offset = value.value("offset", std::uint64_t{0}),
		.record_id = value.value("record_id", std::string{}),
	};
}

std::vector<std::filesystem::path> journal_reader::list_files() const {
	std::vector<std::filesystem::path> files;
	std::error_code ec{};
	if(!std::filesystem::exists(m_root, ec)) {
		return files;
	}
	for(const auto &entry : std::filesystem::recursive_directory_iterator(m_root, ec)) {
		if(ec) {
			break;
		}
		if(!entry.is_regular_file()) {
			continue;
		}
		if(entry.path().extension() != ".ndjson") {
			continue;
		}
		files.push_back(entry.path());
	}
	std::sort(files.begin(), files.end());
	return files;
}
