#ifndef WRITER_H
#define WRITER_H

#include <fstream>
#include <cstdint>
#include <memory>
#include <string>
#include <filesystem>
#include <utility>

#include "logger.h"

class writer {
public:
	writer() = default;

	writer(const std::string &id,
	       const std::string &filename,
	       std::uint64_t rotate_size_bytes = 2ULL * 1024ULL * 1024ULL,
	       std::size_t rotate_files = 3,
	       bool truncate_on_start = true) {
		m_logger = std::make_unique<logger>(id.c_str(), filename.c_str(), rotate_size_bytes, rotate_files, truncate_on_start);
	};

	virtual ~writer() = default;

	virtual int dump(const json &j) {
		if(!m_logger) {
			return -1;
		}
		return m_logger->dump(j);
	};

	virtual int dump_at(double epoch_sec, const json &j) {
		(void)epoch_sec;
		return dump(j);
	};
protected:

private:
	std::unique_ptr<logger> m_logger;
};


class list_writer : public writer {
public:
	using writer::writer;
	virtual ~list_writer() = default;
};

class time_rotating_writer : public writer {
public:
	time_rotating_writer(const std::string &id,
	                    const std::filesystem::path &root_dir,
	                    std::uint64_t max_part_size_bytes,
	                    std::uint32_t retention_hours)
		: writer()
		, m_time_logger(std::make_unique<time_logger>(id.c_str(),
		                                            root_dir,
		                                            max_part_size_bytes,
		                                            retention_hours,
		                                            3)) {
	}

	virtual ~time_rotating_writer() = default;

	virtual int dump(const json &j) override {
		return m_time_logger->dump(j);
	}

	virtual int dump_at(double epoch_sec, const json &j) override {
		return m_time_logger->dump_at(epoch_sec, j);
	}

private:
	std::unique_ptr<time_logger> m_time_logger;
};

class tee_writer : public writer {
public:
	tee_writer(std::unique_ptr<writer> primary, std::unique_ptr<writer> secondary)
		: writer()
		, m_primary(std::move(primary))
		, m_secondary(std::move(secondary)) {
	}

	virtual ~tee_writer() = default;

	virtual int dump(const json &j) override {
		int rc1 = m_primary ? m_primary->dump(j) : 0;
		int rc2 = m_secondary ? m_secondary->dump(j) : 0;
		return (rc1 != 0) ? rc1 : rc2;
	}

private:
	std::unique_ptr<writer> m_primary;
	std::unique_ptr<writer> m_secondary;
};

#endif /* WRITER_H */
}

