function TimelineLane({
  rowKey,
  row,
  range,
  gaps,
  cursorPercent,
  cursorSec,
  fadeSec,
  isHovered,
  onHoverChange,
  childCount = 0,
  expanded = true,
  onToggle
}: {
  rowKey: string;
  row: TimelineRow;
  range: { start: number; end: number };
  cursorPercent: number;
  gaps: TimelineDataGap[];
  cursorSec: number;
  fadeSec: number;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  childCount?: number;
  expanded?: boolean;
  onToggle?: () => void;
}) {
  const focused = row.segments.some((segment) => {
    const end = segment.end ?? range.end;
