}

.timeline-axis-scale .timeline-gap-band {
  z-index: 1;
}

.timeline-axis-tick,
.timeline-segment {
  z-index: 1;
}

.timeline-axis-tick {
  z-index: 2;
}

.timeline-cursor-line {
  z-index: 3;
}

