.timeline-proto-row.timeline-row-hovered,
.timeline-row.timeline-row-hovered,
.timeline-interface-header.timeline-row-cursor-focused,
.timeline-proto-row.timeline-row-cursor-focused,
.timeline-row.timeline-row-cursor-focused {
  background: var(--surface-muted);
}

.timeline-scope-row.timeline-row-hovered .timeline-scope-label,
.timeline-scope-row.timeline-row-cursor-focused .timeline-scope-label,
.timeline-interface-header.timeline-row-hovered .timeline-interface-label,
.timeline-interface-header.timeline-row-cursor-focused .timeline-interface-label,
.timeline-proto-row.timeline-row-hovered .timeline-proto-label,
.timeline-proto-row.timeline-row-cursor-focused .timeline-proto-label,
.timeline-row.timeline-row-hovered .timeline-row-label,
.timeline-row.timeline-row-cursor-focused .timeline-row-label {
  background: var(--surface-muted);
}

/* The context occupies the axis label column, leaving the time scale unobscured. */
.timeline-sticky-context {
  min-width: 0;
  overflow: hidden;
  color: var(--text-strong);
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}

/* Projected metrics availability bounds these lanes; hatch means state is unknown. */
.timeline-gap-band {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 2;
  border-inline: 1px solid color-mix(in srgb, var(--muted) 42%, transparent);
  background: repeating-linear-gradient(
    135deg,
    color-mix(in srgb, var(--surface) 78%, var(--muted)) 0 5px,
    color-mix(in srgb, var(--surface-muted) 88%, var(--muted)) 5px 10px
  );
  pointer-events: none;
}

.timeline-axis-scale .timeline-gap-band {
  z-index: 1;
}

.timeline-axis-tick,
.timeline-segment {
  z-index: 1;
}

.timeline-axis-tick {
  z-index: 2;
}

.timeline-cursor-line {
  z-index: 3;
}

/* Sticky event rail shares the time scale and remains visible above scrolling lanes. */
.timeline-axis {
  grid-template-rows: 24px 22px;
  column-gap: var(--space-2);
  row-gap: 0;
}

.timeline-axis-scale {
  height: 24px;
}

.timeline-cursor-label {
  top: 0;
}

.timeline-cursor-label.is-at-start {
  transform: translateX(0);
}

.timeline-cursor-label.is-at-end {
  transform: translateX(-100%);
}

.timeline-event-rail-label {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-1);
  padding: 0 var(--space-2);
  border-right: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
  background: color-mix(in srgb, var(--surface-muted) 88%, var(--surface));
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-event-step-controls {
  display: inline-flex;
  gap: 2px;
}

.timeline-event-step {
  min-width: 28px;
  min-height: 18px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text-strong);
  font-size: 10px;
  line-height: 1;
}

.timeline-event-step:disabled {
  opacity: .45;
}

.timeline-event-rail {
  position: relative;
  min-width: 0;
  height: 22px;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--surface) 92%, var(--surface-muted));
}

.timeline-event-rail .timeline-cursor-line {
  z-index: 4;
}

.timeline-event-marker {
  position: absolute;
  z-index: 5;
  top: 3px;
  width: 16px;
  height: 16px;
  min-height: 16px;
  padding: 0;
  transform: translateX(-50%);
  border: 1px solid currentColor;
  border-radius: 50%;
  background: var(--surface-raised);
  color: var(--warning);
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.timeline-event-marker.error {
  color: var(--danger);
}

.timeline-event-marker.selected {
  outline: 2px solid color-mix(in srgb, var(--accent) 72%, transparent);
  outline-offset: 1px;
  background: var(--surface);
}

.timeline-event-marker:hover,
.timeline-event-marker:focus-visible {
  z-index: 6;
  transform: translateX(-50%) scale(1.15);
  background: var(--surface);
}
