          onToggle: () => setProtoExpanded((current) => ({ ...current, [protoGroup.key]: !groupExpanded })),
          eventTargetKeys: timelineEventTargetKeys(protoGroup.rows)
        });

          if (!groupExpanded) continue;
          for (const { stream, flows } of protoGroup.rows) {
          const isExpanded = expanded[stream.streamKey] ?? expandLevel === "flow";
          items.push({
            key: `stream:${stream.streamKey}`,
            type: "stream",
            height: 32,
            row: stream,
            rowKey: stream.streamKey,
            childCount: flows.length,
            expanded: isExpanded,
            onToggle:
              flows.length > 0
                ? () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded }))
                : undefined,
            eventTargetKeys: timelineEventTargetKeys([{ stream, flows }])
          });

            if (!isExpanded) continue;
            for (const flow of flows) {
            const flowKey = `${stream.streamKey}::${flow.flowKey ?? flow.streamKey}`;
              items.push({
              key: `flow:${flowKey}`,
              type: "flow",
              height: 32,
              row: flow,
              rowKey: flowKey,
              eventTargetKeys: [timelineRowEventTargetKey(flow)]
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
        <div className="timeline-event-rail-label">
          <span>Events</span>
          <div className="timeline-event-step-controls">
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(-1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === 0} aria-label="Previous warning or error event" title="Previous event">Prev</button>
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === markerEvents.length - 1} aria-label="Next warning or error event" title="Next event">Next</button>
          </div>
        </div>
        <TimelineEventRail buckets={markerBuckets} gaps={gaps} range={range} cursorPercent={clampPercent(cursorPercent)} selectedEventId={selectedEventId} onActivateBucket={activateTimelineEventBucket} />
        {eventBucketPopover ? <TimelineEventBucketPopover ref={eventPopoverRef} bucket={eventBucketPopover} onClose={() => setEventBucketPopover(null)} onSelectEvent={selectTimelineEvent} canRevealEvent={canRevealTimelineEvent} onRevealEvent={(event) => { revealTimelineEvent(event); selectTimelineEvent(event); }} /> : null}
      </div>
      <div className="timeline-rows">
        {virtualized.topPad > 0 ? <div style={{ height: virtualized.topPad }} /> : null}
        {virtualized.visible.map((item) => {
          if (item.type === "interface") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineInterfaceLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={interfaceExpanded[item.group.key] ?? true}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={() => setInterfaceExpanded((current) => ({ ...current, [item.group.key]: !(current[item.group.key] ?? true) }))}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          if (item.type === "proto") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineProtoLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          if (item.type === "scope") {
            return (
              <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineScopeLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          return (
            <div key={item.key} className="timeline-virtual-item" style={{ height: item.height }}>
              <TimelineTreeGuideLines guide={item.treeGuide} />
              <TimelineLane
                rowKey={item.rowKey}
                row={item.row}
                range={range}
                gaps={gaps}
                cursorPercent={clampPercent(cursorPercent)}
                cursorSec={cursorSec}
                fadeSec={fadeSec}
                isHovered={hoveredRowKey === item.rowKey}
                onHoverChange={setHoveredRowKey}
                childCount={item.childCount ?? 0}
                expanded={item.expanded ?? false}
                onToggle={item.onToggle}
                eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                selectedEventId={selectedEventId}
                onSelectEvent={activateTimelineEventBucket}
              />
            </div>
          );
}

.timeline-interface-header.timeline-row-cursor-focused::before,
.timeline-interface-header.timeline-row-cursor-focused::after,
.timeline-proto-row.timeline-row-cursor-focused::before,
.timeline-proto-row.timeline-row-cursor-focused::after,
.timeline-row.timeline-row-cursor-focused::before,
.timeline-row.timeline-row-cursor-focused::after {
  content: none;
}

.timeline-toggle svg {
  transition: transform .16s ease;
}

.timeline-toggle svg.is-expanded {
  transform: rotate(90deg);
}

/* Virtualized tree guides follow the shared Streams hierarchy convention. */
.timeline-virtual-item { position: relative; }
.timeline-virtual-item > .timeline-scope-row,
.timeline-virtual-item > .timeline-interface-header,
.timeline-virtual-item > .timeline-proto-row,
.timeline-virtual-item > .timeline-row { position: relative; }
.timeline-tree-guide-layer { position: absolute; inset: 0; z-index: 4; pointer-events: none; }
.timeline-tree-guide-line { position: absolute; top: 0; bottom: 0; width: 1px; background: color-mix(in srgb, var(--muted) 58%, transparent); }
.timeline-tree-guide-incoming { bottom: calc(50% + 12px); }
.timeline-tree-guide-outgoing { top: calc(50% + 12px); }
.timeline-tree-guide-depth-0 { left: 19px; }
.timeline-tree-guide-depth-1 { left: 47px; }
.timeline-tree-guide-depth-2 { left: 75px; }
.timeline-tree-guide-depth-3 { left: 103px; }
.timeline-tree-guide-depth-4 { left: 131px; }
.timeline-scope-label,
.timeline-interface-label,
.timeline-proto-label,
.timeline-row-label { position: relative; z-index: 3; }
.timeline-virtual-item:hover .timeline-tree-guide-line,
.timeline-virtual-item:has(.timeline-row-hovered) .timeline-tree-guide-line,
.timeline-virtual-item:has(.timeline-row-cursor-focused) .timeline-tree-guide-line { background: color-mix(in srgb, var(--accent) 58%, var(--muted)); }


/* Scope adds the VLAN/VXLAN observation boundary between NIC and protocol. */
.timeline-scope-row,
.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  display: grid;
  grid-template-columns: var(--timeline-label-width) minmax(0, 1fr);
  gap: var(--space-2);
  align-items: center;
  min-height: 32px;
  height: 32px;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
  border-radius: 0;
}

.timeline-row-label span,
.timeline-interface-label span,
.timeline-proto-label span {
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-toggle {
  width: 22px;
  min-height: 22px;
  border-radius: var(--radius-sm);
  color: var(--muted);
}

.timeline-toggle:hover {
  background: var(--accent-soft);
  color: var(--accent);
}

.timeline-row-track,
.timeline-interface-track,
"}

