.timeline-pane {
  padding: 0;
  border-top: 0;
  background: var(--surface);
}

.timeline-header {
  min-height: var(--pane-header-height);
  align-items: center;
  margin: 0;
  padding: 0 var(--space-2);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-header h3 {
  font-size: var(--font-size-sm);
}

.timeline-browse-controls {
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
}

.timeline-browse-controls button {
  min-width: 48px;
  height: 24px;
  min-height: 24px;
  padding: 0 7px;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-browse-controls button.active {
  border: 0;
  background: var(--accent-soft);
  color: var(--accent);
}

.timeline-body {
  border: 0;
  border-radius: 0;
  background:
    linear-gradient(90deg, var(--chart-grid) 1px, transparent 1px) 0 0 / 96px 100%,
    linear-gradient(var(--chart-grid) 1px, transparent 1px) 0 0 / 100% 30px,
    var(--surface);
  padding: 0 var(--space-2);
}

.timeline-axis {
  gap: var(--space-2);
  padding: 4px 0;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-axis-tick,
.timeline-cursor-label {
  font-size: var(--font-size-xs);
}

.timeline-cursor-label {
  padding: 2px 5px;
  border-color: var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  gap: var(--space-2);
}

/* The context occupies the axis label column, leaving the time scale unobscured. */
.timeline-sticky-context {
  min-width: 0;
  overflow: hidden;
  color: var(--text-strong);
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}

/* Projected metrics availability bounds these lanes; hatch means state is unknown. */
.timeline-gap-band {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 2;
  border-inline: 1px solid color-mix(in srgb, var(--muted) 42%, transparent);
  background: repeating-linear-gradient(
    135deg,
    color-mix(in srgb, var(--surface) 78%, var(--muted)) 0 5px,
    color-mix(in srgb, var(--surface-muted) 88%, var(--muted)) 5px 10px
  );
  pointer-events: none;
}

.timeline-axis-scale .timeline-gap-band {
  z-index: 1;
}

.timeline-axis-tick,
.timeline-segment {
  z-index: 1;
}

.timeline-axis-tick {
  z-index: 2;
}

.timeline-cursor-line {
  z-index: 3;
}

/* Sticky event rail shares the time scale and remains visible above scrolling lanes. */
.timeline-axis {
  position: relative;
  grid-template-rows: 24px 22px;
  column-gap: var(--space-2);
  row-gap: 0;
}

.timeline-axis-scale {
  height: 24px;
}

.timeline-cursor-label {
  top: 0;
}

.timeline-cursor-label.is-at-start {
  transform: translateX(0);
}

.timeline-cursor-label.is-at-end {
  transform: translateX(-100%);
}

.timeline-event-rail-label {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-1);
  padding: 0 var(--space-2);
  border-right: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
  background: color-mix(in srgb, var(--surface-muted) 88%, var(--surface));
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-event-step-controls {
  display: inline-flex;
  gap: 2px;
}

.timeline-event-step {
  min-width: 28px;
  min-height: 18px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text-strong);
  font-size: 10px;
  line-height: 1;
}

.timeline-event-step:disabled {
  opacity: .45;
}

.timeline-event-rail {
  position: relative;
  min-width: 0;
  height: 22px;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--surface) 92%, var(--surface-muted));

