item.formatted_output:
  padding: 0 var(--space-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--accent);
  font-size: var(--font-size-xs);
  white-space: nowrap;
}

/* A row marker has a forgiving hit area while keeping the visual signal a thin tick. */
.timeline-row-event-marker {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 12px;
  min-height: 0;
  padding: 0;
  transform: translateX(-50%);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--warning);
}

.timeline-row-event-marker::before {
  position: absolute;
  top: 5px;
  bottom: 5px;
  left: 50%;
  width: 3px;
  content: "";
  transform: translateX(-50%);
  background: currentColor;
}

.timeline-row-event-marker.error {
  color: var(--danger);
}

.timeline-row-event-marker.selected::before {
  width: 5px;
  box-shadow: 0 0 0 1px var(--surface), 0 0 0 2px color-mix(in srgb, var(--accent) 72%, transparent);
}

.timeline-row-event-marker:hover,
.timeline-row-event-marker:focus-visible {
  z-index: 5;
  outline: 0;
}

.timeline-row-event-marker:hover::before,
.timeline-row-event-marker:focus-visible::before {
  top: 3px;
  bottom: 3px;
  width: 5px;
