import { Fragment, forwardRef, useEffect, useMemo, useRef, useState } from "react";
import type { EventLogItem, NetworkScope, TimelineDataGap, TimelineRow } from "../types/api";
import { Icon } from "./ui/Icon";

type TimelinePaneProps = {
  rows: TimelineRow[];
  gaps?: TimelineDataGap[];
  nowSec: number;
  fadeSec: number;
  rangeStartSec: number;
  rangeEndSec: number;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  onPanBySec?: (deltaSec: number) => void;
  onZoom?: (direction: "in" | "out") => void;
  events?: EventLogItem[];
  selectedEventId?: string | null;
  onSelectEvent?: (event: EventLogItem) => void;
  interfaceNames?: ReadonlyMap<number, string>;
};

type TimelineStreamGroup = { stream: TimelineRow; flows: TimelineRow[] };
type TimelineEventLane = { key: string; eventTargetKeys: string[] };
type TimelineTreeAnimation = { parentKey: string; phase: "enter" | "leave" };
type TimelineScopeGroup = {
  key: string;
  label: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};
type TimelineProtoGroup = {
  key: string;
  proto: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};

type TimelineTreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

function TimelineTreeGuideLines({ guide }: { guide: TimelineTreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);

  return <span className="timeline-tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`timeline-tree-guide-line timeline-tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`timeline-tree-guide-line timeline-tree-guide-depth-${guide.depth} timeline-tree-guide-${segment}`} />)}
  </span>;
}

export function TimelinePane({ rows, gaps = [], nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, onPanBySec, onZoom, events = [], selectedEventId = null, onSelectEvent, interfaceNames }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [scopeExpanded, setScopeExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
  const [treeAnimation, setTreeAnimation] = useState<TimelineTreeAnimation | null>(null);
  const [eventBucketPopover, setEventBucketPopover] = useState<EventMarkerBucket | null>(null);
  const [pendingRevealRowKey, setPendingRevealRowKey] = useState<string | null>(null);
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<HTMLDivElement | null>(null);
  const eventPopoverRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);
  const [isScrubbing, setIsScrubbing] = useState(false);
  const [hoveredRowKey, setHoveredRowKey] = useState<string | null>(null);
  const [viewport, setViewport] = useState({ top: 0, height: 480 });
  const cursorRafRef = useRef<number | null>(null);
  const treeAnimationTimerRef = useRef<number | null>(null);
  const pendingCursorXRef = useRef<number | null>(null);
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);
  const scrubPointerIdRef = useRef<number | null>(null);
  const skipNextTimeSelectRef = useRef(false);
  const panStartXRef = useRef<number | null>(null);
  const panLastXRef = useRef<number | null>(null);
  const hasPannedRef = useRef(false);
  const zoomHandlerRef = useRef(onZoom);
  const [isPointerInside, setIsPointerInside] = useState(false);
  const [isCtrlPressed, setIsCtrlPressed] = useState(false);
  zoomHandlerRef.current = onZoom;

  const toggleTimelineTree = (parentKey: string, isExpanded: boolean, update: () => void) => {
    if (treeAnimation) return;
    if (treeAnimationTimerRef.current !== null) window.clearTimeout(treeAnimationTimerRef.current);
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setTreeAnimation(null);
      update();
      return;
    }
    if (isExpanded) {
      setTreeAnimation({ parentKey, phase: "leave" });
      treeAnimationTimerRef.current = window.setTimeout(() => {
        update();
        setTreeAnimation(null);
        treeAnimationTimerRef.current = null;
      }, 140);
      return;
    }
    update();
    setTreeAnimation({ parentKey, phase: "enter" });
    treeAnimationTimerRef.current = window.setTimeout(() => {
      setTreeAnimation(null);
      treeAnimationTimerRef.current = null;
    }, 160);
  };

  useEffect(() => {
    const updateCtrlState = (event: KeyboardEvent) => {
      if (event.key === "Control") setIsCtrlPressed(event.type === "keydown");
    };
    window.addEventListener("keydown", updateCtrlState);
    window.addEventListener("keyup", updateCtrlState);
    return () => {
      window.removeEventListener("keydown", updateCtrlState);
      window.removeEventListener("keyup", updateCtrlState);
    };
  }, []);

  useEffect(() => {
    if (!isHoveringCursor) {
      setCursorSec(Math.min(rangeEndSec, Math.max(rangeStartSec, nowSec)));
    }
  }, [isHoveringCursor, nowSec, rangeStartSec, rangeEndSec]);

  const updateCursor = (clientX: number) => {
    const time = timeFromClientX(clientX);
    if (time !== null) setCursorSec(time);
  };

  const timeFromClientX = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return null;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return null;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
    return Math.round(range.start + ratio * (range.end - range.start));
  };

  const panFromClientX = (clientX: number) => {
    const startX = panStartXRef.current;
    const lastX = panLastXRef.current;
    const axis = axisScaleRef.current;
    if (startX === null || lastX === null || !axis || axis.clientWidth <= 0) return false;
    if (!hasPannedRef.current && Math.abs(clientX - startX) < 4) return false;
    hasPannedRef.current = true;
    const deltaSec = -((clientX - lastX) / axis.clientWidth) * (range.end - range.start);
    panLastXRef.current = clientX;
    if (deltaSec !== 0) onPanBySec?.(deltaSec);
    return true;
  };

  useEffect(() => {
    setExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (row.rowType !== "stream") continue;
        if (!(row.streamKey in next)) {
          next[row.streamKey] = expandLevel === "flow";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel, interfaceNames]);

  useEffect(() => {
    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = interfaceLabel(row, interfaceNames);
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = expandLevel !== "interface";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel]);

  useEffect(() => {
    setProtoExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const ifKey = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${row.interfaceName ?? "unknown"}`;
        const proto = row.proto || row.kind || "OTHER";
        const key = `${ifKey}::${proto}`;
        if (!(key in next)) {
          next[key] = expandLevel === "stream" || expandLevel === "flow";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel]);

  const range = useMemo(() => {
    const safeStart = Number.isFinite(rangeStartSec) ? rangeStartSec : nowSec - 60;
    const safeEnd = Number.isFinite(rangeEndSec) && rangeEndSec > safeStart ? rangeEndSec : safeStart + 1;
    const step = (safeEnd - safeStart) / 4;
    return {
      start: safeStart,
      end: safeEnd,
      ticks: Array.from({ length: 5 }, (_, index) => safeStart + step * index)
    };
  }, [nowSec, rangeStartSec, rangeEndSec]);

  useEffect(() => {
    if (!isScrubbing) return;
    const cancelScrubOnEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      scrubPointerIdRef.current = null;
      setIsScrubbing(false);
      setIsHoveringCursor(false);
      setCursorSec(Math.min(range.end, Math.max(range.start, selectedTimeSec ?? nowSec)));
    };
    window.addEventListener("keydown", cancelScrubOnEscape);
    return () => window.removeEventListener("keydown", cancelScrubOnEscape);
  }, [isScrubbing, nowSec, range, selectedTimeSec]);
  const displayedCursorSec = isScrubbing ? cursorSec : selectedTimeSec ?? cursorSec;
  const cursorPercent = percent(Math.min(range.end, Math.max(range.start, displayedCursorSec)), range.start, range.end);
  const cursorLabel = formatCursor(displayedCursorSec);
  const markerEvents = useMemo(() => events
    .filter((event) => (event.level === "warn" || event.level === "error") && event.time >= range.start && event.time <= range.end)
    .sort((left, right) => left.time - right.time || left.id.localeCompare(right.id)), [events, range.end, range.start]);
  const markerBuckets = useMemo(() => buildEventMarkerBuckets(markerEvents, range), [markerEvents, range]);
  const selectedMarkerIndex = selectedEventId === null ? -1 : markerEvents.findIndex((event) => event.id === selectedEventId);
  const selectTimelineEvent = (event: EventLogItem) => {
    setEventBucketPopover(null);
    if (onSelectEvent) onSelectEvent(event);
    else onSelectTime?.(event.time);
  };
  const activateTimelineEventBucket = (bucket: EventMarkerBucket) => {
    if (bucket.events.length === 1) {
      selectTimelineEvent(bucket.primary);
      return;
    }
    setEventBucketPopover(bucket);
  };
  const moveToAdjacentMarker = (direction: -1 | 1) => {
    if (markerEvents.length === 0) return;
    const referenceTime = selectedMarkerIndex >= 0
      ? markerEvents[selectedMarkerIndex].time
      : selectedTimeSec ?? displayedCursorSec;
    const index = selectedMarkerIndex >= 0
      ? selectedMarkerIndex + direction
      : direction > 0
      : direction > 0
        ? markerEvents.findIndex((event) => event.time > referenceTime)
        : findPreviousEventIndex(markerEvents, referenceTime);
    const event = markerEvents[index];
    if (!event) return;
    selectTimelineEvent(event);
  };

  const groupedRows = useMemo(() => {
    const streams = rows.filter((row) => row.rowType === "stream");
    const flowsByParent = new Map<string, TimelineRow[]>();
    for (const row of rows) {
      if (row.rowType !== "flow" || !row.parentStreamKey) continue;
      const group = flowsByParent.get(row.parentStreamKey) ?? [];
      group.push(row);
      flowsByParent.set(row.parentStreamKey, group);
    }
    return streams.map((stream) => {
      const flows = flowsByParent.get(stream.streamKey) ?? [];
      const flowScope = flows.find((flow) => flow.scope?.known)?.scope;
      const streamSegments = stream.segments.map((segment) => ({ start: segment.start, end: segment.end }));
      const flowSegments = flows.flatMap((flow) => flow.segments.map((segment) => ({ start: segment.start, end: segment.end })));
      const merged = mergeSegmentsNullable([...streamSegments, ...flowSegments]);
      return {
        stream: {
          ...stream,
          scope: stream.scope?.known ? stream.scope : flowScope ?? stream.scope,
          active: stream.active || flows.some((flow) => flow.active),
          segments: merged
        },
        flows
      };
    });
  }, [rows]);

  const groupedByInterface = useMemo(() => {
    const groups = new Map<string, { key: string; label: string; rows: typeof groupedRows }>();
    for (const item of groupedRows) {
      const label = interfaceLabel(item.stream, interfaceNames);
      const key = item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : `name:${label}`;
      const group = groups.get(key) ?? { key, label, rows: [] };
      group.rows.push(item);
      groups.set(key, group);
    }
    return [...groups.values()]
      .map((group) => ({
        ...group,
        segments: mergeSegments(
          group.rows.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))
        ),
        firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
        lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
        active: group.rows.some(({ stream }) => stream.active)
      }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [groupedRows, rangeEndSec, interfaceNames]);

  const canRevealTimelineEvent = (event: EventLogItem) => Boolean(
    event.streamKey && groupedByInterface.some((group) => group.rows.some(({ stream }) => stream.streamKey === event.streamKey))
  );

  const revealTimelineEvent = (event: EventLogItem) => {
    if (!event.streamKey) return;
    for (const interfaceGroup of groupedByInterface) {
      for (const scopeGroup of buildTimelineScopeGroups(interfaceGroup.rows, interfaceGroup.key, range.end)) {
        for (const protoGroup of buildTimelineProtoGroups(scopeGroup.rows, scopeGroup.key, range.end)) {
          const streamGroup = protoGroup.rows.find(({ stream }) => stream.streamKey === event.streamKey);
          if (!streamGroup) continue;
          setInterfaceExpanded((current) => ({ ...current, [interfaceGroup.key]: true }));
          setScopeExpanded((current) => ({ ...current, [scopeGroup.key]: true }));
          setProtoExpanded((current) => ({ ...current, [protoGroup.key]: true }));
          const flow = event.flowKey
            ? streamGroup.flows.find((candidate) => (candidate.flowKey ?? candidate.streamKey) === event.flowKey)
            : undefined;
          if (flow) {
            setExpanded((current) => ({ ...current, [streamGroup.stream.streamKey]: true }));
            setPendingRevealRowKey(`flow:${streamGroup.stream.streamKey}::${flow.flowKey ?? flow.streamKey}`);
          } else {
            setPendingRevealRowKey(`stream:${streamGroup.stream.streamKey}`);
          }
          return;
        }
      }
    }
  };

  useEffect(() => {
    if (hasAppliedExpandLevel.current && previousExpandLevel.current === expandLevel) {
      return;
    }
    previousExpandLevel.current = expandLevel;

    const nextInterfaces: Record<string, boolean> = {};
    for (const group of groupedByInterface) {
      nextInterfaces[group.key] = expandLevel !== "interface";
    }
    setInterfaceExpanded(nextInterfaces);

    const nextScopes: Record<string, boolean> = {};
    const nextProtos: Record<string, boolean> = {};
    for (const group of groupedByInterface) {
      for (const scopeGroup of buildTimelineScopeGroups(group.rows, group.key, range.end)) {
        nextScopes[scopeGroup.key] = expandLevel !== "interface";
        for (const protoGroup of buildTimelineProtoGroups(scopeGroup.rows, scopeGroup.key, range.end)) {
          nextProtos[protoGroup.key] = expandLevel === "stream" || expandLevel === "flow";
        }
      }
    }
    setScopeExpanded(nextScopes);
    setProtoExpanded(nextProtos);

    const nextStreams: Record<string, boolean> = {};
    for (const row of rows) {
      if (row.rowType === "stream") {
        nextStreams[row.streamKey] = expandLevel === "flow";
      }
    }
    setExpanded(nextStreams);

    if (groupedByInterface.length > 0 || rows.length > 0) {
      hasAppliedExpandLevel.current = true;
    }
  }, [expandLevel, groupedByInterface, range.end, rows]);

  useEffect(() => {
    return () => {
      if (cursorRafRef.current !== null) {
        window.cancelAnimationFrame(cursorRafRef.current);
        cursorRafRef.current = null;
      }
      if (treeAnimationTimerRef.current !== null) {
        window.clearTimeout(treeAnimationTimerRef.current);
        treeAnimationTimerRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    const chart = chartRef.current;
    if (!chart) return;
    const body = chart.closest(".timeline-body") as HTMLElement | null;
    if (!body) return;

    const update = () => {
      setViewport({
        top: body.scrollTop,
        height: body.clientHeight
      });
    };

    update();
    body.addEventListener("scroll", update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(body);

    return () => {
      body.removeEventListener("scroll", update);
      observer.disconnect();
    };
  }, [rows.length]);

  const baseRows = useMemo(() => {
    const items: Array<TimelineEventLane & { parentKey?: string } & (
      | { key: string; type: "interface"; height: number; group: (typeof groupedByInterface)[number] }
      | {
          key: string;
          type: "scope";
          height: number;
          group: TimelineScopeGroup;
          expanded: boolean;
          onToggle: () => void;
        }
      | {
          key: string;
          type: "proto";
          height: number;
          group: TimelineProtoGroup;
          expanded: boolean;
          onToggle: () => void;
        }
      | {
          key: string;
          type: "stream" | "flow";
          height: number;
          row: TimelineRow;
          rowKey: string;
          childCount?: number;
          expanded?: boolean;
          onToggle?: () => void;
        }
    )> = [];

    for (const group of groupedByInterface) {
      items.push({
        key: `if:${group.key}`,
        type: "interface",
        height: 32,
        group,
        eventTargetKeys: timelineEventTargetKeys(group.rows)
      });

      if (!(interfaceExpanded[group.key] ?? expandLevel !== "interface")) continue;
      const scopeGroups = buildTimelineScopeGroups(group.rows, group.key, range.end);

      for (const scopeGroup of scopeGroups) {
        const scopeIsExpanded = scopeExpanded[scopeGroup.key] ?? expandLevel !== "interface";
        items.push({
          key: `scope:${scopeGroup.key}`,
          type: "scope",
          height: 32,
          group: scopeGroup,
          parentKey: "if:" + group.key,
          expanded: scopeIsExpanded,
          onToggle: () => toggleTimelineTree("scope:" + scopeGroup.key, scopeIsExpanded, () => setScopeExpanded((current) => ({ ...current, [scopeGroup.key]: !scopeIsExpanded }))),
          eventTargetKeys: timelineEventTargetKeys(scopeGroup.rows)
        });
        if (!scopeIsExpanded) continue;
        const protoGroups = buildTimelineProtoGroups(scopeGroup.rows, scopeGroup.key, range.end);

        for (const protoGroup of protoGroups) {
          const groupExpanded = protoExpanded[protoGroup.key] ?? (expandLevel === "stream" || expandLevel === "flow");
        items.push({
          key: `proto:${protoGroup.key}`,
          type: "proto",
          height: 32,
          group: protoGroup,
          parentKey: "scope:" + scopeGroup.key,
          expanded: groupExpanded,
          onToggle: () => toggleTimelineTree("proto:" + protoGroup.key, groupExpanded, () => setProtoExpanded((current) => ({ ...current, [protoGroup.key]: !groupExpanded }))),
          eventTargetKeys: timelineEventTargetKeys(protoGroup.rows)
        });

          if (!groupExpanded) continue;
          for (const { stream, flows } of protoGroup.rows) {
          const isExpanded = expanded[stream.streamKey] ?? expandLevel === "flow";
          items.push({
            key: `stream:${stream.streamKey}`,
            type: "stream",
            height: 32,
            row: stream,
            rowKey: stream.streamKey,
            parentKey: "proto:" + protoGroup.key,
            childCount: flows.length,
            expanded: isExpanded,
            onToggle:
              flows.length > 0
                ? () => toggleTimelineTree("stream:" + stream.streamKey, isExpanded, () => setExpanded((current) => ({ ...current, [stream.streamKey]: !isExpanded })))
                : undefined,
            eventTargetKeys: timelineEventTargetKeys([{ stream, flows }])
          });

            if (!isExpanded) continue;
            for (const flow of flows) {
            const flowKey = `${stream.streamKey}::${flow.flowKey ?? flow.streamKey}`;
              items.push({
              key: `flow:${flowKey}`,
              type: "flow",
              height: 32,
              row: flow,
              rowKey: flowKey,
              parentKey: "stream:" + stream.streamKey,
              eventTargetKeys: [timelineRowEventTargetKey(flow)]
              });
            }
          }
        }
      }
    }
    return items;
  }, [groupedByInterface, interfaceExpanded, scopeExpanded, expanded, protoExpanded, range.end, expandLevel, treeAnimation]);

  const visibleRowEventBuckets = useMemo(
    () => buildVisibleTimelineEventBuckets(markerEvents, range, baseRows),
    [markerEvents, range, baseRows]
  );

  const guidedRows = useMemo(() => {
    const depthOf = (item: (typeof baseRows)[number]) => {
      switch (item.type) {
        case "interface": return 0;
        case "scope": return 1;
        case "proto": return 2;
        case "stream": return 3;
        case "flow": return 4;
      }
    };
    const depths = baseRows.map(depthOf);
    const nextSibling = baseRows.map((_, index) => {
      const depth = depths[index];
      for (let next = index + 1; next < baseRows.length; next += 1) {
        if (depths[next] < depth) return false;
        if (depths[next] === depth) return true;
      }
      return false;
    });
    const ancestry: Array<{ key: string; depth: number; hasNextSibling: boolean } | undefined> = [];
    const seenSiblings = new Set<string>();

    return baseRows.map((row, index) => {
      const depth = depths[index];
      ancestry.length = depth;
      const parentKey = ancestry.slice(0, depth).filter(Boolean).map((item) => item!.key).join("/") || "root";
      const siblingKey = `${parentKey}:${depth}`;
      const hasPreviousSibling = seenSiblings.has(siblingKey);
      seenSiblings.add(siblingKey);
      const guide = {
        depth,
        ancestorDepths: ancestry.slice(0, depth)
          .filter((item) => item?.hasNextSibling)
          .map((item) => item!.depth),
        hasPreviousSibling,
        hasNextSibling: nextSibling[index],
      };
      ancestry[depth] = { key: row.key, depth, hasNextSibling: nextSibling[index] };
      return { ...row, treeGuide: guide };
    });
  }, [baseRows]);

  useEffect(() => {
    if (!pendingRevealRowKey) return;
    const index = guidedRows.findIndex((row) => row.key === pendingRevealRowKey);
    if (index < 0) return;
    const chart = chartRef.current;
    const body = chart?.closest(".timeline-body") as HTMLElement | null;
    if (!body) return;
    const offset = guidedRows.slice(0, index).reduce((total, row) => total + row.height, 0);
    body.scrollTop = Math.max(0, offset - Math.max(0, (body.clientHeight - guidedRows[index].height) / 2));
    setViewport({ top: body.scrollTop, height: body.clientHeight });
    setPendingRevealRowKey(null);
  }, [guidedRows, pendingRevealRowKey]);

  useEffect(() => {
    if (!eventBucketPopover) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setEventBucketPopover(null);
    };
    const closeOnOutsidePointer = (event: PointerEvent) => {
      const target = event.target as Node;
      if (eventPopoverRef.current?.contains(target)) return;
      if ((target as Element).closest?.(".timeline-event-marker, .timeline-row-event-marker")) return;
      setEventBucketPopover(null);
    };
    window.addEventListener("keydown", closeOnEscape);
    window.addEventListener("pointerdown", closeOnOutsidePointer);
    return () => {
      window.removeEventListener("keydown", closeOnEscape);
      window.removeEventListener("pointerdown", closeOnOutsidePointer);
    };
  }, [eventBucketPopover]);

  useEffect(() => {
    const chart = chartRef.current;
    const body = chart?.closest(".timeline-body") as HTMLElement | null;
    if (!body) return;
    const maxScrollTop = Math.max(0, body.scrollHeight - body.clientHeight);
    if (body.scrollTop > maxScrollTop) {
      body.scrollTop = maxScrollTop;
      setViewport({ top: maxScrollTop, height: body.clientHeight });
    }
  }, [guidedRows.length]);


  const virtualized = useMemo(() => {
    const offsets: number[] = new Array(guidedRows.length);
    let total = 0;
    for (let index = 0; index < guidedRows.length; index += 1) {
      offsets[index] = total;
      total += guidedRows[index].height;
    }

    const overscan = Math.max(200, viewport.height);
    const startY = Math.max(0, viewport.top - overscan);
    const endY = viewport.top + viewport.height + overscan;

    let startIndex = 0;
    while (startIndex < guidedRows.length && offsets[startIndex] + guidedRows[startIndex].height < startY) {
      startIndex += 1;
    }

    let endIndex = startIndex;
    while (endIndex < guidedRows.length && offsets[endIndex] < endY) {
      endIndex += 1;
    }

    const topPad = startIndex > 0 ? offsets[startIndex] : 0;
    const bottomPad = Math.max(0, total - (endIndex > 0 ? offsets[endIndex - 1] + guidedRows[endIndex - 1].height : 0));

    return {
      startIndex,
      endIndex,
      topPad,
      bottomPad,
      visible: guidedRows.slice(startIndex, endIndex)
    };
  }, [guidedRows, viewport.height, viewport.top]);

  const stickyContext = useMemo(() => {
    if (viewport.top <= 0) return [];
    const labels: string[] = [];
    let consumed = 0;
    for (const item of guidedRows) {
      if (consumed > viewport.top) break;
      consumed += item.height;
      if (item.type === "interface") labels.splice(0, labels.length, item.group.label);
      else if (item.type === "scope") labels.splice(1, labels.length - 1, item.group.label);
      else if (item.type === "proto") labels.splice(2, labels.length - 2, item.group.proto);
      else if (item.type === "stream") labels.splice(3, labels.length - 3, timelineRowLabel(item.row));
    }
    return labels.length > 1 ? labels : [];
  }, [guidedRows, viewport.top]);

  useEffect(() => {
    const chart = chartRef.current;
    if (!chart) return;
    const onWheel = (event: WheelEvent) => {
      const onZoom = zoomHandlerRef.current;
      if (!event.ctrlKey || !onZoom || event.deltaY === 0) return;
      event.preventDefault();
      onZoom(event.deltaY < 0 ? "in" : "out");
    };
    chart.addEventListener("wheel", onWheel, { passive: false });
    return () => chart.removeEventListener("wheel", onWheel);
  }, [groupedByInterface.length]);

  if (groupedByInterface.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
      <div
        ref={chartRef}
        className={"timeline-chart" + (isScrubbing ? " is-time-scrubbing" : "") + (isPointerInside && isCtrlPressed && onZoom ? " is-zoom-mode" : "")}
        tabIndex={0}
        onKeyDown={(event) => {
          if (event.altKey || event.ctrlKey || event.metaKey || (event.key !== "ArrowLeft" && event.key !== "ArrowRight")) return;
          const target = event.target as HTMLElement;
          if (target.closest("button") && !target.closest(".timeline-event-step, .timeline-event-marker")) return;
          event.preventDefault();
          moveToAdjacentMarker(event.key === "ArrowLeft" ? -1 : 1);
        }}
        onClick={(event) => {
          if (skipNextTimeSelectRef.current) {
            skipNextTimeSelectRef.current = false;
            return;
          }
          const target = event.target as HTMLElement;
          if (!target.closest(".timeline-axis-scale, .timeline-row-track")) return;
          const selected = timeFromClientX(event.clientX);
          if (selected !== null) onSelectTime?.(selected);
        }}
        onPointerEnter={(event) => {
          setIsPointerInside(true);
          setIsCtrlPressed(event.ctrlKey);
        }}
        onPointerDown={(event) => {
          const target = event.target as HTMLElement;
          if (event.button !== 0 || !target.closest(".timeline-axis-scale, .timeline-row-track")) return;
          scrubPointerIdRef.current = event.pointerId;
          panStartXRef.current = event.clientX;
          panLastXRef.current = event.clientX;
          hasPannedRef.current = false;
          event.currentTarget.setPointerCapture(event.pointerId);
          setIsScrubbing(true);
          setIsHoveringCursor(true);
          updateCursor(event.clientX);
        }}
        onPointerMove={(event) => {
          setIsCtrlPressed(event.ctrlKey);
          if (scrubPointerIdRef.current !== null && scrubPointerIdRef.current !== event.pointerId) return;
          if (scrubPointerIdRef.current === event.pointerId && panFromClientX(event.clientX)) return;
          setIsHoveringCursor(true);
          pendingCursorXRef.current = event.clientX;
          if (cursorRafRef.current !== null) return;
          cursorRafRef.current = window.requestAnimationFrame(() => {
            cursorRafRef.current = null;
            const x = pendingCursorXRef.current;
            if (x !== null) updateCursor(x);
          });
        }}
        onPointerUp={(event) => {
          if (scrubPointerIdRef.current !== event.pointerId) return;
          const didPan = hasPannedRef.current;
          scrubPointerIdRef.current = null;
          panStartXRef.current = null;
          panLastXRef.current = null;
          hasPannedRef.current = false;
          if (cursorRafRef.current !== null) {
            window.cancelAnimationFrame(cursorRafRef.current);
            cursorRafRef.current = null;
          }
          if (!didPan) {
            const selected = timeFromClientX(event.clientX);
            if (selected !== null) {
              setCursorSec(selected);
              onSelectTime?.(selected);
            }
          }
          skipNextTimeSelectRef.current = true;
          setIsScrubbing(false);
        }}
        onPointerCancel={(event) => {
          if (scrubPointerIdRef.current !== event.pointerId) return;
          scrubPointerIdRef.current = null;
          panStartXRef.current = null;
          panLastXRef.current = null;
          hasPannedRef.current = false;
          setIsScrubbing(false);
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, selectedTimeSec ?? nowSec)));
        }}
        onPointerLeave={() => {
          setIsPointerInside(false);
          setIsCtrlPressed(false);
          if (scrubPointerIdRef.current !== null) return;
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, nowSec)));
        }}
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label">
          {stickyContext.length > 0 ? (
            <div className="timeline-sticky-context" aria-label="Current timeline hierarchy" title={stickyContext.join(" › ")}>
              {stickyContext.join(" › ")}
            </div>
          ) : null}
        </div>
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <TimelineGapBands gaps={gaps} range={range} label />
          <div className={"timeline-cursor-label" + (cursorPercent <= 5 ? " is-at-start" : cursorPercent >= 95 ? " is-at-end" : "")} style={{ left: String(clampPercent(cursorPercent)) + "%" }} title={cursorLabel}>
            {cursorLabel}
          </div>
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
        <div className="timeline-event-rail-label">
          <span>Events</span>
          <div className="timeline-event-step-controls">
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(-1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === 0} aria-label="Previous warning or error event" title="Previous event">Prev</button>
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === markerEvents.length - 1} aria-label="Next warning or error event" title="Next event">Next</button>
          </div>
        </div>
        <TimelineEventRail buckets={markerBuckets} gaps={gaps} range={range} cursorPercent={clampPercent(cursorPercent)} selectedEventId={selectedEventId} onActivateBucket={activateTimelineEventBucket} />
        {eventBucketPopover ? <TimelineEventBucketPopover ref={eventPopoverRef} bucket={eventBucketPopover} onClose={() => setEventBucketPopover(null)} onSelectEvent={selectTimelineEvent} canRevealEvent={canRevealTimelineEvent} onRevealEvent={(event) => { revealTimelineEvent(event); selectTimelineEvent(event); }} /> : null}
      </div>
      <div className="timeline-rows">
        {virtualized.topPad > 0 ? <div style={{ height: virtualized.topPad }} /> : null}
        {virtualized.visible.map((item) => {
          const itemAnimation = treeAnimation?.parentKey === item.parentKey ? treeAnimation : null;
          const animationClass = itemAnimation ? " timeline-tree-" + itemAnimation.phase : "";
          if (item.type === "interface") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineInterfaceLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={interfaceExpanded[item.group.key] ?? true}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={() => toggleTimelineTree(item.key, interfaceExpanded[item.group.key] ?? true, () => setInterfaceExpanded((current) => ({ ...current, [item.group.key]: !(current[item.group.key] ?? true) })))}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          if (item.type === "proto") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineProtoLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          if (item.type === "scope") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineScopeLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          return (
            <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
              <TimelineTreeGuideLines guide={item.treeGuide} />
              <TimelineLane
                rowKey={item.rowKey}
                row={item.row}
                range={range}
                gaps={gaps}
                cursorPercent={clampPercent(cursorPercent)}
                cursorSec={cursorSec}
                fadeSec={fadeSec}
                isHovered={hoveredRowKey === item.rowKey}
                onHoverChange={setHoveredRowKey}
                childCount={item.childCount ?? 0}
                expanded={item.expanded ?? false}
                onToggle={item.onToggle}
                eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                selectedEventId={selectedEventId}
                onSelectEvent={activateTimelineEventBucket}
              />
            </div>
          );
        })}
        {virtualized.bottomPad > 0 ? <div style={{ height: virtualized.bottomPad }} /> : null}
      </div>
    </div>
  );
}

type EventMarkerBucket = { key: string; time: number; level: "warn" | "error"; events: EventLogItem[]; primary: EventLogItem };

const MAX_EVENT_MARKERS = 240;

function TimelineEventRail({ buckets, gaps, range, cursorPercent, selectedEventId, onActivateBucket }: {
  buckets: EventMarkerBucket[];
  gaps: TimelineDataGap[];
  range: { start: number; end: number };
  cursorPercent: number;
  selectedEventId: string | null;
  onActivateBucket: (bucket: EventMarkerBucket) => void;
}) {
  return (
    <div className="timeline-event-rail" aria-label="Warning and error events">
      <TimelineGapBands gaps={gaps} range={range} />
      <div className="timeline-cursor-line" style={{ left: String(cursorPercent) + "%" }} aria-hidden="true" />
      {buckets.map((bucket) => {
        const selected = bucket.events.some((event) => event.id === selectedEventId);
        const label = eventMarkerLabel(bucket);
        return <button
          key={bucket.key}
          type="button"
          className={"timeline-event-marker " + bucket.level + (selected ? " selected" : "")}
          style={{ left: String(percent(bucket.time, range.start, range.end)) + "%" }}
          title={label}
          aria-label={label}
          onClick={(event) => { event.stopPropagation(); onActivateBucket(bucket); }}
        >
          <span aria-hidden="true">{bucket.events.length > 1 ? bucket.events.length : "!"}</span>
        </button>;
      })}
    </div>
  );
}

const TimelineEventBucketPopover = forwardRef<HTMLDivElement, {
  bucket: EventMarkerBucket;
  onClose: () => void;
  onSelectEvent: (event: EventLogItem) => void;
  canRevealEvent: (event: EventLogItem) => boolean;
  onRevealEvent: (event: EventLogItem) => void;
}>(function TimelineEventBucketPopover({ bucket, onClose, onSelectEvent, canRevealEvent, onRevealEvent }, ref) {
  const orderedEvents = [...bucket.events].sort((left, right) => left.time - right.time || left.id.localeCompare(right.id));
  return (
    <div ref={ref} className="timeline-event-bucket-popover" role="dialog" aria-label="Events at this time">
      <div className="timeline-event-bucket-header">
        <strong>{bucket.events.length} events</strong>
        <button type="button" className="timeline-event-bucket-close" onClick={onClose} aria-label="Close event list">×</button>
      </div>
      <div className="timeline-event-bucket-list">
        {orderedEvents.map((event) => {
          const target = event.targetLabel ?? event.flowKey ?? event.streamKey ?? "System";
          return <div key={event.id} className="timeline-event-bucket-item">
            <button type="button" className="timeline-event-bucket-select" onClick={() => onSelectEvent(event)}>
              <span className={"timeline-event-bucket-level " + event.level}>{event.level.toUpperCase()}</span>
              <span className="timeline-event-bucket-time">{formatCursor(event.time)}</span>
              <span className="timeline-event-bucket-message">{event.message}</span>
              <span className="timeline-event-bucket-target">{target}</span>
            </button>
            {canRevealEvent(event) ? <button type="button" className="timeline-event-bucket-reveal" onClick={() => onRevealEvent(event)}>Show target</button> : null}
          </div>;
        })}
      </div>
    </div>
  );
});

function buildEventMarkerBuckets(events: EventLogItem[], range: { start: number; end: number }): EventMarkerBucket[] {
  const bucketSec = Math.max(0.001, (range.end - range.start) / MAX_EVENT_MARKERS);
  const buckets = new Map<number, EventLogItem[]>();
  for (const event of events) {
    const key = Math.max(0, Math.min(MAX_EVENT_MARKERS - 1, Math.floor((event.time - range.start) / bucketSec)));
    const bucket = buckets.get(key) ?? [];
    bucket.push(event);
    buckets.set(key, bucket);
  }
  return [...buckets.entries()].sort(([left], [right]) => left - right).map(([key, bucket]) => {
    const primary = [...bucket].sort((left, right) => eventSeverityRank(right) - eventSeverityRank(left) || right.time - left.time || right.id.localeCompare(left.id))[0];
    return {
      key: String(key),
      time: primary.time,
      level: bucket.some((event) => event.level === "error") ? "error" : "warn",
      events: bucket,
      primary
    };
  });
}

function timelineEventTargetKey(event: EventLogItem) {
  if (event.flowKey) return `flow:${event.flowKey}`;
  if (event.streamKey) return `stream:${event.streamKey}`;
  return undefined;
}

function timelineRowEventTargetKey(row: TimelineRow) {
  if (row.rowType === "flow") return `flow:${row.flowKey ?? row.streamKey}`;
  return `stream:${row.streamKey}`;
}

function timelineEventTargetKeys(rows: TimelineStreamGroup[]) {
  const keys = new Set<string>();
  for (const { stream, flows } of rows) {
    keys.add(timelineRowEventTargetKey(stream));
    for (const flow of flows) keys.add(timelineRowEventTargetKey(flow));
  }
  return [...keys];
}

function buildVisibleTimelineEventBuckets(events: EventLogItem[], range: { start: number; end: number }, lanes: TimelineEventLane[]) {
  const laneByTarget = new Map<string, string>();
  for (const lane of lanes) {
    for (const targetKey of lane.eventTargetKeys) laneByTarget.set(targetKey, lane.key);
  }

  const eventsByLane = new Map<string, EventLogItem[]>();
  for (const event of events) {
    const targetKey = timelineEventTargetKey(event);
    const laneKey = targetKey
      ? laneByTarget.get(targetKey) ?? (event.flowKey && event.streamKey ? laneByTarget.get(`stream:${event.streamKey}`) : undefined)
      : undefined;
    if (!laneKey) continue;
    const laneEvents = eventsByLane.get(laneKey) ?? [];
    laneEvents.push(event);
    eventsByLane.set(laneKey, laneEvents);
  }
  return new Map([...eventsByLane.entries()].map(([laneKey, laneEvents]) => [laneKey, buildEventMarkerBuckets(laneEvents, range)]));
}

function eventSeverityRank(event: EventLogItem) {
  return event.level === "error" ? 2 : event.level === "warn" ? 1 : 0;
}

function eventMarkerLabel(bucket: EventMarkerBucket) {
  const count = bucket.events.length;
  const primary = bucket.primary;
  const target = primary.targetLabel ?? primary.flowKey ?? primary.streamKey ?? "System";
  return [
    count > 1 ? String(count) + " warning or error events; selected event:" : undefined,
    formatCursor(primary.time),
    primary.level.toUpperCase() + ": " + primary.message,
    "Target: " + target
  ].filter((value): value is string => Boolean(value)).join("\n");
}

function findPreviousEventIndex(events: EventLogItem[], time: number) {
  for (let index = events.length - 1; index >= 0; index -= 1) {
    if (events[index].time < time) return index;
  }
  return -1;
}

function TimelineScopeLane({
