.timeline-proto-label strong {
  font-size: var(--font-size-sm);
  font-weight: 600;
}

.timeline-row-label > span:not(.timeline-label-text) {
  display: none;
}

.timeline-interface-header.timeline-row-hovered,
.timeline-proto-row.timeline-row-hovered,
.timeline-row.timeline-row-hovered,
.timeline-interface-header.timeline-row-cursor-focused,
.timeline-proto-row.timeline-row-cursor-focused,
.timeline-row.timeline-row-cursor-focused {
  background: var(--surface-muted);
  border-radius: 0;
  box-shadow: none;
}

.timeline-interface-header.timeline-row-hovered .timeline-interface-label,
.timeline-proto-row.timeline-row-hovered .timeline-proto-label,
.timeline-row.timeline-row-hovered .timeline-row-label,
.timeline-interface-header.timeline-row-cursor-focused .timeline-interface-label,
.timeline-proto-row.timeline-row-cursor-focused .timeline-proto-label,
.timeline-row.timeline-row-cursor-focused .timeline-row-label {
  background: var(--surface-muted);
}

/* Horizontal separators come only from the actual row boundaries. */
.timeline-chart {
  background:
    linear-gradient(90deg, var(--chart-grid) 1px, transparent 1px) var(--timeline-label-width) 0 / 96px 100%,
    var(--surface);
}

/* Allow endpoint labels to remain readable over the chart area. */
.timeline-row-label {
  position: relative;
  z-index: 3;
  overflow: visible;
}

.timeline-row-track,
.timeline-interface-track,
.timeline-proto-track {
  position: relative;
  z-index: 1;
}

.timeline-row-flow .timeline-row-label strong,
.timeline-row-flow .timeline-label-text {
  min-width: max-content;
  overflow: visible;
  text-overflow: clip;
  white-space: nowrap;
}

.timeline-row-flow .timeline-row-label strong,
.timeline-row-flow .timeline-row-label .timeline-label-text {
  font-size: var(--font-size-xs) !important;
  font-weight: 400;
}

.timeline-row-flow .timeline-label-text {
  flex: 0 0 auto;
  color: var(--text-strong);
}

.timeline-row-cursor-focused,
.timeline-interface-header.timeline-row-cursor-focused,
.timeline-proto-row.timeline-row-cursor-focused,
.timeline-row.timeline-row-cursor-focused {
  background: var(--surface-muted);
  border-radius: 0;
  box-shadow: none;
}

.timeline-interface-header.timeline-row-cursor-focused::before,
.timeline-interface-header.timeline-row-cursor-focused::after,
.timeline-proto-row.timeline-row-cursor-focused::before,
.timeline-proto-row.timeline-row-cursor-focused::after,
.timeline-row.timeline-row-cursor-focused::before,
.timeline-row.timeline-row-cursor-focused::after {
  content: none;
}

.timeline-toggle {
  transform-origin: center;
  transition: transform .16s ease, background .16s ease, color .16s ease;
}

.timeline-toggle.open {
  transform: rotate(90deg);
}

/* Virtualized tree guides follow the shared Streams hierarchy convention. */
.timeline-virtual-item { position: relative; }
.timeline-virtual-item.timeline-tree-enter { animation: timeline-tree-row-enter .16s ease-out both; }
.timeline-virtual-item.timeline-tree-leave { pointer-events: none; animation: timeline-tree-row-leave .14s ease-in both; }
@keyframes timeline-tree-row-enter { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
@keyframes timeline-tree-row-leave { from { opacity: 1; transform: translateY(0); } to { opacity: 0; transform: translateY(-4px); } }
@media (prefers-reduced-motion: reduce) {
  .timeline-toggle svg,
  .timeline-virtual-item.timeline-tree-enter,
  .timeline-virtual-item.timeline-tree-leave { animation: none; transition: none; }
}
.timeline-virtual-item > .timeline-scope-row,
.timeline-virtual-item > .timeline-interface-header,
.timeline-virtual-item > .timeline-proto-row,
.timeline-virtual-item > .timeline-row { position: relative; }
.timeline-tree-guide-layer { position: absolute; inset: 0; z-index: 4; pointer-events: none; }
.timeline-tree-guide-line { position: absolute; top: 0; bottom: 0; width: 1px; background: color-mix(in srgb, var(--muted) 58%, transparent); }
.timeline-tree-guide-incoming { bottom: calc(50% + 12px); }
.timeline-tree-guide-outgoing { top: calc(50% + 12px); }
.timeline-tree-guide-depth-0 { left: 19px; }
.timeline-tree-guide-depth-1 { left: 47px; }
.timeline-tree-guide-depth-2 { left: 75px; }
