.timeline-virtual-item:hover .timeline-tree-guide-line,
.timeline-virtual-item:has(.timeline-row-hovered) .timeline-tree-guide-line,
.timeline-virtual-item:has(.timeline-row-cursor-focused) .timeline-tree-guide-line { background: color-mix(in srgb, var(--accent) 58%, var(--muted)); }


/* Scope adds the VLAN/VXLAN observation boundary between NIC and protocol. */
.timeline-scope-row,
.timeline-interface-header,
