            <span className="timeline-leaf-marker" aria-hidden="true" />
          )}
          <span className="timeline-label-text">{timelineRowLabel(row)}</span>
          {childCount > 0 && row.rowType === "stream" ? <TimelineCountBadge count={childCount} /> : null}
        </strong>
      </div>
      <div className="timeline-row-track">
        <TimelineGapBands gaps={gaps} range={range} />
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {splitTimelineSegments(row.segments, gaps, range).map((segment, index) => renderSegment(row, segment, index, range, fadeSec))}
        <TimelineRowEventMarkers buckets={eventBuckets} range={range} selectedEventId={selectedEventId} onSelectEvent={onSelectEvent} />
      </div>
    </div>
  );
}

function TimelineRowEventMarkers({ buckets, range, selectedEventId, onSelectEvent }: {
  buckets: EventMarkerBucket[];
  range: { start: number; end: number };
  selectedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
}) {
  return <>{buckets.map((bucket) => {
    const selected = bucket.events.some((event) => event.id === selectedEventId);
    const label = eventMarkerLabel(bucket);
    return <button
      key={bucket.key}
      type="button"
      className={`timeline-row-event-marker ${bucket.level}${selected ? " selected" : ""}`}
      style={{ left: `${percent(bucket.time, range.start, range.end)}%` }}
      title={label}
      aria-label={label}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => { event.stopPropagation(); onSelectEvent(bucket); }}
    />;
  })}</>;
}

function TimelineCountBadge({ count }: { count: number }) {
  return <span className="timeline-count-badge">{count}</span>;
}
function TimelineGapBands({ gaps, range, label = false }: { gaps: TimelineDataGap[]; range: { start: number; end: number }; label?: boolean }) {
  return <>{gaps.map((gap) => {
    const from = Math.max(range.start, gap.from);
    const to = Math.min(range.end, gap.to);
    if (to <= from) return null;
    const start = percent(from, range.start, range.end);
    const end = percent(to, range.start, range.end);
    return <div key={`${gap.reason}:${from}:${to}`} className="timeline-gap-band" style={{ left: `${start}%`, width: `${Math.max(0.4, end - start)}%` }} title="Monitoring data unavailable" aria-label={label ? "Monitoring data unavailable" : undefined} />;
  })}</>;
}


.timeline-event-bucket-reveal {
  align-self: center;
  min-height: 24px;
  margin-right: var(--space-2);
  padding: 0 var(--space-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--accent);
  font-size: var(--font-size-xs);
  white-space: nowrap;
}

/* A row marker has a forgiving hit area while keeping the visual signal a thin tick. */
.timeline-row-event-marker {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 12px;
  min-height: 0;
  padding: 0;
  transform: translateX(-50%);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--warning);
}

.timeline-row-event-marker::before {
  position: absolute;
  top: 5px;
  bottom: 5px;
  left: 50%;
  width: 3px;
  content: "";
  transform: translateX(-50%);
  background: currentColor;
}

## 2026-09-16: Timelineイベント集約と実時間目盛り

### Context

Timelineのイベント集約は表示範囲の左端を基準にしていたため、同じ時間幅で横移動すると集約境界が変わった。近傍マーカーは見た目上重なって個別選択しにくく、複数件マーカーのクリックでは一覧だけを開いて選択状態を更新しなかった。また、時刻目盛りと縦グリッドは実時刻境界と連動していなかった。

### Decision

イベント集約は、表示範囲から求めた1・2・5系列などの時間幅を選び、Unix時刻基準の固定境界で行う。複数件マーカーのクリックではerror優先・新しい時刻優先の代表イベントを先に選択してから一覧を開く。

レールと同一行の帯上では、18px未満に近接する集約マーカーを追加で一つのマーカーへ統合する。統合マーカーは既存のイベント一覧と個別選択を使用する。

時刻軸は表示範囲に対して約4区間になる実時間のきりのよい目盛りを選び、表示範囲内のその境界だけを描画する。縦グリッドは同じ目盛りデータを使用する。

### Reason

時間移動中の表示を安定させつつ、画面上で実際に重なるマーカーだけを一つの操作対象にできる。代表イベントの即時選択により、クリックした行と白枠・Events・Time travelの状態を一致させる。実時刻境界の目盛りとグリッドは時刻把握と帯の対応を容易にする。

### Consequences

同じRange・画面幅での横移動では、画面内に残るイベントの集約数は安定する。Range変更、画面幅変更、表示範囲端でのイベント出入りによる表示数の変化は意図した挙動である。API、保存形式、Events選択とTime travelの連携は変更しない。

---

## 2026-09-15: Timeline固定時間軸とイベントレール

### Context

Timelineの時間軸、イベントレール、左側の階層パンくずは縦方向の調査中にも参照する必要がある。共通スタイルは`timeline-axis`をstickyにしていたが、Timeline専用スタイルが`position: relative`で上書きしており、長いツリーをスクロールすると軸とレールが画面外へ移動していた。

### Decision

Timeline専用スタイルで`timeline-axis`を`position: sticky; top: 0`に戻し、z-indexを10へ設定する。時間軸、イベントレール、パンくずを同じaxis内で固定し、ツリー行だけを縦スクロールさせる。

### Reason

時刻、イベント密度、現在の階層コンテキストを同時に保つことで、長いstream/flowツリーの調査中も時刻軸との対応を失わない。

### Consequences

時間軸はスクロール中も行マーカーより前面に描画される。軸上のイベント一覧ポップオーバーも固定軸を基準に表示され、API、スクロール位置、virtualizationの計算は変更しない。

---

## 2026-09-15: TimelineとStreamsのツリー制御表現

### Context

TimelineとStreamsは同じNIC、scope、protocol、stream、flow階層を表示するが、Timelineの開閉ボタンには既定buttonの枠が残り、展開できないflowは空白だった。画面間でツリーの制御列を見比べると、ノードの種類を同じように読み取れなかった。

### Decision

Timelineの開閉ボタンはStreamsと同様に枠なし・透明背景のアイコン操作とする。flowなど開閉できない末端行では、同じ22px制御列へ7pxのアウトライン円を表示する。hover/focus時のaccent背景と色変化は開閉可能なアイコンだけに適用する。

### Reason

制御列の幅と末端記号を揃えることで、階層の深さと展開可能性を画面間で一貫して認識できる。末端行のラベル開始位置も開閉可能なstreamと揃う。

### Consequences

Timelineの既存の開閉状態、アニメーション、イベントマーカー、アクセシブルなbuttonラベルは変更しない。末端円は装飾であり、操作対象ではない。

---

## 2026-09-15: Timelineツリーの開閉アニメーション

### Context

Timelineの階層行は仮想スクロールで必要な行だけを描画する。ツリーの展開・折りたたみが即時に切り替わると、対象階層が多い場合に視線が追従しづらい。一方で、スクロール時までアニメーションすると監視中の操作性を損なう。

### Decision

利用者の明示的なツリー開閉に限り、親の直接の子行を展開時160ms、折りたたみ時140msでフェードと4pxの縦移動により遷移させる。折りたたみでは子行の操作を無効化してからアニメーション終了時に状態を閉じる。既存の開閉アイコン回転を維持する。

仮想スクロールによる行のマウント、データ更新、Show targetによる自動展開にはこのアニメーションを適用しない。OSの`prefers-reduced-motion: reduce`指定時は開閉とアイコン遷移を即時にする。

### Reason

階層の増減だけを短く示すことで視線を保ち、仮想化された一覧のスクロールやLive更新へ不要な描画負荷・動きを持ち込まない。

