.timeline-event-step-controls {
  display: inline-flex;
  gap: 2px;
}

.timeline-event-step {
  min-width: 28px;
  min-height: 18px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text-strong);
  font-size: 10px;
  line-height: 1;
}

.timeline-event-step:disabled {
  opacity: .45;
}

.timeline-event-rail {
  position: relative;
  min-width: 0;
  height: 22px;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--surface) 92%, var(--surface-muted));
}

.timeline-event-rail .timeline-cursor-line {
  z-index: 4;
}

.timeline-event-marker {
  position: absolute;
  z-index: 5;
  top: 3px;
  width: 16px;
  height: 16px;
  min-height: 16px;
  padding: 0;
  transform: translateX(-50%);
  border: 1px solid currentColor;
  border-radius: 50%;
  background: var(--surface-raised);
  color: var(--warning);
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.timeline-event-marker.error {
  color: var(--danger);
}

.timeline-event-marker.selected {
  outline: 2px solid color-mix(in srgb, var(--accent) 72%, transparent);
  outline-offset: 1px;
  background: var(--surface);
}

.timeline-event-marker:hover,
.timeline-event-marker:focus-visible {
  z-index: 6;
  transform: translateX(-50%) scale(1.15);
  background: var(--surface);
}

/* A compact event list is only opened for a time bucket containing multiple events. */

.timeline-event-bucket-reveal {
  align-self: center;
  min-height: 24px;
  margin-right: var(--space-2);
  padding: 0 var(--space-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--accent);
  font-size: var(--font-size-xs);
  white-space: nowrap;
}

/* A row marker has a forgiving hit area while keeping the visual signal a thin tick. */
.timeline-row-event-marker {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 12px;
  min-height: 0;
  padding: 0;
  transform: translateX(-50%);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--warning);
}

.timeline-row-event-marker::before {
  position: absolute;
  top: 5px;
  bottom: 5px;
  left: 50%;
  width: 3px;
  content: "";
  transform: translateX(-50%);
  background: currentColor;
}

.timeline-row-event-marker.error {
  color: var(--danger);
}

.timeline-row-event-marker.selected::before {
  width: 5px;
  box-shadow: 0 0 0 1px var(--surface), 0 0 0 2px color-mix(in srgb, var(--accent) 72%, transparent);
}

.timeline-row-event-marker:hover,
.timeline-row-event-marker:focus-visible {
  z-index: 5;
  outline: 0;
}

.timeline-row-event-marker:hover::before,
.timeline-row-event-marker:focus-visible::before {
  top: 3px;
  bottom: 3px;
  width: 5px;
}

