function TimelineRowEventMarkers({ buckets, range, selectedEventId, onSelectEvent }: {
  buckets: EventMarkerBucket[];
  range: { start: number; end: number };
  selectedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
}) {
  return <>{buckets.map((bucket) => {
    const selected = bucket.events.some((event) => event.id === selectedEventId);
    const label = eventMarkerLabel(bucket);
    return <button
      key={bucket.key}
      type="button"
      className={`timeline-row-event-marker ${bucket.level}${selected ? " selected" : ""}`}
      style={{ left: `${percent(bucket.time, range.start, range.end)}%` }}
      title={label}
      aria-label={label}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => { event.stopPropagation(); onSelectEvent(bucket); }}
    />;
  })}</>;
}

function TimelineCountBadge({ count }: { count: number }) {
  return <span className="timeline-count-badge">{count}</span>;
}
function TimelineGapBands({ gaps, range, label = false }: { gaps: TimelineDataGap[]; range: { start: number; end: number }; label?: boolean }) {
  return <>{gaps.map((gap) => {
    const from = Math.max(range.start, gap.from);
    const to = Math.min(range.end, gap.to);
    if (to <= from) return null;
    const start = percent(from, range.start, range.end);
    const end = percent(to, range.start, range.end);
    return <div key={`${gap.reason}:${from}:${to}`} className="timeline-gap-band" style={{ left: `${start}%`, width: `${Math.max(0.4, end - start)}%` }} title="Monitoring data unavailable" aria-label={label ? "Monitoring data unavailable" : undefined} />;
  })}</>;
}


.timeline-event-bucket-reveal {
  align-self: center;
  min-height: 24px;
  margin-right: var(--space-2);
  padding: 0 var(--space-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--accent);
  font-size: var(--font-size-xs);
  white-space: nowrap;
}

/* A row marker has a forgiving hit area while keeping the visual signal a thin tick. */
.timeline-row-event-marker {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 12px;
  min-height: 0;
  padding: 0;
  transform: translateX(-50%);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--warning);
}

.timeline-row-event-marker::before {
  position: absolute;
  top: 5px;
  bottom: 5px;
