import { Fragment, forwardRef, useEffect, useMemo, useRef, useState } from "react";
import type { EventLogItem, NetworkScope, TimelineDataGap, TimelineRow } from "../types/api";
import { Icon } from "./ui/Icon";

type TimelinePaneProps = {
  rows: TimelineRow[];
  gaps?: TimelineDataGap[];
  nowSec: number;
  fadeSec: number;
  rangeStartSec: number;
  rangeEndSec: number;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  onPanBySec?: (deltaSec: number) => void;
  onZoom?: (direction: "in" | "out") => void;
  events?: EventLogItem[];
  selectedEventId?: string | null;
  onSelectEvent?: (event: EventLogItem) => void;
  interfaceNames?: ReadonlyMap<number, string>;
};

type TimelineStreamGroup = { stream: TimelineRow; flows: TimelineRow[] };
type TimelineEventLane = { key: string; eventTargetKeys: string[] };
type TimelineTreeAnimation = { parentKey: string; phase: "enter" | "leave" };
type TimelineScopeGroup = {
  key: string;
  label: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};
type TimelineProtoGroup = {
  key: string;
  proto: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};

type TimelineTreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

function TimelineTreeGuideLines({ guide }: { guide: TimelineTreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);

  return <span className="timeline-tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`timeline-tree-guide-line timeline-tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`timeline-tree-guide-line timeline-tree-guide-depth-${guide.depth} timeline-tree-guide-${segment}`} />)}
  </span>;
}

export function TimelinePane({ rows, gaps = [], nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, onPanBySec, onZoom, events = [], selectedEventId = null, onSelectEvent, interfaceNames }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [scopeExpanded, setScopeExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
  const [treeAnimation, setTreeAnimation] = useState<TimelineTreeAnimation | null>(null);
  const [eventBucketPopover, setEventBucketPopover] = useState<EventMarkerBucket | null>(null);
  const [pendingRevealRowKey, setPendingRevealRowKey] = useState<string | null>(null);
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<HTMLDivElement | null>(null);
  const eventPopoverRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);
  const [isScrubbing, setIsScrubbing] = useState(false);
  const [hoveredRowKey, setHoveredRowKey] = useState<string | null>(null);
  const [viewport, setViewport] = useState({ top: 0, height: 480 });
  const [axisWidth, setAxisWidth] = useState(0);
  const cursorRafRef = useRef<number | null>(null);
  const treeAnimationTimerRef = useRef<number | null>(null);
  const pendingCursorXRef = useRef<number | null>(null);
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);
  const scrubPointerIdRef = useRef<number | null>(null);
  const skipNextTimeSelectRef = useRef(false);
  const panStartXRef = useRef<number | null>(null);
  const panLastXRef = useRef<number | null>(null);
  const hasPannedRef = useRef(false);
  const zoomHandlerRef = useRef(onZoom);
  const [isPointerInside, setIsPointerInside] = useState(false);
  const [isCtrlPressed, setIsCtrlPressed] = useState(false);
  zoomHandlerRef.current = onZoom;

  const toggleTimelineTree = (parentKey: string, isExpanded: boolean, update: () => void) => {
    if (treeAnimation) return;
    if (treeAnimationTimerRef.current !== null) window.clearTimeout(treeAnimationTimerRef.current);
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setTreeAnimation(null);
      update();
      return;
    }
    if (isExpanded) {
      setTreeAnimation({ parentKey, phase: "leave" });
      treeAnimationTimerRef.current = window.setTimeout(() => {
        update();
        setTreeAnimation(null);
        treeAnimationTimerRef.current = null;
      }, 140);
      return;
    }
    update();
    setTreeAnimation({ parentKey, phase: "enter" });
    treeAnimationTimerRef.current = window.setTimeout(() => {
      setTreeAnimation(null);
      treeAnimationTimerRef.current = null;
    }, 160);
  };

  useEffect(() => {
    const updateCtrlState = (event: KeyboardEvent) => {
      if (event.key === "Control") setIsCtrlPressed(event.type === "keydown");
    };
    window.addEventListener("keydown", updateCtrlState);
    window.addEventListener("keyup", updateCtrlState);
    return () => {
      window.removeEventListener("keydown", updateCtrlState);
      window.removeEventListener("keyup", updateCtrlState);
    };
  }, []);

  useEffect(() => {
    const axis = axisScaleRef.current;
    if (!axis) return;
    const update = () => setAxisWidth(axis.clientWidth);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(axis);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!isHoveringCursor) {
      setCursorSec(Math.min(rangeEndSec, Math.max(rangeStartSec, nowSec)));
    }
  }, [isHoveringCursor, nowSec, rangeStartSec, rangeEndSec]);

  const updateCursor = (clientX: number) => {
    const time = timeFromClientX(clientX);
    if (time !== null) setCursorSec(time);
  };

  const timeFromClientX = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return null;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return null;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
    return Math.round(range.start + ratio * (range.end - range.start));
  };

  const panFromClientX = (clientX: number) => {
    const startX = panStartXRef.current;
    const lastX = panLastXRef.current;
    const axis = axisScaleRef.current;
    if (startX === null || lastX === null || !axis || axis.clientWidth <= 0) return false;
    if (!hasPannedRef.current && Math.abs(clientX - startX) < 4) return false;
    hasPannedRef.current = true;
    const deltaSec = -((clientX - lastX) / axis.clientWidth) * (range.end - range.start);
    panLastXRef.current = clientX;
    if (deltaSec !== 0) onPanBySec?.(deltaSec);
    return true;
  };

  useEffect(() => {
    setExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (row.rowType !== "stream") continue;
        if (!(row.streamKey in next)) {
          next[row.streamKey] = expandLevel === "flow";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel, interfaceNames]);

  useEffect(() => {
    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = interfaceLabel(row, interfaceNames);
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
