.timeline-pane {
  padding: 0;
  border-top: 0;
  background: var(--surface);
}

.timeline-header {
  min-height: var(--pane-header-height);
  align-items: center;
  margin: 0;
  padding: 0 var(--space-2);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-header h3 {
  font-size: var(--font-size-sm);
}

.timeline-browse-controls {
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
}

.timeline-browse-controls button {
  min-width: 48px;
  height: 24px;
  min-height: 24px;
  padding: 0 7px;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-browse-controls button.active {
  border: 0;
  background: var(--accent-soft);
  color: var(--accent);
}

.timeline-body {
  border: 0;
  border-radius: 0;
  background:
    linear-gradient(90deg, var(--chart-grid) 1px, transparent 1px) 0 0 / 96px 100%,
    linear-gradient(var(--chart-grid) 1px, transparent 1px) 0 0 / 100% 30px,
    var(--surface);
  padding: 0 var(--space-2);
}

.timeline-axis {
  gap: var(--space-2);
  padding: 4px 0;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-axis-tick,
.timeline-cursor-label {
  font-size: var(--font-size-xs);
}

.timeline-cursor-label {
  padding: 2px 5px;
  border-color: var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  gap: var(--space-2);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
}

.timeline-interface-header,
.timeline-proto-row {
  min-height: 30px;
  background: var(--surface-muted);
}

.timeline-row {
  min-height: 30px;
  border-radius: 0;
  background: transparent;
}

.timeline-row:hover,
.timeline-row-hovered {
  background: var(--surface-muted);
}

.timeline-row-cursor-focused {
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
}

.timeline-row-label strong,
.timeline-interface-label strong,
.timeline-proto-label strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
}

.timeline-row-label span,
.timeline-interface-label span,
.timeline-proto-label span {
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-toggle {
  display: grid;
  place-items: center;
  width: 22px;
  min-height: 22px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.timeline-toggle:hover {
  background: var(--accent-soft);
  color: var(--accent);
}

.timeline-leaf-marker {
  display: grid;
  place-items: center;
  width: 22px;
  min-height: 22px;
  pointer-events: none;
}

.timeline-leaf-marker::before {
  width: 7px;
  height: 7px;
  box-sizing: border-box;
  border: 1px solid color-mix(in srgb, var(--muted) 72%, transparent);
  border-radius: 50%;
  content: "";
}

.timeline-row-track,
.timeline-interface-track,
.timeline-proto-track {
  background: transparent;
}

.timeline-segment,
.timeline-segment.active,
.timeline-segment.timeline-segment-stream,
.timeline-segment.timeline-segment-flow,
.timeline-segment.timeline-segment-interface,
.timeline-segment.timeline-segment-proto {
  border-radius: 0;
  box-shadow: none;
}

.timeline-segment.active.timeline-segment-stream,
.timeline-segment.active.timeline-segment-proto {
  background: color-mix(in srgb, var(--accent) 62%, transparent);
}

.timeline-segment.active.timeline-segment-flow {
  background: color-mix(in srgb, var(--accent-2) 60%, transparent);
}

.timeline-segment.active.timeline-segment-interface {
  background: color-mix(in srgb, var(--success) 48%, transparent);
}

.timeline-cursor-line {
  background: var(--accent);
  opacity: .78;
}

/* Keep the grid in the chart content so it scrolls together with timeline rows. */
.timeline-body {
  background: var(--surface);
}

.timeline-chart {
  --timeline-label-width: clamp(196px, 24vw, 320px);
  gap: 0;
  background:
    linear-gradient(90deg, var(--chart-grid) 1px, transparent 1px) var(--timeline-label-width) 0 / 96px 100%,
    linear-gradient(var(--chart-grid) 1px, transparent 1px) 0 0 / 100% 32px,
    var(--surface);
}

.timeline-chart .timeline-axis-scale,
.timeline-chart .timeline-row-track {
  cursor: grab;
}

.timeline-chart.is-time-scrubbing,
.timeline-chart.is-time-scrubbing .timeline-axis-scale,
.timeline-chart.is-time-scrubbing .timeline-row-track {
  cursor: grabbing;
  user-select: none;
}

.timeline-chart.is-zoom-mode,
.timeline-chart.is-zoom-mode .timeline-axis-scale,
.timeline-chart.is-zoom-mode .timeline-row-track {
  cursor: url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 width=%2724%27 height=%2724%27 viewBox=%270 0 24 24%27%3E%3Cpath d=%27M4 5v14M20 5v14M7 12h10M10 9l-3 3 3 3M14 9l3 3-3 3%27 fill=%27none%27 stroke=%27%23111%27 stroke-width=%272%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27/%3E%3C/svg%3E") 12 12, col-resize;
}

.timeline-axis,
.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  grid-template-columns: var(--timeline-label-width) minmax(0, 1fr);
  gap: var(--space-2);
}

.timeline-interface-header,
.timeline-proto-row {
  min-height: 32px;
  background: transparent;
}

.timeline-row {
  min-height: 42px;
  height: 100%;
}

.timeline-interface-label,
.timeline-proto-label,
.timeline-row-label,
.timeline-axis-label {
  min-width: 0;
  align-self: stretch;
  padding: 0 var(--space-2);
  border-right: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
  background: color-mix(in srgb, var(--surface-muted) 88%, var(--surface));
