@media (max-width: 900px) { .stream-table .interface-row, .stream-table .scope-row, .stream-table .proto-row { grid-template-columns: 20px 10px minmax(0, 1fr); } .stream-table .stream-row { grid-template-columns: 20px 10px minmax(0, 1fr) 28px; } .stream-table .flow-list-row { grid-template-columns: 10px minmax(0, 1fr) 28px; } .stream-table .flow-list-row .flow-main { grid-column: 2; } .stream-table .stream-row .row-action-menu { grid-column: 4; } .stream-table .flow-list-row .row-action-menu { grid-column: 3; } .stream-table .row-right, .stream-table .interface-sparklines { display: none; } }

.stream-table .stream-row.selected,
.stream-table .flow-list-row.selected {
  background: var(--accent-soft);
/*  box-shadow: inset 3px 0 0 var(--accent);*/
  box-shadow: inset 4px 0 0 var(--accent);
}

.stream-table .row-action-menu { position: relative; display: grid; place-items: center; width: 28px; height: 28px; }
.stream-table .row-action-trigger { display: grid; place-items: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--muted); cursor: pointer; }
.stream-table .row-action-trigger:hover, .stream-table .row-action-trigger:focus-visible { background: var(--accent-soft); color: var(--accent); outline: none; }
.stream-table .row-action-popup { position: absolute; top: calc(100% + 2px); right: 0; z-index: 12; display: grid; min-width: 176px; padding: 4px 0; border: 1px solid var(--line); background: var(--surface-raised); box-shadow: var(--popover-shadow); }
.stream-table .row-action-popup button { padding: 7px 10px; border: 0; background: transparent; color: var(--text); text-align: left; white-space: nowrap; cursor: pointer; }
.stream-table .row-action-popup button:hover, .stream-table .row-action-popup button:focus-visible { background: var(--accent-soft); color: var(--accent); outline: none; }

.stream-sticky-context-anchor { position: sticky; top: 0; z-index: 4; height: 0; pointer-events: none; }
.stream-sticky-context { position: absolute; inset: 0 0 auto; height: 32px; display: flex; align-items: center; min-width: 0; padding: 0 10px; overflow: hidden; border-bottom: 1px solid var(--line); background: var(--surface-raised); color: var(--muted); font-size: var(--font-size-xs); visibility: hidden; pointer-events: none; }
.stream-sticky-context.is-visible { visibility: visible; }
.stream-context-segment { display: inline-flex; align-items: center; min-width: 0; flex: 0 1 auto; }
.stream-context-segment:last-child { flex: 1 1 auto; }
.stream-context-separator { flex: 0 0 auto; margin: 0 5px; color: color-mix(in srgb, var(--muted) 58%, transparent); font-size: 14px; line-height: 1; }
.stream-context-chip { display: block; pointer-events: auto; min-width: 0; max-width: 220px; overflow: hidden; padding: 3px 7px; border: 1px solid transparent; border-radius: var(--radius-md); color: var(--text); font-size: var(--font-size-xs); font-weight: 600; line-height: 1.2; text-overflow: ellipsis; white-space: nowrap; }
.stream-context-segment:last-child .stream-context-chip { max-width: none; }
.stream-context-interface { border-color: color-mix(in srgb, var(--accent-2) 28%, var(--line)); background: color-mix(in srgb, var(--accent-2) 10%, var(--surface)); color: color-mix(in srgb, var(--accent-2) 74%, var(--text)); }
.stream-context-scope { border-color: color-mix(in srgb, var(--chart-metric-rttvar) 28%, var(--line)); background: color-mix(in srgb, var(--chart-metric-rttvar) 10%, var(--surface)); color: color-mix(in srgb, var(--chart-metric-rttvar) 74%, var(--text)); }
.stream-context-proto { border-color: color-mix(in srgb, var(--protocol-default) 28%, var(--line)); background: color-mix(in srgb, var(--protocol-default) 10%, var(--surface)); color: color-mix(in srgb, var(--protocol-default) 74%, var(--text)); }
.stream-context-proto-rtp { border-color: color-mix(in srgb, var(--protocol-rtp) 28%, var(--line)); background: color-mix(in srgb, var(--protocol-rtp) 10%, var(--surface)); color: color-mix(in srgb, var(--protocol-rtp) 74%, var(--text)); }
.stream-context-proto-srt { border-color: color-mix(in srgb, var(--protocol-srt) 28%, var(--line)); background: color-mix(in srgb, var(--protocol-srt) 10%, var(--surface)); color: color-mix(in srgb, var(--protocol-srt) 74%, var(--text)); }
.stream-context-proto-hls { border-color: color-mix(in srgb, var(--protocol-hls) 28%, var(--line)); background: color-mix(in srgb, var(--protocol-hls) 10%, var(--surface)); color: color-mix(in srgb, var(--protocol-hls) 74%, var(--text)); }
.stream-context-stream { border-color: var(--accent-border); background: color-mix(in srgb, var(--accent) 14%, var(--surface)); color: var(--accent); font-weight: 700; }



/* Keep the NIC link state beside the name without competing with the stream count. */
.stream-table .interface-link-summary {
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label">
          {stickyContext.length > 0 ? (
            <div className="timeline-sticky-context" aria-label="Current timeline hierarchy">{stickyContext.map((item, index) => <span className="stream-context-segment" key={`${item.kind}:${item.label}:${index}`}>
              {index > 0 && <span className="stream-context-separator" aria-hidden="true">›</span>}
              <span className={`stream-context-chip stream-context-${item.kind}${item.kind === "proto" ? " stream-context-proto-" + timelineContextProtoClass(item.proto) : ""}`} title={item.title ?? item.label}>{item.label}</span>
            </span>)}</div>
          ) : null}
        </div>
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <TimelineGapBands gaps={gaps} range={range} label />
          <div className={"timeline-cursor-label" + (cursorPercent <= 5 ? " is-at-start" : cursorPercent >= 95 ? " is-at-end" : "")} style={{ left: String(clampPercent(cursorPercent)) + "%" }} title={cursorLabel}>
            {cursorLabel}
          </div>
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
        <div className="timeline-event-rail-label">
          <span>Events</span>
          <div className="timeline-event-step-controls">
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(-1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === 0} aria-label="Previous warning or error event" title="Previous event">Prev</button>
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === markerEvents.length - 1} aria-label="Next warning or error event" title="Next event">Next</button>
          </div>
        </div>
        <TimelineEventRail buckets={eventRailBuckets} gaps={gaps} range={range} cursorPercent={clampPercent(cursorPercent)} selectedEventId={selectedEventId} activeBucketEventIds={activeBucketEventIds} previewedEventId={previewedEventId} onActivateBucket={activateTimelineEventBucket} />
        {eventBucketPopover ? <TimelineEventBucketPopover ref={eventPopoverRef} bucket={eventBucketPopover} onClose={() => { setEventBucketPopover(null); setPreviewedEventId(null); }} onPreviewEvent={setPreviewedEventId} onSelectEvent={selectTimelineEvent} canRevealEvent={canRevealTimelineEvent} onRevealEvent={(event) => { revealTimelineEvent(event); selectTimelineEvent(event); }} /> : null}
      </div>
      <div className="timeline-rows">
        <TimelineTimeGrid ticks={range.ticks} range={range} />
        {virtualized.topPad > 0 ? <div style={{ height: virtualized.topPad }} /> : null}
        {virtualized.visible.map((item) => {
          const itemAnimation = treeAnimation?.parentKey === item.parentKey ? treeAnimation : null;
          const animationClass = itemAnimation ? " timeline-tree-" + itemAnimation.phase : "";
          if (item.type === "interface") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineInterfaceLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={interfaceExpanded[item.group.key] ?? true}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={() => toggleTimelineTree(item.key, interfaceExpanded[item.group.key] ?? true, () => setInterfaceExpanded((current) => ({ ...current, [item.group.key]: !(current[item.group.key] ?? true) })))}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  activeBucketEventIds={activeBucketEventIds}
                  previewedEventId={previewedEventId}
                  onSelectEvent={activateTimelineEventBucket}

