item.stdout:
.timeline-pane {
  padding: 0;
  border-top: 0;
  background: var(--surface);
}

.timeline-header {
  min-height: var(--pane-header-height);
  align-items: center;
  margin: 0;
  padding: 0 var(--space-2);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-header h3 {
  font-size: var(--font-size-sm);
}

.timeline-browse-controls {
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
}

.timeline-browse-controls button {
  min-width: 48px;
  height: 24px;
  min-height: 24px;
  padding: 0 7px;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-browse-controls button.active {
  border: 0;
  background: var(--accent-soft);
  color: var(--accent);
}

.timeline-body {
  border: 0;
  border-radius: 0;
  background:
    linear-gradient(90deg, var(--chart-grid) 1px, transparent 1px) 0 0 / 96px 100%,
    linear-gradient(var(--chart-grid) 1px, transparent 1px) 0 0 / 100% 30px,
    var(--surface);
  padding: 0 var(--space-2);
}

.timeline-axis {
  gap: var(--space-2);
  padding: 4px 0;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-axis-tick,
.timeline-cursor-label {
  font-size: var(--font-size-xs);
}

.timeline-cursor-label {
  padding: 2px 5px;
  border-color: var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  gap: var(--space-2);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
}

.timeline-interface-header,
.timeline-proto-row {
  min-height: 30px;
  background: var(--surface-muted);
}

.timeline-row {
  min-height: 30px;
  border-radius: 0;
  background: transparent;
}

}

.timeline-row-label > span:not(.timeline-label-text) {
  display: none;
}

.timeline-interface-header.timeline-row-hovered,
.timeline-proto-row.timeline-row-hovered,
.timeline-row.timeline-row-hovered,
.timeline-interface-header.timeline-row-cursor-focused,
.timeline-proto-row.timeline-row-cursor-focused,
.timeline-row.timeline-row-cursor-focused {
  background: var(--surface-muted);
  border-radius: 0;
  box-shadow: none;
}

.timeline-interface-header.timeline-row-hovered .timeline-interface-label,
.timeline-proto-row.timeline-row-hovered .timeline-proto-label,
.timeline-row.timeline-row-hovered .timeline-row-label,
.timeline-interface-header.timeline-row-cursor-focused .timeline-interface-label,
.timeline-proto-row.timeline-row-cursor-focused .timeline-proto-label,
.timeline-row.timeline-row-cursor-focused .timeline-row-label {
  background: var(--surface-muted);
}

/* Horizontal separators come only from the actual row boundaries. */
.timeline-chart {
  background: var(--surface);
}

.timeline-rows {
  position: relative;
}

.timeline-time-grid {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: calc(var(--timeline-label-width) + var(--space-2));
  z-index: 0;
  pointer-events: none;
}

.timeline-time-grid-line {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--chart-grid);
}

.timeline-rows > :not(.timeline-time-grid) {
  position: relative;
  z-index: 1;
}

/* Allow endpoint labels to remain readable over the chart area. */
.timeline-row-label {
  position: relative;
  z-index: 3;
  overflow: visible;
}

