function timelineTickStepSec(rangeSec: number) {
  const target = Math.max(0.001, rangeSec / 4);
  if (target > TIME_TICK_STEPS_SEC[TIME_TICK_STEPS_SEC.length - 1]) return niceTimeStepSec(target);
  return TIME_TICK_STEPS_SEC.reduce((nearest, step) => {
    return Math.abs(Math.log(step / target)) < Math.abs(Math.log(nearest / target)) ? step : nearest;
  }, TIME_TICK_STEPS_SEC[0]);
}

function buildTimelineTicks(start: number, end: number, step: number) {
  const first = Math.ceil(start / step - 1e-9) * step;
  const ticks: number[] = [];
  for (let index = 0, tick = first; tick <= end + step * 1e-6; index += 1, tick = first + index * step) {
    ticks.push(Math.round(tick * 1000) / 1000);
  }
  return ticks;
}

function timelineEventTargetKey(event: EventLogItem) {
  if (event.flowKey) return `flow:${event.flowKey}`;
  if (event.streamKey) return `stream:${event.streamKey}`;
  return undefined;
}

function timelineRowEventTargetKey(row: TimelineRow) {
  if (row.rowType === "flow") return `flow:${row.flowKey ?? row.streamKey}`;
  return `stream:${row.streamKey}`;
}

function timelineEventTargetKeys(rows: TimelineStreamGroup[]) {
  const keys = new Set<string>();
  for (const { stream, flows } of rows) {
    keys.add(timelineRowEventTargetKey(stream));
    for (const flow of flows) keys.add(timelineRowEventTargetKey(flow));
  }
  return [...keys];
}

function buildVisibleTimelineEventBuckets(events: EventLogItem[], range: { start: number; end: number }, lanes: TimelineEventLane[]) {
  const laneByTarget = new Map<string, string>();
  for (const lane of lanes) {
    for (const targetKey of lane.eventTargetKeys) laneByTarget.set(targetKey, lane.key);
  }

  const eventsByLane = new Map<string, EventLogItem[]>();
  for (const event of events) {
    const targetKey = timelineEventTargetKey(event);
    const laneKey = targetKey
      ? laneByTarget.get(targetKey) ?? (event.flowKey && event.streamKey ? laneByTarget.get(`stream:${event.streamKey}`) : undefined)
      : undefined;
    if (!laneKey) continue;
    const laneEvents = eventsByLane.get(laneKey) ?? [];
    laneEvents.push(event);
    eventsByLane.set(laneKey, laneEvents);
  }
  return new Map([...eventsByLane.entries()].map(([laneKey, laneEvents]) => [laneKey, buildEventMarkerBuckets(laneEvents, range)]));
}

function eventSeverityRank(event: EventLogItem) {
  return event.level === "error" ? 2 : event.level === "warn" ? 1 : 0;
}

function eventMarkerLabel(bucket: EventMarkerBucket) {
  const count = bucket.events.length;
  const primary = bucket.primary;
  const target = primary.targetLabel ?? primary.flowKey ?? primary.streamKey ?? "System";
  return [
    count > 1 ? String(count) + " warning or error events; selected event:" : undefined,
    formatEventTime(primary.time),
    primary.level.toUpperCase() + ": " + primary.message,
    "Target: " + target
  ].filter((value): value is string => Boolean(value)).join("\n");
}

function findPreviousEventIndex(events: EventLogItem[], time: number) {
  for (let index = events.length - 1; index >= 0; index -= 1) {
    if (events[index].time < time) return index;
  }
  return -1;
}

