  onSelectEvent,
  onInspectTarget
}: {
  rowKey: string;
  row: TimelineRow;
  treeLevel: number;
  range: { start: number; end: number };
  cursorPercent: number;
  gaps: TimelineDataGap[];
  cursorSec: number;
  fadeSec: number;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  childCount?: number;
  expanded?: boolean;
  onToggle?: () => void;
  eventBuckets: EventMarkerBucket[];
  selectedEventId: string | null;
  activeBucketEventIds: ReadonlySet<string>;
  previewedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
  onInspectTarget?: (row: TimelineRow) => void;
}) {
  const focused = row.segments.some((segment) => {
    const end = segment.end ?? range.end;
    return cursorSec >= segment.start && cursorSec <= end;
  });
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";

  return (
    <div
      className={`timeline-row ${row.rowType === "flow" ? "timeline-row-flow" : "timeline-row-stream"} timeline-tree-level-${treeLevel}${focusClass}`}
      onPointerEnter={() => onHoverChange(rowKey)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-row-label" data-tooltip={row.flowKey ?? row.streamKey}>
        <strong>
          {onToggle ? (
            <button type="button" className={"timeline-toggle" + (expanded ? " open" : "")} onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label={expanded ? "Collapse flow rows" : "Expand flow rows"}>
