          setCursorSec(Math.min(range.end, Math.max(range.start, nowSec)));
        }}
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label">
          {stickyContext.length > 0 ? (
            <div className="timeline-sticky-context" aria-label="Current timeline hierarchy">{stickyContext.map((item, index) => <span className="stream-context-segment" key={`${item.kind}:${item.label}:${index}`}>
              {index > 0 && <span className="stream-context-separator" aria-hidden="true">›</span>}
              <span className={`stream-context-chip stream-context-${item.kind}${item.kind === "proto" ? " stream-context-proto-" + timelineContextProtoClass(item.proto) : ""}`} data-tooltip={item.title ?? item.label}>{item.label}</span>
