            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(-1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === 0} aria-label="Previous warning or error event" data-tooltip-key="tooltip.previousEvent">Prev</button>
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === markerEvents.length - 1} aria-label="Next warning or error event" data-tooltip-key="tooltip.nextEvent">Next</button>
          </div>
