import { Fragment, forwardRef, useEffect, useMemo, useRef, useState } from "react";
import type { EventLogItem, NetworkScope, TimelineDataGap, TimelineRow } from "../types/api";
import { Icon } from "./ui/Icon";

type TimelinePaneProps = {
  rows: TimelineRow[];
  gaps?: TimelineDataGap[];
  nowSec: number;
  fadeSec: number;
  rangeStartSec: number;
  rangeEndSec: number;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  onPanBySec?: (deltaSec: number) => void;
  onZoom?: (direction: "in" | "out") => void;
  events?: EventLogItem[];
  selectedEventId?: string | null;
  onSelectEvent?: (event: EventLogItem) => void;
  onInspectTarget?: (row: TimelineRow) => void;
  interfaceNames?: ReadonlyMap<number, string>;
};

type TimelineStreamGroup = { stream: TimelineRow; flows: TimelineRow[] };
type TimelineEventLane = { key: string; eventTargetKeys: string[] };
type TimelineDisplayGroup = { key: string; label: string; confidence?: "confirmed" | "heuristic"; rows: TimelineStreamGroup[]; grouped: boolean };
type TimelineTreeAnimation = { parentKey: string; phase: "enter" | "leave" };
type TimelineScopeGroup = {
  key: string;
  label: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};
type TimelineProtoGroup = {
  key: string;
  proto: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};

type TimelineTreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

type TimelineStickyContextItem = {
  kind: "interface" | "scope" | "proto" | "stream";
  label: string;
  proto?: string;
  title?: string;
};

function TimelineTreeGuideLines({ guide }: { guide: TimelineTreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);

  return <span className="timeline-tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`timeline-tree-guide-line timeline-tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`timeline-tree-guide-line timeline-tree-guide-depth-${guide.depth} timeline-tree-guide-${segment}`} />)}
  </span>;
}

export function TimelinePane({ rows, gaps = [], nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, onPanBySec, onZoom, events = [], selectedEventId = null, onSelectEvent, onInspectTarget, interfaceNames }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [scopeExpanded, setScopeExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
  const [treeAnimation, setTreeAnimation] = useState<TimelineTreeAnimation | null>(null);
  const [eventBucketPopover, setEventBucketPopover] = useState<EventMarkerBucket | null>(null);
  const [previewedEventId, setPreviewedEventId] = useState<string | null>(null);
  const [pendingRevealRowKey, setPendingRevealRowKey] = useState<string | null>(null);
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<HTMLDivElement | null>(null);
  const eventPopoverRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);
  const [isScrubbing, setIsScrubbing] = useState(false);
  const [hoveredRowKey, setHoveredRowKey] = useState<string | null>(null);
  const [viewport, setViewport] = useState({ top: 0, height: 480 });
  const [axisWidth, setAxisWidth] = useState(0);
  const cursorRafRef = useRef<number | null>(null);
  const treeAnimationTimerRef = useRef<number | null>(null);
  const pendingCursorXRef = useRef<number | null>(null);
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);
  const scrubPointerIdRef = useRef<number | null>(null);
  const skipNextTimeSelectRef = useRef(false);
  const panStartXRef = useRef<number | null>(null);
  const panLastXRef = useRef<number | null>(null);
  const hasPannedRef = useRef(false);
  const zoomHandlerRef = useRef(onZoom);
  const [isPointerInside, setIsPointerInside] = useState(false);
  const [isCtrlPressed, setIsCtrlPressed] = useState(false);
  zoomHandlerRef.current = onZoom;

  const toggleTimelineTree = (parentKey: string, isExpanded: boolean, update: () => void) => {
    if (treeAnimation) return;
    if (treeAnimationTimerRef.current !== null) window.clearTimeout(treeAnimationTimerRef.current);
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setTreeAnimation(null);
      update();
      return;
    }
    if (isExpanded) {
      setTreeAnimation({ parentKey, phase: "leave" });
      treeAnimationTimerRef.current = window.setTimeout(() => {
        update();
        setTreeAnimation(null);
        treeAnimationTimerRef.current = null;
            const selected = timeFromClientX(event.clientX);
            if (selected !== null) {
              setCursorSec(selected);
              onSelectTime?.(selected);
            }
          }
          skipNextTimeSelectRef.current = true;
          setIsScrubbing(false);
        }}
        onPointerCancel={(event) => {
          if (scrubPointerIdRef.current !== event.pointerId) return;
          scrubPointerIdRef.current = null;
          panStartXRef.current = null;
          panLastXRef.current = null;
          hasPannedRef.current = false;
          setIsScrubbing(false);
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, selectedTimeSec ?? nowSec)));
        }}
        onPointerLeave={() => {
          setIsPointerInside(false);
          setIsCtrlPressed(false);
          if (scrubPointerIdRef.current !== null) return;
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, nowSec)));
        }}
      >
      <div className="timeline-axis">
        <div className="timeline-axis-label">
          {stickyContext.length > 0 ? (
            <div className="timeline-sticky-context" aria-label="Current timeline hierarchy">{stickyContext.map((item, index) => <span className="stream-context-segment" key={`${item.kind}:${item.label}:${index}`}>
              {index > 0 && <span className="stream-context-separator" aria-hidden="true">›</span>}
              <span className={`stream-context-chip stream-context-${item.kind}${item.kind === "proto" ? " stream-context-proto-" + timelineContextProtoClass(item.proto) : ""}`} data-tooltip={item.title ?? item.label}>{item.label}</span>
            </span>)}</div>
          ) : null}
        </div>
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <TimelineGapBands gaps={gaps} range={range} label />
          <div className={"timeline-cursor-label" + (cursorPercent <= 5 ? " is-at-start" : cursorPercent >= 95 ? " is-at-end" : "")} style={{ left: String(clampPercent(cursorPercent)) + "%" }} data-tooltip={cursorLabel}>
            {cursorLabel}
          </div>
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
        <div className="timeline-event-rail-label">
          <span>Events</span>
          <div className="timeline-event-step-controls">
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(-1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === 0} aria-label="Previous warning or error event" data-tooltip-key="tooltip.previousEvent">Prev</button>
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === markerEvents.length - 1} aria-label="Next warning or error event" data-tooltip-key="tooltip.nextEvent">Next</button>
          </div>
        </div>
        <TimelineEventRail buckets={eventRailBuckets} gaps={gaps} range={range} cursorPercent={clampPercent(cursorPercent)} selectedEventId={selectedEventId} activeBucketEventIds={activeBucketEventIds} previewedEventId={previewedEventId} onActivateBucket={activateTimelineEventBucket} />
        {eventBucketPopover ? <TimelineEventBucketPopover ref={eventPopoverRef} bucket={eventBucketPopover} onClose={() => { setEventBucketPopover(null); setPreviewedEventId(null); }} onPreviewEvent={setPreviewedEventId} onSelectEvent={selectTimelineEvent} canRevealEvent={canRevealTimelineEvent} onRevealEvent={(event) => { revealTimelineEvent(event); selectTimelineEvent(event); }} /> : null}
      </div>
      <div className="timeline-rows">
        <TimelineTimeGrid ticks={range.ticks} range={range} />
        {virtualized.topPad > 0 ? <div style={{ height: virtualized.topPad }} /> : null}
        {virtualized.visible.map((item) => {
          const itemAnimation = treeAnimation?.parentKey === item.parentKey ? treeAnimation : null;
          const animationClass = itemAnimation ? " timeline-tree-" + itemAnimation.phase : "";
          if (item.type === "interface") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineInterfaceLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={interfaceExpanded[item.group.key] ?? true}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={() => toggleTimelineTree(item.key, interfaceExpanded[item.group.key] ?? true, () => setInterfaceExpanded((current) => ({ ...current, [item.group.key]: !(current[item.group.key] ?? true) })))}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  activeBucketEventIds={activeBucketEventIds}
                  previewedEventId={previewedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          if (item.type === "proto") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineProtoLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  activeBucketEventIds={activeBucketEventIds}
                  previewedEventId={previewedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          if (item.type === "scope") {
            return (
              <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
                <TimelineTreeGuideLines guide={item.treeGuide} />
                <TimelineScopeLane
                  group={item.group}
                  range={range}
                  gaps={gaps}
                  cursorPercent={clampPercent(cursorPercent)}
                  cursorSec={cursorSec}
                  expanded={item.expanded}
                  isHovered={hoveredRowKey === item.group.key}
                  onHoverChange={setHoveredRowKey}
                  onToggle={item.onToggle}
                  eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                  selectedEventId={selectedEventId}
                  activeBucketEventIds={activeBucketEventIds}
                  previewedEventId={previewedEventId}
                  onSelectEvent={activateTimelineEventBucket}
                />
              </div>
            );
          }

          return (
            <div key={item.key} className={"timeline-virtual-item" + animationClass} style={{ height: item.height }}>
              <TimelineTreeGuideLines guide={item.treeGuide} />
              <TimelineLane
                rowKey={item.rowKey}
                row={item.row}
                treeLevel={item.treeGuide.depth}
                range={range}
                gaps={gaps}
                cursorPercent={clampPercent(cursorPercent)}
                cursorSec={cursorSec}
                fadeSec={fadeSec}
                isHovered={hoveredRowKey === item.rowKey}
                onHoverChange={setHoveredRowKey}
                childCount={item.childCount ?? 0}
                expanded={item.expanded ?? false}
                onToggle={item.onToggle}
                eventBuckets={visibleRowEventBuckets.get(item.key) ?? []}
                selectedEventId={selectedEventId}
                activeBucketEventIds={activeBucketEventIds}
                previewedEventId={previewedEventId}
                onSelectEvent={activateTimelineEventBucket}
                onInspectTarget={onInspectTarget}
              />
            </div>
          );
        })}
        {virtualized.bottomPad > 0 ? <div style={{ height: virtualized.bottomPad }} /> : null}
      </div>
    </div>
  );
}

type EventMarkerBucket = { key: string; time: number; level: "warn" | "error"; events: EventLogItem[]; primary: EventLogItem };

const MAX_EVENT_MARKERS = 240;
const EVENT_MARKER_MIN_DISTANCE_PX = 18;
const TIME_TICK_STEPS_SEC = [
  0.1, 0.2, 0.5,
  1, 2, 5, 10, 15, 30,
  60, 120, 300, 600, 900, 1800,
  3600, 7200, 10800, 21600, 43200, 86400
];
const EVENT_BUCKET_STEPS_SEC = [
  0.1, 0.2, 0.5,
  1, 2, 5, 10, 15, 30,
  cursorSec: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
  eventBuckets: EventMarkerBucket[];
  selectedEventId: string | null;
  activeBucketEventIds: ReadonlySet<string>;
  previewedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
}) {
  const focused = group.segments.some((segment) => cursorSec >= segment.start && cursorSec <= segment.end);
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";
  return (
    <div
      className={`timeline-proto-row${focusClass}`}
      onPointerEnter={() => onHoverChange(group.key)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-proto-label" data-tooltip={group.key}>
        <strong>
          <button type="button" className={"timeline-toggle" + (expanded ? " open" : "")} onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label={expanded ? "Collapse protocol rows" : "Expand protocol rows"}>
            <Icon name="expand" size={15} />
          </button>
          <span className="timeline-label-text">{group.proto}</span>
          <TimelineCountBadge count={group.rows.length} />
        </strong>
      </div>
      <div className="timeline-row-track timeline-proto-track">
        <TimelineGapBands gaps={gaps} range={range} />
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {splitTimelineSegments(group.segments, gaps, range).map((segment, index) => {
          const start = percent(segment.start, range.start, range.end);
          const end = percent(segment.end ?? range.end, range.start, range.end);
          return (
            <div
              key={`${group.key}:${index}:${segment.start}`}
              className={`timeline-segment timeline-segment-proto${group.active && (segment.end ?? range.end) >= range.end ? " active" : ""}`}
              style={{
                left: `${start}%`,
                width: `${Math.max(0.6, end - start)}%`
              }}
            />
          );
        })}
        <TimelineRowEventMarkers buckets={eventBuckets} range={range} selectedEventId={selectedEventId} activeBucketEventIds={activeBucketEventIds} previewedEventId={previewedEventId} onSelectEvent={onSelectEvent} />
      </div>
    </div>
  );
}

function TimelineInterfaceLane({
  group,
  range,
  gaps,
  cursorPercent,
  cursorSec,
  expanded,
  isHovered,
  onHoverChange,
  onToggle,
  eventBuckets,
  selectedEventId,
  activeBucketEventIds,
  previewedEventId,
  onSelectEvent
}: {
  group: {
    key: string;
    label: string;
    rows: Array<{ stream: TimelineRow; flows: TimelineRow[] }>;
    segments: Array<{ start: number; end: number }>;
    firstSeen: number;
    lastSeen: number;
    active: boolean;
  };
  range: { start: number; end: number };
  cursorPercent: number;
  gaps: TimelineDataGap[];
  cursorSec: number;
  expanded: boolean;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  onToggle: () => void;
  eventBuckets: EventMarkerBucket[];
  selectedEventId: string | null;
  activeBucketEventIds: ReadonlySet<string>;
  previewedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
}) {
  const focused = group.segments.some((segment) => cursorSec >= segment.start && cursorSec <= segment.end);
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";
  return (
    <div
      className={`timeline-interface-header${focusClass}`}
      onPointerEnter={() => onHoverChange(group.key)}
      onPointerLeave={() => onHoverChange(null)}
    >
      <div className="timeline-interface-label" data-tooltip={group.key}>
        <strong>
          <button type="button" className={"timeline-toggle" + (expanded ? " open" : "")} onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label={expanded ? "Collapse interface rows" : "Expand interface rows"}>
            <Icon name="expand" size={15} />
          </button>
          <span className="timeline-label-text">{group.label}</span>
          <TimelineCountBadge count={group.rows.length} />
        </strong>
      </div>
      <div className="timeline-row-track timeline-interface-track">
        <TimelineGapBands gaps={gaps} range={range} />
        <div className="timeline-cursor-line" style={{ left: `${cursorPercent}%` }} aria-hidden="true" />
        {splitTimelineSegments(group.segments, gaps, range).map((segment, index) => {
          const start = percent(segment.start, range.start, range.end);
          const end = percent(segment.end ?? range.end, range.start, range.end);
          return (
            <div
              key={`${group.key}:${index}:${segment.start}`}
              className={`timeline-segment timeline-segment-interface${group.active && (segment.end ?? range.end) >= range.end ? " active" : ""}`}
              style={{
                left: `${start}%`,
                width: `${Math.max(0.6, end - start)}%`
              }}
            />
          );
        })}
        <TimelineRowEventMarkers buckets={eventBuckets} range={range} selectedEventId={selectedEventId} activeBucketEventIds={activeBucketEventIds} previewedEventId={previewedEventId} onSelectEvent={onSelectEvent} />
      </div>
    </div>
  );
}

function TimelineLane({
  rowKey,
  row,
  treeLevel,
  range,
  gaps,
  cursorPercent,
  cursorSec,
  fadeSec,
  isHovered,
  onHoverChange,
  childCount = 0,
  expanded = true,
  onToggle,
  eventBuckets,
  selectedEventId,
  activeBucketEventIds,
  previewedEventId,
  onSelectEvent,
  onInspectTarget
}: {
  rowKey: string;
  row: TimelineRow;
  treeLevel: number;
  range: { start: number; end: number };
  cursorPercent: number;
  gaps: TimelineDataGap[];
  cursorSec: number;
  fadeSec: number;
  isHovered: boolean;
  onHoverChange: (key: string | null) => void;
  childCount?: number;
  expanded?: boolean;
  onToggle?: () => void;
  eventBuckets: EventMarkerBucket[];
  selectedEventId: string | null;
  activeBucketEventIds: ReadonlySet<string>;
  previewedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
  onInspectTarget?: (row: TimelineRow) => void;
}) {
  const focused = row.segments.some((segment) => {
    const end = segment.end ?? range.end;
    return cursorSec >= segment.start && cursorSec <= end;
  });
  const focusClass = focused ? " timeline-row-cursor-focused" : isHovered ? " timeline-row-hovered" : "";

