.timeline-proto-row.timeline-row-cursor-focused .timeline-proto-label,
.timeline-row.timeline-row-cursor-focused .timeline-row-label {
  background: var(--surface-muted);
}

/* Horizontal separators come only from the actual row boundaries. */
.timeline-chart {
  background: var(--surface);
}

.timeline-rows {
  position: relative;
}

.timeline-time-grid {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: calc(var(--timeline-label-width) + var(--space-2));
  z-index: 0;
  pointer-events: none;
}

.timeline-time-grid-line {
  position: absolute;
  top: 0;
  bottom: 0;
