function TimelineRowEventMarkers({ buckets, range, selectedEventId, activeBucketEventIds, previewedEventId, onSelectEvent }: {
  buckets: EventMarkerBucket[];
  range: { start: number; end: number };
  selectedEventId: string | null;
  activeBucketEventIds: ReadonlySet<string>;
  previewedEventId: string | null;
  onSelectEvent: (bucket: EventMarkerBucket) => void;
}) {
  return <>{buckets.map((bucket) => {
    const selected = bucket.events.some((event) => event.id === selectedEventId);
    const inActiveBucket = bucket.events.some((event) => activeBucketEventIds.has(event.id));
    const previewed = bucket.events.some((event) => event.id === previewedEventId);
    const label = eventMarkerLabel(bucket);
    const timePercent = percent(bucket.time, range.start, range.end);
    return <button
      key={bucket.key}
      type="button"
      className={"timeline-row-event-marker " + bucket.level + (selected ? " selected" : "") + (inActiveBucket ? " in-event-bucket" : "") + (previewed ? " previewed" : "")}
      style={{ left: "clamp(6px, " + timePercent + "%, calc(100% - 6px))" }}
      data-tooltip={label}
      aria-label={label}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => { event.stopPropagation(); onSelectEvent(bucket); }}
    />;
  })}</>;
}

function TimelineCountBadge({ count }: { count: number }) {
  return <span className="timeline-count-badge">{count}</span>;
}
function TimelineGapBands({ gaps, range, label = false }: { gaps: TimelineDataGap[]; range: { start: number; end: number }; label?: boolean }) {
  return <>{gaps.map((gap) => {
    const from = Math.max(range.start, gap.from);
    const to = Math.min(range.end, gap.to);
    if (to <= from) return null;
    const start = percent(from, range.start, range.end);
    const end = percent(to, range.start, range.end);
    return <div key={`${gap.reason}:${from}:${to}`} className="timeline-gap-band" style={{ left: `${start}%`, width: `${Math.max(0.4, end - start)}%` }} data-tooltip-key="tooltip.monitoringDataUnavailable" aria-label={label ? "Monitoring data unavailable" : undefined} />;
  })}</>;
}

