function clipTimelineRow(row: TimelineRow, from: number, to: number): TimelineRow | undefined {
  const clippedSegments = row.segments
    .map((segment) => {
      const effectiveEnd = segment.end ?? to;
      if (effectiveEnd <= from || segment.start >= to) return undefined;
      return {
        start: Math.max(segment.start, from),
        end: segment.end === null ? null : Math.min(segment.end, to)
      };
    })
    .filter((segment): segment is NonNullable<typeof segment> => segment !== undefined);

  if (clippedSegments.length === 0) {
    return undefined;
  }

  return {
    ...row,
    firstSeen: clippedSegments[0].start,
    lastSeen: Math.min(row.lastSeen, to),
    segments: clippedSegments
  };
}

function listTimelineFiles(from: number, to: number) {
  const files: string[] = [];
  const current = new Date(Math.floor(from) * 1000);
  current.setUTCMinutes(0, 0, 0);
  const end = new Date(Math.floor(to) * 1000);
  end.setUTCMinutes(0, 0, 0);

  while (current.getTime() <= end.getTime()) {
    const yyyy = current.getUTCFullYear().toString().padStart(4, "0");
    const mm = String(current.getUTCMonth() + 1).padStart(2, "0");
    const dd = String(current.getUTCDate()).padStart(2, "0");
    const hh = String(current.getUTCHours()).padStart(2, "0");
    const file = path.join(config.timelineEventsDir, `${yyyy}${mm}${dd}`, `${hh}.ndjson`);
    if (existsSync(file)) files.push(file);
    current.setUTCHours(current.getUTCHours() + 1);
  }

  return files;
}

function getTimelineAvailableWindow(): TimelineWindow | undefined {
  if (!existsSync(config.timelineEventsDir)) return undefined;

  const dayDirs = readdirSync(config.timelineEventsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && /^\d{8}$/.test(entry.name))
    .map((entry) => entry.name)
    .sort();
  if (dayDirs.length === 0) return undefined;

  let earliest: number | undefined;
  let latestHourEnd: number | undefined;
  let latestEventTime: number | undefined;

  for (const dayDir of dayDirs) {
    const hours = readdirSync(path.join(config.timelineEventsDir, dayDir), { withFileTypes: true })
      .filter((entry) => entry.isFile() && /^\d{2}\.ndjson$/.test(entry.name))
      .map((entry) => Number(entry.name.slice(0, 2)))
      .filter((value) => Number.isInteger(value))
      .sort((a, b) => a - b);
    if (hours.length === 0) continue;

    const year = Number(dayDir.slice(0, 4));
    const month = Number(dayDir.slice(4, 6)) - 1;
    const day = Number(dayDir.slice(6, 8));
    const first = Date.UTC(year, month, day, hours[0], 0, 0) / 1000;
    const latestHour = hours[hours.length - 1];
    const last = Date.UTC(year, month, day, latestHour, 0, 0) / 1000 + 3600;
    earliest = earliest === undefined ? first : Math.min(earliest, first);
    latestHourEnd = latestHourEnd === undefined ? last : Math.max(latestHourEnd, last);

    const latestFile = path.join(config.timelineEventsDir, dayDir, `${String(latestHour).padStart(2, "0")}.ndjson`);
    const latestInFile = readLastTimelineEventTime(latestFile);
    if (latestInFile !== undefined) {
      latestEventTime = latestEventTime === undefined ? latestInFile : Math.max(latestEventTime, latestInFile);
    }
  }

  const latest = latestEventTime ?? latestHourEnd;
  if (earliest === undefined || latest === undefined || latest <= earliest) {
    return undefined;
  }

  return { from: earliest, to: latest };
}

function readLastTimelineEventTime(file: string): number | undefined {
  try {
    const text = readFileSync(file, "utf8");
    if (!text) return undefined;
    const lines = text.split("\n");
    for (let i = lines.length - 1; i >= 0; i -= 1) {
      const line = lines[i]?.trim();
      if (!line) continue;
      const item = normalizeTimelineLine(line);
      if (item && Number.isFinite(item.time)) return item.time;
      break;
    }
  } catch {
    return undefined;
  }
  return undefined;
}

async function readTimelineFile(file: string, onEntry: (item: NormalizedTimelineInput) => void) {
  const rl = readline.createInterface({
    input: createReadStream(file),
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (!line) continue;
    const item = normalizeTimelineLine(line);
    if (item) onEntry(item);
  }
}
