          const trimmedFrom = Math.max(mergedAvailable.from, desiredTo - keepSpanSec);
          const trimmedRows = clipTimelineRows(mergedRows, trimmedFrom, desiredTo);
          const trimmedGaps = clipTimelineGaps(mergedGaps, trimmedFrom, desiredTo);
          timelineHistoryCacheRef.current = {
            from: trimmedFrom,
            to: desiredTo,
            rows: trimmedRows,
            gaps: trimmedGaps,
            available: mergedAvailable,
            source: response.source
          };
          const window = clampTimelineWindow({
            desiredTo,
            windowSec: preset.windowSec,
            available: mergedAvailable,
            nowSec: safeNow
          });
          setTimeline(clipTimelineRows(trimmedRows, window.from, window.to));
          setTimelineGaps(clipTimelineGaps(trimmedGaps, window.from, window.to));
          setTimelineWindow(window);
          setTimelineAvailable(mergedAvailable);
          setTimelineSource(response.source);
        }).finally(() => {
          timelineLoadingRef.current = false;
          if (!background) { setTimelineLoading(false); if (requestId !== undefined) timelineLoad.succeed(requestId); }
        });
        return;
      }

      const lookbackSec = timelineFollowNow ? preset.windowSec : preset.windowSec * 4;
      const queryFrom = Math.max(0, desiredTo - lookbackSec);
      void getTimelineChunked({
        from: queryFrom,
        to: desiredTo,
        includeFlows: true
      }).then((response) => {
        if (cancelled) return;
        timelineHistoryCacheRef.current = {
          from: queryFrom,
          to: desiredTo,
          rows: response.rows,
          gaps: response.gaps ?? [],
          available: response.available,
          source: response.source
        };
        const window = clampTimelineWindow({
          desiredTo,
          windowSec: preset.windowSec,
          available: response.available,
          nowSec: safeNow
        });
        setTimeline(clipTimelineRows(response.rows, window.from, window.to));
        setTimelineGaps(clipTimelineGaps(response.gaps ?? [], window.from, window.to));
        setTimelineWindow(window);
        setTimelineAvailable(response.available);
        setTimelineSource(response.source);
      }).finally(() => {
        timelineLoadingRef.current = false;
        if (!background) { setTimelineLoading(false); if (requestId !== undefined) timelineLoad.succeed(requestId); }
      });
    };
    load();
    const timer = timelineFollowNow && selectedTimeSec === null ? window.setInterval(() => load(true), timelineFollowRefreshMs(preset.windowSec)) : undefined;
    return () => {
      cancelled = true;
    };
  }

  const minTo = safeAvailable.from + windowSec;
  const maxTo = safeAvailable.to;
  const safeTo = Math.min(maxTo, Math.max(minTo, desiredTo));
  return {
    from: safeTo - windowSec,
    to: safeTo
  };
}

function clipTimelineRows(rows: TimelineRow[], from: number, to: number) {
  const clipped = rows
    .map((row) => {
      const segments = row.segments
        .map((segment) => {
          const effectiveEnd = segment.end ?? to;
          if (effectiveEnd <= from || segment.start >= to) return undefined;
          return {
            start: Math.max(segment.start, from),
            end: segment.end === null ? null : Math.min(segment.end, to)
          };
        })
        .filter((segment): segment is NonNullable<typeof segment> => segment !== undefined);

      return {
        ...row,
        firstSeen: segments.length > 0 ? segments[0].start : row.firstSeen,
        lastSeen: Math.min(row.lastSeen, to),
        segments
      };
    });

  // 履歴APIと同じく、表示期間と重ならないflowは行ごと除外する。
  // flowだけが期間内に残る場合は、階層表示に必要な親streamを残す。
  const streamKeysWithVisibleFlow = new Set(
    clipped
      .filter((row) => row.rowType === "flow" && row.segments.length > 0)
      .map((row) => row.parentStreamKey ?? row.streamKey)
  );

  return clipped.filter((row) => row.segments.length > 0 || (
    row.rowType === "stream" && streamKeysWithVisibleFlow.has(row.streamKey)
  ));
}
function clipTimelineGaps(gaps: TimelineDataGap[], from: number, to: number) {
  return gaps
    .map((gap) => ({ ...gap, from: Math.max(from, gap.from), to: Math.min(to, gap.to) }))
    .filter((gap) => gap.to > gap.from);
}

function mergeTimelineGaps(base: TimelineDataGap[], incoming: TimelineDataGap[]) {
  const sorted = [...base, ...incoming]
    .filter((gap) => Number.isFinite(gap.from) && Number.isFinite(gap.to) && gap.to > gap.from)
    .sort((a, b) => a.from - b.from || a.to - b.to);
  const merged: TimelineDataGap[] = [];
  for (const gap of sorted) {
    const previous = merged[merged.length - 1];
    if (!previous || gap.from > previous.to) {
      merged.push({ ...gap });
      continue;
    }
    previous.to = Math.max(previous.to, gap.to);
  }
  return merged;
      last.end = Math.max(last.end, segment.end);
    }
  }
  return merged;
}

function mergeTimelineRows(baseRows: TimelineRow[], incomingRows: TimelineRow[]) {
  const map = new Map<string, TimelineRow>();
  for (const row of baseRows) {
    const key = row.rowType === "flow" ? `${row.streamKey}::${row.flowKey ?? row.streamKey}` : row.streamKey;
    map.set(key, {
      ...row,
      segments: row.segments.map((segment) => ({ ...segment }))
    });
  }

  for (const row of incomingRows) {
    const key = row.rowType === "flow" ? `${row.streamKey}::${row.flowKey ?? row.streamKey}` : row.streamKey;
    const existing = map.get(key);
    if (!existing) {
      map.set(key, {
        ...row,
        segments: row.segments.map((segment) => ({ ...segment }))
      });
      continue;
    }
    const incomingIsLatest = row.lastSeen >= existing.lastSeen;
    existing.active = incomingIsLatest ? row.active : existing.active;
    existing.firstSeen = Math.min(existing.firstSeen, row.firstSeen);
    existing.lastSeen = Math.max(existing.lastSeen, row.lastSeen);
    existing.interfaceId = existing.interfaceId ?? row.interfaceId;
    existing.interfaceName = existing.interfaceName ?? row.interfaceName;
    existing.scope = existing.scope?.known ? existing.scope : row.scope;
    existing.label = existing.label || row.label;
    existing.role = existing.role ?? row.role;
    existing.endpointSrc = existing.endpointSrc ?? row.endpointSrc;
    existing.endpointDst = existing.endpointDst ?? row.endpointDst;
    existing.segments.push(...row.segments.map((segment) => ({ ...segment })));
    existing.segments = mergeTimelineSegments(existing.segments);
  }

  return [...map.values()];
}

