    40	): TimelineDataGap[] {
    41	  const uniquePoints = [...new Set(points
    42	    .map((point) => point.time)
    43	    .filter((time) => Number.isFinite(time) && time <= to))]
    44	    .sort((a, b) => a - b);
    45	  const gaps: TimelineDataGap[] = [];
