    48	    const gapFrom = uniquePoints[index - 1] + maxIntervalSec;
    49	    const gapTo = uniquePoints[index];
    50	    if (gapTo <= gapFrom) continue;
    51	    const clippedFrom = Math.max(from, gapFrom);
    52	    const clippedTo = Math.min(to, gapTo);
    53	    if (clippedTo > clippedFrom) gaps.push({ from: clippedFrom, to: clippedTo, reason: "monitor-unavailable" });
    54	  }
