#include "journal_reader.h"
#include "trace.h"

#include <algorithm>
#include <fstream>
#include <system_error>
#include <utility>

namespace {
struct journal_file_start {
	std::string record_id;
	std::string capture_id;
};

journal_file_start first_record(const std::filesystem::path &path) {
	std::ifstream input(path);
	std::string line;
	while(std::getline(input, line)) {
		if(line.empty()) continue;
		try {
			const json record = json::parse(line);
			if(record.is_object()) {
				return journal_file_start{
					.record_id = record.value("record_id", std::string{}),
					.capture_id = record.value("capture_id", std::string{}),
				};
			}
		}
		catch(const json::parse_error &) {
			break;
		}
	}
	return {};
}

bool record_matches_capture(const std::string &record_id, const std::string &capture_id) {
	return !capture_id.empty() && record_id.size() > capture_id.size() &&
	       record_id.compare(0, capture_id.size(), capture_id) == 0 &&
	       record_id[capture_id.size()] == ':';
}

void reset_replaced_cursor(journal_reader::cursor &cursor,
	                        const std::string &path,
	                        std::uint64_t file_size,
	                        const char *reason) {
	trace(1, "journal reader: cursor reset path=%s reason=%s old_offset=%llu file_size=%llu",
	      path.c_str(), reason,
	      static_cast<unsigned long long>(cursor.offset),
	      static_cast<unsigned long long>(file_size));
	cursor.offset = 0;
	cursor.record_id.clear();
	cursor.file_start_record_id.clear();
}

void advance_cursor(journal_reader::cursor &cursor,
	                const std::string &path,
	                std::uint64_t offset,
	                const std::string &record_id) {
	const bool path_changed = cursor.path != path;
	if(path_changed) {
		cursor.path = path;
		cursor.file_start_record_id.clear();
	}
	cursor.offset = offset;
	cursor.record_id = record_id;
	if(path_changed && !record_id.empty()) {
		cursor.file_start_record_id = record_id;
	}
}
}

journal_reader::journal_reader(std::filesystem::path root)
	: m_root(std::move(root)) {
}

journal_reader::result journal_reader::read_after(cursor &cursor, const record_handler &handler) const {
	result out{};
	for(const auto &path : list_files()) {
		const auto relative = std::filesystem::relative(path, m_root).generic_string();
		if(!cursor.path.empty() && relative < cursor.path) {
			continue;
		}

		if(relative == cursor.path) {
			std::error_code ec{};
			const auto file_size = std::filesystem::file_size(path, ec);
			const auto current_start = first_record(path);
			if(!ec && file_size < cursor.offset) {
				reset_replaced_cursor(cursor, relative, file_size, "truncated");
				cursor.file_start_record_id = current_start.record_id;
			}
			else if(cursor.file_start_record_id.empty()) {
				if(!cursor.record_id.empty() && !current_start.capture_id.empty() &&
				   !record_matches_capture(cursor.record_id, current_start.capture_id)) {
					reset_replaced_cursor(cursor, relative, ec ? 0 : file_size, "capture-changed");
					cursor.file_start_record_id = current_start.record_id;
				}
				else {
					cursor.file_start_record_id = current_start.record_id;
				}
			}
			else {
				if(!current_start.record_id.empty() &&
				   current_start.record_id != cursor.file_start_record_id) {
					reset_replaced_cursor(cursor, relative, ec ? 0 : file_size, "start-record-changed");
					cursor.file_start_record_id = current_start.record_id;
				}
			}
		}

		std::ifstream input(path);
		if(!input) {
			continue;
		}

		std::uint64_t offset = 0;
		std::string line;
		while(std::getline(input, line)) {
			const std::uint64_t next_offset = offset + static_cast<std::uint64_t>(line.size()) + 1U;
			if(relative == cursor.path && next_offset <= cursor.offset) {
				offset = next_offset;
				continue;
			}
			offset = next_offset;
			if(line.empty()) {
				continue;
			}

			json record;
			try {
				record = json::parse(line);
			}
			catch(const json::parse_error &) {
				// A writer can leave a partial final line while it is appending. Keep it for the next pass.
				break;
			}
			if(!record.is_object()) {
				advance_cursor(cursor, relative, next_offset, {});
				out.advanced = true;
				continue;
			}
			if(handler(record) != 0) {
				return out;
			}
			advance_cursor(cursor, relative, next_offset,
			               record.value("record_id", std::string{}));
			++out.records;
			out.advanced = true;
		}
	}
