namespace {
void check(bool value, const char *message) {
	if(!value) throw std::runtime_error(message);
}

class memory_writer : public writer {
public:
	int dump(const json &) override { return 0; }
};

json read(const std::filesystem::path &file) {
	std::ifstream input(file);
	return json::parse(input);
}
}

int main() {
	char pattern[] = "/tmp/stm-timeline-checkpoint-XXXXXX";
	const char *directory = mkdtemp(pattern);
	if(!directory) return 1;
	const std::filesystem::path root(directory);
	try {
		memory_writer output;
		timeline_sink timeline({.live_writer = output, .capture_id = "test",
			.history_root = root / "events", .checkpoint_root = root / "checkpoint"});
		const double start = 1792540800.0; // 2026-10-21 00:00 UTC.
		const json stream{{"type", "stream"}, {"stream_key", "stream-a"}, {"proto", "RTP"}};
		const json flow{{"type", "flow"}, {"stream_key", "stream-a"}, {"flow_key", "flow-a"}, {"proto", "RTP"}};
		timeline.emit(start + 10, "stream_detected", stream);
		timeline.emit(start + 20, "flow_detected", flow);
		check(std::filesystem::is_empty(root / "checkpoint"), "no snapshot before the first minute rollover");

		timeline.emit(start + 60.25, "flow_lost", flow);
		const auto checkpoint = root / "checkpoint" / "20261021" / "0001.json";
		check(std::filesystem::exists(checkpoint), "snapshot must use the current minute");
		check(!std::filesystem::exists(root / "checkpoint" / "20261021" / "0000.json"), "current state must not be saved under the previous minute");
		const auto first = read(checkpoint);
		check(first["time"] == start + 60.25 && first["slot"]["minute"] == 1, "body time and filename minute must match");
		check(first["active_rows"].size() == 1 && first["active_rows"][0]["type"] == "stream", "snapshot must include the triggering Lost");

		timeline.emit(start + 60.25, "flow_recovered", flow);
		check(read(checkpoint) == first, "later events in the same minute must remain in the event history");
		timeline.emit(start + 120, "marker", stream);
		const auto second = read(root / "checkpoint" / "20261021" / "0002.json");
		check(second["active_rows"].size() == 2, "next snapshot must preserve the recovered flow");

		const double resumed = start + 2 * 86400 + 301.5;
		timeline.emit(resumed, "stream_lost", stream);
		const auto after_gap = read(root / "checkpoint" / "20261023" / "0005.json");
		check(after_gap["time"] == resumed && after_gap["slot"]["day"] == 23, "long gaps must use the resumed date and minute");
		check(read(root / "checkpoint" / "20261021" / "0002.json") == second, "resumption must not rewrite an older snapshot");
		std::filesystem::remove_all(root);
		std::cout << "timeline checkpoint tests passed\n";
		return 0;
	} catch(const std::exception &error) {
		std::filesystem::remove_all(root);
		std::cerr << error.what() << '\n';
		return 1;
	}
}
