import type { TimelineDataGap, TimelineWindow } from "./types/api";

export function clampTimelineWindow({ desiredTo, windowSec, available, nowSec }: {
  desiredTo: number; windowSec: number; available: TimelineWindow; nowSec: number;
}) {
  // Observation bounds do not limit the display of a stopped/unavailable tail.
  const to = Math.min(Math.max(available.to, desiredTo), nowSec);
  const start = Math.min(available.from, to);
  if (to - start <= windowSec) return { from: start, to };
  const end = Math.min(to, Math.max(start + windowSec, desiredTo));
  return { from: end - windowSec, to: end };
}

export function clipTimelineGaps(gaps: TimelineDataGap[], from: number, to: number) {
  return gaps.map((gap) => ({ ...gap, from: Math.max(from, gap.from), to: Math.min(to, gap.to) }))
    .filter((gap) => gap.to > gap.from);
}

export function mergeTimelineGaps(base: TimelineDataGap[], incoming: TimelineDataGap[]) {
  const sorted = [...base, ...incoming]
    .filter((gap) => Number.isFinite(gap.from) && Number.isFinite(gap.to) && gap.to > gap.from)
    .sort((a, b) => a.from - b.from || a.to - b.to);
  const merged: TimelineDataGap[] = [];
  for (const gap of sorted) {
    const previous = merged[merged.length - 1];
    if (!previous || gap.from > previous.to || previous.reason !== gap.reason || !!previous.provisional !== !!gap.provisional) {
      merged.push({ ...gap });
    } else previous.to = Math.max(previous.to, gap.to);
  }
  return merged;
}

export function replaceTimelineGaps(base: TimelineDataGap[], incoming: TimelineDataGap[], from: number, to: number) {
  const kept = base.flatMap((gap) => [
    ...clipTimelineGaps([gap], gap.from, from),
    ...clipTimelineGaps([gap], to, gap.to)
  ]);
  return mergeTimelineGaps(kept, clipTimelineGaps(incoming, from, to));
}

export function timelineDeltaFrom(cache: { to: number; gaps: TimelineDataGap[] }, desiredFrom: number) {
  let from = Math.max(0, cache.to - 120);
  for (const gap of cache.gaps) {
    if (gap.to > desiredFrom) from = Math.min(from, Math.max(desiredFrom, gap.from));
  }
  return from;
}

