bool timeline_sink::observe_run(const json &record, double time) {
	const auto id = record.value("run_id", record.value("capture_id", std::string{}));
	if(id.empty() || id == m_run_id) return true;
	const auto producer = record.value("producer", json::object());
	const double started_at = producer.is_object() ? producer.value("started_at", 0.0) : 0.0;
	if(m_run_started_at > 0.0 && started_at > 0.0 && started_at <= m_run_started_at) return false;
	m_run_id = id;
	m_run_started_at = started_at;
	emit(time, "observation_run", {{"type", "system"}, {"run_id", id}});
	return true;
}

void timeline_sink::observe_metrics(double time, const json::array_t &metrics) {
	// A final metrics window can still contain traffic counted before a Lost.
	std::erase_if(m_recently_closed, [time](const auto &entry) { return time > entry.second + 3.0; });
	for(const auto &entry : metrics) {
		if(!entry.is_object()) continue;
		const auto stream_key = entry.value("stream_key", std::string{});
		if(stream_key.empty()) continue;
		bool observed = false;
		for(const char *field : {"packet_count", "request_count", "response_count", "download_bytes"}) {
			const auto counter = entry.value(field, json::object());
			if(counter.is_object() && counter.contains("window") && counter["window"].is_number() && counter["window"].get<double>() > 0.0) observed = true;
		}
		if(!observed || m_recently_closed.contains(stream_key)) continue;
		json subject{{"type", "stream"}, {"stream_key", stream_key}};
		for(const char *field : {"proto", "interface_id", "scope", "name", "endpoint", "stream_group"}) {
			if(entry.contains(field)) subject[field] = entry[field];
		}
		if(!m_active_rows.contains(stream_key)) emit(time, "stream_observed", subject);
		const auto flow_key = entry.value("flow_key", std::string{});
		const auto key = stream_key + "::" + flow_key;
		if(flow_key.empty() || m_active_rows.contains(key) || m_recently_closed.contains(key)) continue;
		subject["type"] = "flow";
		subject["flow_key"] = flow_key;
		if(entry.contains("role")) subject["role"] = entry["role"];
		emit(time, "flow_observed", std::move(subject));
	}
}

json timeline_sink::export_state() const {
	json rows = json::array();
	for(const auto &[key, state] : m_active_rows) {
		json item = state.row;
		item["first_seen"] = state.first_seen;
		item["last_seen"] = state.last_seen;
		rows.push_back(std::move(item));
	}
	std::sort(rows.begin(), rows.end(), [](const json &a, const json &b) { return a.value("key", "") < b.value("key", ""); });
	return {{"active_rows", std::move(rows)}, {"run_id", m_run_id}, {"run_started_at", m_run_started_at},
		{"seq", m_seq}, {"recently_closed", m_recently_closed}};
}

void timeline_sink::import_state(const json &state) {
	if(!state.is_object()) return;
	m_run_id = state.value("run_id", std::string{});
	m_run_started_at = state.value("run_started_at", 0.0);
	m_seq = state.value("seq", std::uint64_t{0});
	m_recently_closed = state.value("recently_closed", std::unordered_map<std::string, double>{});
	m_active_rows.clear();
	for(const auto &item : state.value("active_rows", json::array())) {
		if(!item.is_object()) continue;
		const auto key = item.value("key", std::string{});
		if(key.empty()) continue;
		m_active_rows[key] = {.row = item, .first_seen = item.value("first_seen", 0.0), .last_seen = item.value("last_seen", 0.0)};
	}
}

