import type { TimelineDataGap, TimelineWindow, TimelineRow, TimelineSegment, TimelineViewResponse } from "./types/api";

export function clampTimelineWindow({ desiredTo, windowSec, available, nowSec }: {
  desiredTo: number; windowSec: number; available: TimelineWindow; nowSec: number;
}) {
  // Observation bounds do not limit the display of a stopped/unavailable tail.
  const to = Math.min(Math.max(available.to, desiredTo), nowSec);
  const start = Math.min(available.from, to);
  if (to - start <= windowSec) return { from: start, to };
  const end = Math.min(to, Math.max(start + windowSec, desiredTo));
  return { from: end - windowSec, to: end };
}

export function clipTimelineGaps(gaps: TimelineDataGap[], from: number, to: number) {
  return gaps.map((gap) => ({ ...gap, from: Math.max(from, gap.from), to: Math.min(to, gap.to) }))
    .filter((gap) => gap.to > gap.from);
}

export function mergeTimelineGaps(base: TimelineDataGap[], incoming: TimelineDataGap[]) {
  const sorted = [...base, ...incoming]
    .filter((gap) => Number.isFinite(gap.from) && Number.isFinite(gap.to) && gap.to > gap.from)
    .sort((a, b) => a.from - b.from || a.to - b.to);
  const merged: TimelineDataGap[] = [];
  for (const gap of sorted) {
    const previous = merged[merged.length - 1];
    if (!previous || gap.from > previous.to || previous.reason !== gap.reason || !!previous.provisional !== !!gap.provisional) {
      merged.push({ ...gap });
    } else previous.to = Math.max(previous.to, gap.to);
  }
  return merged;
}

export function replaceTimelineGaps(base: TimelineDataGap[], incoming: TimelineDataGap[], from: number, to: number) {
  const kept = base.flatMap((gap) => [
    ...clipTimelineGaps([gap], gap.from, from),
    ...clipTimelineGaps([gap], to, gap.to)
  ]);
  return mergeTimelineGaps(kept, clipTimelineGaps(incoming, from, to));
}

export function timelineDeltaFrom(cache: { to: number; gaps: TimelineDataGap[] }, desiredFrom: number) {
  let from = Math.max(0, cache.to - 120);
  for (const gap of cache.gaps) {
    if (gap.to > desiredFrom) from = Math.min(from, Math.max(desiredFrom, gap.from));
  }
  return from;
}

/** A query returns the full state for its window; absence and holes are authoritative too. */
export function replaceTimelineRows(base: TimelineRow[], incoming: TimelineRow[], from: number) {
  const key = (row: TimelineRow) => row.rowType === "flow" ? `${row.streamKey}::${row.flowKey ?? ""}` : row.streamKey;
  const rows = new Map<string, TimelineRow>();
  for (const row of base) {
    const segments = row.segments.map(segment => ({ start: segment.start, end: Math.min(segment.end ?? from, from) }))
      .filter(segment => segment.end > segment.start);
    if (segments.length) rows.set(key(row), { ...row, segments, active: false, lastSeen: Math.min(from, row.lastSeen) });
  }
  for (const row of incoming) {
    const previous = rows.get(key(row));
    const sorted = [...(previous?.segments ?? []), ...row.segments].sort((a, b) => a.start - b.start);
    const segments: TimelineSegment[] = [];
    for (const segment of sorted) {
      const last = segments[segments.length - 1];
      if (last && segment.start <= (last.end ?? Infinity)) {
        last.end = last.end === null || segment.end === null ? null : Math.max(last.end, segment.end);
      } else segments.push({ ...segment });
    }
    rows.set(key(row), { ...row, firstSeen: Math.min(previous?.firstSeen ?? row.firstSeen, row.firstSeen), segments });
  }
  return [...rows.values()];
}

export async function queryTimelineChunks(query: { from: number; to: number; includeFlows: boolean },
  fetchChunk: (query: { from: number; to: number; includeFlows: boolean }) => Promise<TimelineViewResponse>, chunkSec = 30 * 60): Promise<TimelineViewResponse> {
  if (query.to - query.from <= chunkSec) return fetchChunk(query);
  let rows: TimelineRow[] = [], gaps: TimelineDataGap[] = [];
  let available: TimelineWindow | null = null;
  let source: "live" | "history" = "history";
  for (let from = query.from; from < query.to; from += chunkSec) {
    const to = Math.min(query.to, from + chunkSec);
    const part = await fetchChunk({ from, to, includeFlows: query.includeFlows });
    const normalized = part.rows.map(row => ({ ...row, segments: row.segments.map(segment => ({
      start: segment.start, end: segment.end === null && to < query.to ? to : segment.end
    })) }));
    rows = replaceTimelineRows(rows, normalized, from);
    gaps = mergeTimelineGaps(gaps, part.gaps ?? []);
    available = available ? { from: Math.min(available.from, part.available.from), to: Math.max(available.to, part.available.to) } : part.available;
    source = part.source;
  }
  return { rows, gaps, available: available ?? { from: query.from, to: query.to }, window: { from: query.from, to: query.to }, source };
}

