import { Fragment, forwardRef, useEffect, useMemo, useRef, useState } from "react";
import type { EventLogItem, NetworkScope, TimelineDataGap, TimelineRow } from "../types/api";
import { Icon } from "./ui/Icon";

type TimelinePaneProps = {
  rows: TimelineRow[];
  gaps?: TimelineDataGap[];
  nowSec: number;
  fadeSec: number;
  rangeStartSec: number;
  rangeEndSec: number;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  onPanBySec?: (deltaSec: number) => void;
  onZoom?: (direction: "in" | "out") => void;
  events?: EventLogItem[];
  selectedEventId?: string | null;
  onSelectEvent?: (event: EventLogItem) => void;
  onInspectTarget?: (row: TimelineRow) => void;
  interfaceNames?: ReadonlyMap<number, string>;
};

type TimelineStreamGroup = { stream: TimelineRow; flows: TimelineRow[] };
type TimelineEventLane = { key: string; eventTargetKeys: string[] };
type TimelineDisplayGroup = { key: string; label: string; confidence?: "confirmed" | "heuristic"; rows: TimelineStreamGroup[]; grouped: boolean };
type TimelineTreeAnimation = { parentKey: string; phase: "enter" | "leave" };
type TimelineScopeGroup = {
  key: string;
  label: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};
type TimelineProtoGroup = {
  key: string;
  proto: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};

type TimelineTreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

type TimelineStickyContextItem = {
  kind: "interface" | "scope" | "proto" | "stream";
  label: string;
  proto?: string;
  title?: string;
};

function TimelineTreeGuideLines({ guide }: { guide: TimelineTreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);

  return <span className="timeline-tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`timeline-tree-guide-line timeline-tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`timeline-tree-guide-line timeline-tree-guide-depth-${guide.depth} timeline-tree-guide-${segment}`} />)}
  </span>;
}

export function TimelinePane({ rows, gaps = [], nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, onPanBySec, onZoom, events = [], selectedEventId = null, onSelectEvent, onInspectTarget, interfaceNames }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [scopeExpanded, setScopeExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
  const [treeAnimation, setTreeAnimation] = useState<TimelineTreeAnimation | null>(null);
  const [eventBucketPopover, setEventBucketPopover] = useState<EventMarkerBucket | null>(null);
  const [previewedEventId, setPreviewedEventId] = useState<string | null>(null);
  const [pendingRevealRowKey, setPendingRevealRowKey] = useState<string | null>(null);
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<HTMLDivElement | null>(null);
  const eventPopoverRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);
  const [isScrubbing, setIsScrubbing] = useState(false);
  const [hoveredRowKey, setHoveredRowKey] = useState<string | null>(null);
  const [selectedTimelineRowKey, setSelectedTimelineRowKey] = useState<string | null>(null);
  const [viewport, setViewport] = useState({ top: 0, height: 480 });
  const [axisWidth, setAxisWidth] = useState(0);
  const cursorRafRef = useRef<number | null>(null);
  const treeAnimationTimerRef = useRef<number | null>(null);
  const pendingCursorXRef = useRef<number | null>(null);
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);
  const scrubPointerIdRef = useRef<number | null>(null);
  const skipNextTimeSelectRef = useRef(false);
  const panStartXRef = useRef<number | null>(null);
  const panLastXRef = useRef<number | null>(null);
  const hasPannedRef = useRef(false);
  const zoomHandlerRef = useRef(onZoom);
  const [isPointerInside, setIsPointerInside] = useState(false);
  const [isCtrlPressed, setIsCtrlPressed] = useState(false);
  zoomHandlerRef.current = onZoom;

  const toggleTimelineTree = (parentKey: string, isExpanded: boolean, update: () => void) => {
    if (treeAnimation) return;
    if (treeAnimationTimerRef.current !== null) window.clearTimeout(treeAnimationTimerRef.current);
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setTreeAnimation(null);
      update();
      return;
    }
    if (isExpanded) {
      setTreeAnimation({ parentKey, phase: "leave" });
      treeAnimationTimerRef.current = window.setTimeout(() => {
        update();
        setTreeAnimation(null);
        treeAnimationTimerRef.current = null;
      }, 140);
      return;
    }
    update();
    setTreeAnimation({ parentKey, phase: "enter" });
    treeAnimationTimerRef.current = window.setTimeout(() => {
      setTreeAnimation(null);
      treeAnimationTimerRef.current = null;
    }, 160);
  };

  useEffect(() => {
    const updateCtrlState = (event: KeyboardEvent) => {
      if (event.key === "Control") setIsCtrlPressed(event.type === "keydown");
    };
    window.addEventListener("keydown", updateCtrlState);
    window.addEventListener("keyup", updateCtrlState);
    return () => {
      window.removeEventListener("keydown", updateCtrlState);
      window.removeEventListener("keyup", updateCtrlState);
    };
  }, []);

  useEffect(() => {
    const axis = axisScaleRef.current;
    if (!axis) return;
    const update = () => setAxisWidth(axis.clientWidth);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(axis);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!isHoveringCursor) {
      setCursorSec(Math.min(rangeEndSec, Math.max(rangeStartSec, nowSec)));
    }
  }, [isHoveringCursor, nowSec, rangeStartSec, rangeEndSec]);

  const updateCursor = (clientX: number) => {
    const time = timeFromClientX(clientX);
    if (time !== null) setCursorSec(time);
  };

  const timeFromClientX = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return null;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return null;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
    return Math.round(range.start + ratio * (range.end - range.start));
  };

  const panFromClientX = (clientX: number) => {
    const startX = panStartXRef.current;
    const lastX = panLastXRef.current;
    const axis = axisScaleRef.current;
    if (startX === null || lastX === null || !axis || axis.clientWidth <= 0) return false;
    if (!hasPannedRef.current && Math.abs(clientX - startX) < 4) return false;
    hasPannedRef.current = true;
    const deltaSec = -((clientX - lastX) / axis.clientWidth) * (range.end - range.start);
    panLastXRef.current = clientX;
    if (deltaSec !== 0) onPanBySec?.(deltaSec);
    return true;
  };

  useEffect(() => {
    setExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        if (row.rowType !== "stream") continue;
        if (!(row.streamKey in next)) {
          next[row.streamKey] = expandLevel === "flow";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel, interfaceNames]);

  useEffect(() => {
    setInterfaceExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const label = interfaceLabel(row, interfaceNames);
        const key = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${label}`;
        if (!(key in next)) {
          next[key] = expandLevel !== "interface";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel]);

  useEffect(() => {
    setProtoExpanded((current) => {
      const next = { ...current };
      let changed = false;
      for (const row of rows) {
        const ifKey = row.interfaceId !== undefined ? `if:${row.interfaceId}` : `name:${row.interfaceName ?? "unknown"}`;
        const proto = row.proto || row.kind || "OTHER";
        const key = `${ifKey}::${proto}`;
        if (!(key in next)) {
          next[key] = expandLevel === "stream" || expandLevel === "flow";
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [rows, expandLevel]);

  const range = useMemo(() => {
    const safeStart = Number.isFinite(rangeStartSec) ? rangeStartSec : nowSec - 60;
    const safeEnd = Number.isFinite(rangeEndSec) && rangeEndSec > safeStart ? rangeEndSec : safeStart + 1;
    const tickStepSec = timelineTickStepSec(safeEnd - safeStart);
    return {
      start: safeStart,
      end: safeEnd,
      ticks: buildTimelineTicks(safeStart, safeEnd, tickStepSec)
    };
  }, [nowSec, rangeStartSec, rangeEndSec]);

  useEffect(() => {
    if (!isScrubbing) return;
    const cancelScrubOnEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      scrubPointerIdRef.current = null;
      setIsScrubbing(false);
      setIsHoveringCursor(false);
      setCursorSec(Math.min(range.end, Math.max(range.start, selectedTimeSec ?? nowSec)));
    };
    window.addEventListener("keydown", cancelScrubOnEscape);
    return () => window.removeEventListener("keydown", cancelScrubOnEscape);
  }, [isScrubbing, nowSec, range, selectedTimeSec]);
  const displayedCursorSec = isScrubbing ? cursorSec : selectedTimeSec ?? cursorSec;
  const cursorPercent = percent(Math.min(range.end, Math.max(range.start, displayedCursorSec)), range.start, range.end);
  const cursorLabel = formatCursor(displayedCursorSec);
  const markerEvents = useMemo(() => events
    .filter((event) => (event.level === "warn" || event.level === "error") && event.time >= range.start && event.time <= range.end)
    .sort((left, right) => left.time - right.time || left.id.localeCompare(right.id)), [events, range.end, range.start]);
  const markerBuckets = useMemo(() => buildEventMarkerBuckets(markerEvents, range), [markerEvents, range]);
  const eventRailBuckets = useMemo(
    () => clusterEventMarkerBuckets(markerBuckets, range, axisWidth),
    [axisWidth, markerBuckets, range]
  );
  const activeBucketEventIds = useMemo(
    () => new Set(eventBucketPopover?.events.map((event) => event.id) ?? []),
    [eventBucketPopover]
  );
  const selectedMarkerIndex = selectedEventId === null ? -1 : markerEvents.findIndex((event) => event.id === selectedEventId);
  const selectTimelineEvent = (event: EventLogItem) => {
    setEventBucketPopover(null);
    setPreviewedEventId(null);
    if (onSelectEvent) onSelectEvent(event);
    else onSelectTime?.(event.time);
  };
  const activateTimelineEventBucket = (bucket: EventMarkerBucket) => {
    selectTimelineEvent(bucket.primary);
    if (bucket.events.length > 1) setEventBucketPopover(bucket);
  };
  const moveToAdjacentMarker = (direction: -1 | 1) => {
    if (markerEvents.length === 0) return;
    const referenceTime = selectedMarkerIndex >= 0
      ? markerEvents[selectedMarkerIndex].time
      : selectedTimeSec ?? displayedCursorSec;
    const index = selectedMarkerIndex >= 0
      ? selectedMarkerIndex + direction
      : direction > 0
        ? markerEvents.findIndex((event) => event.time > referenceTime)
        : findPreviousEventIndex(markerEvents, referenceTime);
    const event = markerEvents[index];
    if (!event) return;
    selectTimelineEvent(event);
  };

  const groupedRows = useMemo(() => {
    const streams = rows.filter((row) => row.rowType === "stream");
    const flowsByParent = new Map<string, TimelineRow[]>();
    for (const row of rows) {
      if (row.rowType !== "flow" || !row.parentStreamKey) continue;
      const group = flowsByParent.get(row.parentStreamKey) ?? [];
      group.push(row);
      flowsByParent.set(row.parentStreamKey, group);
    }
    return streams.map((stream) => {
      const flows = flowsByParent.get(stream.streamKey) ?? [];
      const flowScope = flows.find((flow) => flow.scope?.known)?.scope;
      const streamSegments = stream.segments.map((segment) => ({ start: segment.start, end: segment.end }));
      const flowSegments = flows.flatMap((flow) => flow.segments.map((segment) => ({ start: segment.start, end: segment.end })));
      const merged = mergeSegmentsNullable([...streamSegments, ...flowSegments]);
      return {
        stream: {
          ...stream,
          scope: stream.scope?.known ? stream.scope : flowScope ?? stream.scope,
          active: stream.active || flows.some((flow) => flow.active),
          segments: merged
        },
        flows
      };
    });
  }, [rows]);

  const groupedByInterface = useMemo(() => {
    const groups = new Map<string, { key: string; label: string; rows: typeof groupedRows }>();
    for (const item of groupedRows) {
      const label = interfaceLabel(item.stream, interfaceNames);
      const key = item.stream.interfaceId !== undefined ? `if:${item.stream.interfaceId}` : `name:${label}`;
      const group = groups.get(key) ?? { key, label, rows: [] };
      group.rows.push(item);
      groups.set(key, group);
    }
    return [...groups.values()]
      .map((group) => ({
        ...group,
        segments: mergeSegments(
          group.rows.flatMap(({ stream }) => stream.segments.map((segment) => ({ start: segment.start, end: segment.end ?? rangeEndSec })))
        ),
        firstSeen: Math.min(...group.rows.map(({ stream }) => stream.firstSeen)),
        lastSeen: Math.max(...group.rows.map(({ stream }) => stream.lastSeen)),
        active: group.rows.some(({ stream }) => stream.active)
    while (startIndex < guidedRows.length && offsets[startIndex] + guidedRows[startIndex].height < startY) {
      startIndex += 1;
    }

    let endIndex = startIndex;
    while (endIndex < guidedRows.length && offsets[endIndex] < endY) {
      endIndex += 1;
    }

    const topPad = startIndex > 0 ? offsets[startIndex] : 0;
    const bottomPad = Math.max(0, total - (endIndex > 0 ? offsets[endIndex - 1] + guidedRows[endIndex - 1].height : 0));

    return {
      startIndex,
      endIndex,
      topPad,
      bottomPad,
      visible: guidedRows.slice(startIndex, endIndex)
    };
  }, [guidedRows, viewport.height, viewport.top]);

  const stickyContext = useMemo(() => {
    if (viewport.top <= 0) return [];
    const items: TimelineStickyContextItem[] = [];
    let consumed = 0;
    for (const item of guidedRows) {
      if (consumed > viewport.top) break;
      consumed += item.height;
      if (item.type === "interface") items.splice(0, items.length, { kind: "interface", label: item.group.label });
      else if (item.type === "scope") items.splice(1, items.length - 1, { kind: "scope", label: item.group.label });
      else if (item.type === "proto") items.splice(2, items.length - 2, { kind: "proto", label: item.group.proto, proto: item.group.proto });
      else if (item.type === "stream") items.splice(3, items.length - 3, { kind: "stream", label: timelineRowLabel(item.row), title: timelineStreamEndpointText(item.row) });
    }
    return items.length > 1 ? items : [];
  }, [guidedRows, viewport.top]);

  useEffect(() => {
    const chart = chartRef.current;
    if (!chart) return;
    const onWheel = (event: WheelEvent) => {
      const onZoom = zoomHandlerRef.current;
      if (!event.ctrlKey || !onZoom || event.deltaY === 0) return;
      event.preventDefault();
      onZoom(event.deltaY < 0 ? "in" : "out");
    };
    chart.addEventListener("wheel", onWheel, { passive: false });
    return () => chart.removeEventListener("wheel", onWheel);
  }, [groupedByInterface.length]);

  if (groupedByInterface.length === 0 && gaps.length === 0) {
    return (
      <div className="timeline-placeholder">
        <strong>Timeline is empty</strong>
        <span>No stream lifetime data matches the current filter yet.</span>
      </div>
    );
  }

  return (
      <div
        ref={chartRef}
        className={"timeline-chart" + (isScrubbing ? " is-time-scrubbing" : "") + (isPointerInside && isCtrlPressed && onZoom ? " is-zoom-mode" : "")}
        tabIndex={0}
        onKeyDown={(event) => {
          if (event.altKey || event.ctrlKey || event.metaKey || (event.key !== "ArrowLeft" && event.key !== "ArrowRight")) return;
          const target = event.target as HTMLElement;
          if (target.closest("button") && !target.closest(".timeline-event-step, .timeline-event-marker")) return;
          event.preventDefault();
          moveToAdjacentMarker(event.key === "ArrowLeft" ? -1 : 1);
        }}
        onClick={(event) => {
          if (skipNextTimeSelectRef.current) {
            skipNextTimeSelectRef.current = false;
            return;
          }
          const target = event.target as HTMLElement;
          if (!target.closest(".timeline-axis-scale, .timeline-row-track")) return;
          const selected = timeFromClientX(event.clientX);
          if (selected !== null) onSelectTime?.(selected);
        }}
        onPointerEnter={(event) => {
          setIsPointerInside(true);
          setIsCtrlPressed(event.ctrlKey);
        }}
        onPointerDown={(event) => {
          const target = event.target as HTMLElement;
          if (event.button !== 0 || !target.closest(".timeline-axis-scale, .timeline-row-track")) return;
          scrubPointerIdRef.current = event.pointerId;
          panStartXRef.current = event.clientX;
          panLastXRef.current = event.clientX;
          hasPannedRef.current = false;
          event.currentTarget.setPointerCapture(event.pointerId);
          setIsScrubbing(true);
          setIsHoveringCursor(true);
          updateCursor(event.clientX);
        }}
        onPointerMove={(event) => {
          setIsCtrlPressed(event.ctrlKey);
          if (scrubPointerIdRef.current !== null && scrubPointerIdRef.current !== event.pointerId) return;
          if (scrubPointerIdRef.current === event.pointerId && panFromClientX(event.clientX)) return;
          setIsHoveringCursor(true);
          pendingCursorXRef.current = event.clientX;
          if (cursorRafRef.current !== null) return;
          cursorRafRef.current = window.requestAnimationFrame(() => {
            cursorRafRef.current = null;
            const x = pendingCursorXRef.current;
            if (x !== null) updateCursor(x);
          });
