.timeline-pane {
  padding: 0;
  border-top: 0;
  background: var(--surface);
}

.timeline-header {
  min-height: var(--pane-header-height);
  align-items: center;
  margin: 0;
  padding: 0 var(--space-2);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-header h3 {
  font-size: var(--font-size-sm);
}

.timeline-browse-controls {
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
}

.timeline-browse-controls button {
  min-width: 48px;
  height: 24px;
  min-height: 24px;
  padding: 0 7px;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-browse-controls button.active {
  border: 0;
  background: var(--accent-soft);
  color: var(--accent);
}

.timeline-body {
  border: 0;
  border-radius: 0;
  background:
    linear-gradient(90deg, var(--chart-grid) 1px, transparent 1px) 0 0 / 96px 100%,
    linear-gradient(var(--chart-grid) 1px, transparent 1px) 0 0 / 100% 30px,
    var(--surface);
  /*  padding: 0 var(--space-2);*/
  padding: 0;
}

.timeline-axis {
  gap: var(--space-2);
/*  padding: 4px 0;*/
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.timeline-axis-tick,
.timeline-cursor-label {
  font-size: var(--font-size-xs);
}

.timeline-cursor-label {
  padding: 2px 5px;
  border-color: var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.timeline-interface-header,
.timeline-proto-row,
.timeline-row {
  gap: var(--space-2);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
}

.timeline-interface-header,
  z-index: 1;
}

.timeline-axis-tick {
  z-index: 2;
}

.timeline-cursor-line {
  z-index: 3;
}

/* Sticky event rail shares the time scale and remains visible above scrolling lanes. */
.timeline-axis {
  position: sticky;
  top: 0;
  z-index: 10;
  grid-template-rows: 24px 22px;
  column-gap: var(--space-2);
  row-gap: 0;
}

.timeline-axis-scale {
  height: 24px;
}

.timeline-cursor-label {
  top: 0;
}

.timeline-cursor-label.is-at-start {
  transform: translateX(0);
}

.timeline-cursor-label.is-at-end {
  transform: translateX(-100%);
}

.timeline-event-rail-label {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-1);
  padding: 0 var(--space-2);
  border-right: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
/*  background: color-mix(in srgb, var(--surface-muted) 88%, var(--surface));*/
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.timeline-event-step-controls {
  display: inline-flex;
  gap: 2px;
}

.timeline-event-step {
  min-width: 28px;
  min-height: 18px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text-strong);
  font-size: 10px;
  line-height: 1;
}
}

.timeline-row-event-marker:hover::before,
.timeline-row-event-marker:focus-visible::before {
  top: 3px;
  bottom: 3px;
  width: 5px;
}


/* Align the sticky Timeline context with the Streams hierarchy chips. */
.timeline-sticky-context { display: flex; align-items: center; width: 100%; min-width: 0; overflow: hidden; pointer-events: none; }
.timeline-axis { grid-template-rows: 32px 24px; }
.timeline-axis-label { padding: 0 10px; }
.timeline-axis-scale { height: 32px; }
.timeline-axis-tick { top: 9px; }
.timeline-cursor-label { top: 6px; }
.timeline-event-rail-label { padding: 0 10px; font-size: var(--font-size-xs); }
.timeline-event-rail { height: 24px; }
.timeline-event-marker { top: 4px; }

/* Let the sticky hierarchy path extend over the time scale instead of truncating it at the label column. */
.timeline-axis-label {
  position: relative;
  z-index: 5;
  overflow: visible;
}

.timeline-sticky-context {
  width: max-content;
  min-width: 100%;
  overflow: visible;
}

.timeline-sticky-context .stream-context-segment {
  flex: 0 0 auto;
}

.timeline-sticky-context .stream-context-chip {
  max-width: none;
  overflow: visible;
  text-overflow: clip;
}

.timeline-inspect-button {
  display: inline-grid;
  flex: 0 0 auto;
  place-items: center;
  width: 22px;
  height: 22px;
  margin-left: auto;
  padding: 0;
  opacity: 0;
  color: var(--muted);
  background: transparent;
  border: 0;
  border-radius: var(--radius-sm);
}
.timeline-row:hover .timeline-inspect-button,
.timeline-row:focus-within .timeline-inspect-button { opacity: 1; }
.timeline-inspect-button:hover,
.timeline-inspect-button:focus-visible { color: var(--accent); background: var(--accent-soft); }
