test('Timeline and Events navigate by exact identity without changing filters or measurement points', {timeout:40000}, async t => {
  const browser = await clientBrowser(t, `
    import React,{useState,useRef} from 'react';import {createRoot} from 'react-dom/client';
    import {TimelinePane} from './client/src/components/TimelinePane';import {EventLog} from './client/src/components/EventLog';
    import {EMPTY_TIMELINE_MEASUREMENT} from './client/src/timelineCursor';
    import {includeTimelineNavigationRows,requestTimeNavigation} from './client/src/timeNavigation';
    import {I18nProvider,useI18n} from './client/src/i18n';import {TooltipProvider} from './client/src/components/ui/TooltipProvider';
    const epoch=1700000000, scope={known:true,layers:[],interfaceId:0,interfaceName:'lo'};
    const rows=Array.from({length:15},(_,i)=>{const s={rowType:'stream',streamKey:'s'+i,label:'Stream '+i,kind:'RTP',proto:'RTP',scope,interfaceId:0,active:true,firstSeen:epoch,lastSeen:epoch+60,segments:[{start:epoch,end:null}]};return[s,{...s,rowType:'flow',parentStreamKey:s.streamKey,flowKey:'f'+i}]}).flat();
    const events=[...Array.from({length:100},(_,i)=>({id:'near'+i,time:epoch+i*.6,type:'test',level:'info',scope:'system',message:'ordinary '+i})),
      {id:'39148',time:epoch+16.001,type:'test',level:'warn',scope:'flow',streamKey:'s0',flowKey:'f0',message:'39148 recovered'},
      {id:'34309',time:epoch+16.865,type:'test',level:'warn',scope:'flow',streamKey:'s14',flowKey:'f14',message:'34309 recovered'},
      {id:'info',time:epoch+22.234,type:'test',level:'info',scope:'flow',streamKey:'s14',flowKey:'f14',message:'INFO target'},
      {id:'missing',time:epoch+25.456,type:'test',level:'info',scope:'flow',streamKey:'absent',flowKey:'absent-flow',message:'Missing target'}];
    window.allowNavigation=true;window.pendingNavigation=null;window.approve=()=>window.pendingNavigation?.();
    function Fixture(){
      const[view,setView]=useState('timeline'),[time,setTime]=useState(epoch+10),[selected,setSelected]=useState(null),[target,setTarget]=useState(null);
      const[m,setM]=useState(EMPTY_TIMELINE_MEASUREMENT),[c,setC]=useState({query:'',hideTimeline:false,missing:false,loading:false});const revision=useRef(0);const{setLocale}=useI18n();window.locale=setLocale;
      window.configure=p=>setC(s=>({...s,...p}));window.state={view,time,selected:selected?.id,target,m,config:c};
      const go=(tab,time,event)=>requestTimeNavigation(action=>{if(window.allowNavigation)action();else window.pendingNavigation=action},r=>{
        setTime(r.time);setSelected(r.event??null);setTarget({time:r.time,event:r.event,revision:++revision.current});setView(r.tab);
      },{tab,time,event});
      window.jump=(tab,id,time)=>{const e=events.find(e=>e.id===id);go(tab,e?.time??time,e)};
      const allRows=c.missing?[]:rows, filtered=c.hideTimeline?[]:allRows, shown=includeTimelineNavigationRows(allRows,filtered,view==='timeline'?target?.event:undefined);
      const setTimeOnly=x=>{setTime(x);setSelected(null);setTarget(null)};
      return <main style={{height:500,width:1000}}>{view==='timeline'?<div className='timeline-body' style={{height:'100%'}}><TimelinePane rows={shown} gaps={[]} nowSec={epoch+60} fadeSec={2}
        rangeStartSec={epoch} rangeEndSec={epoch+60} selectedTimeSec={time} onSelectTime={setTimeOnly} events={events.filter(e=>e.level==='warn')}
        selectedEventId={selected?.id} onSelectEvent={e=>{setSelected(e);setTime(e.time)}} expandLevel='interface' measurement={m} onChangeMeasurement={setM}
        navigationTarget={target} navigationOutsideFilter={shown!==filtered} navigationLoading={c.loading} onOpenEvents={(time,event)=>go('events',time,event)}/></div>:
        <EventLog events={events} eventsRange='1m' onChangeEventsRange={()=>{}} selectedStreamKey={null} selectedFlowKey={null} selectedInterfaceId={null}
          query={c.query} onChangeQuery={query=>setC(s=>({...s,query}))} selectedTimeSec={time} selectedEvent={selected} onSelectEvent={setSelected} onSelectTime={setTimeOnly}
          timeSelectionRevision={target?.revision} navigationTarget={target} onOpenTimeline={e=>go('timeline',e.time,e)} />}</main>;
    }
    createRoot(document.getElementById('root')).render(<I18nProvider><TooltipProvider delayMs={0}><Fixture/></TooltipProvider></I18nProvider>);
  `);
  if(!browser)return;
  const {evaluate,wait,call,errors}=browser;
  await wait("!!document.querySelector('.timeline-measure-toggle')");
  await evaluate("document.querySelector('.timeline-event-marker').click()");
  await wait("document.querySelectorAll('.timeline-event-bucket-item').length===2");
  await evaluate("document.querySelector('[data-event-id=\"39148\"] .timeline-event-set-a').click()");
  await evaluate("document.querySelector('[data-event-id=\"34309\"] .timeline-event-set-b').click()");
  await wait("state.m.A?.event?.id==='39148'&&state.m.B?.event?.id==='34309'");
  await evaluate("configure({query:'does-not-match'})");
  await evaluate("document.querySelector('[data-event-id=\"34309\"] .timeline-event-open-events').click()");
  await wait("state.view==='events'&&!!document.querySelector('.event-primary-selected[data-event-id=\"34309\"]')");
  assert.equal(await evaluate('state.time'),1700000016.865);
  assert.equal(await evaluate('state.config.query'),'does-not-match');
  assert.match(await evaluate("document.querySelector('.events-navigation-status').textContent"),/outside current filter/);
  await evaluate("configure({hideTimeline:true})");
  await evaluate("document.querySelector('.event-open-timeline').click()");
  await wait("state.view==='timeline'&&!!document.querySelector('.timeline-row-flow.selected')");
  assert.equal(await evaluate("document.querySelectorAll('.timeline-row-flow').length"),1,'only the target flow is added outside the filter');
  assert.match(await evaluate("document.querySelector('.timeline-navigation-status').textContent"),/outside the filter/);
  assert.equal(await evaluate("document.querySelector('.timeline-interval').getAttribute('aria-label')"),'B − A: +864 ms');
  await evaluate("document.querySelector('.timeline-open-a-events').click()");
  await wait("!!document.querySelector('.event-primary-selected[data-event-id=\"39148\"]')");
  await evaluate("jump('timeline','info')");
  await wait("!!document.querySelector('.timeline-event-marker.info.selected')&&!!document.querySelector('.timeline-row-flow.selected')");
  assert.equal(await evaluate("document.querySelector('.timeline-event-marker.info').textContent"),'i');
  await evaluate("document.querySelector('.timeline-open-events').click()");
  await wait("state.view==='events'&&state.selected===undefined");
  assert.equal(await evaluate("document.querySelectorAll('.event-primary-selected').length"),0,'a timestamp jump never pretends to select a specific event');
  assert.match(await evaluate("document.querySelector('.events-navigation-status').textContent"),/no exact event selected/);
  await evaluate("configure({query:''});jump('events',null,1700000028.05)");
  await wait("document.querySelector('.events-list')?.scrollTop>0");
  assert.equal(await evaluate("document.querySelectorAll('.event-primary-selected').length"),0);
  const before=await evaluate('JSON.stringify({view:state.view,time:state.time,target:state.target})');
  await evaluate("allowNavigation=false;jump('timeline','info')");
  assert.equal(await evaluate('JSON.stringify({view:state.view,time:state.time,target:state.target})'),before,'rejected navigation leaves both time and view unchanged');
  await evaluate('approve();allowNavigation=true');
  await wait("state.view==='timeline'&&!!document.querySelector('.timeline-event-marker.info.selected')");
  await evaluate("configure({missing:true});jump('timeline','missing')");
  await wait("document.querySelector('.timeline-navigation-status')?.textContent.includes('No stream/flow history')");
  assert.equal(await evaluate("document.querySelectorAll('.timeline-row').length"),0,'missing history does not invent a target row');
  await evaluate("locale('ja')");
  await wait("document.querySelector('.timeline-navigation-status')?.textContent.includes('履歴がありません')");
  await evaluate("configure({loading:true});jump('timeline','info')");
  await wait("document.querySelector('.timeline-navigation-status')?.textContent.includes('読込')");
  await evaluate("configure({missing:false,loading:false,hideTimeline:false})");
  await wait("!!document.querySelector('.timeline-row-flow.selected')");
  assert.ok(await evaluate("document.querySelector('.timeline-body').scrollTop>0"),'target is revealed after history arrives');
  for(const theme of ['light','dark']){
    await evaluate(`document.documentElement.dataset.theme='${theme}'`);
    const layout=await evaluate("(()=>{const a=document.querySelector('.timeline-axis').getBoundingClientRect(),f=document.querySelector('.timeline-row-flow.selected').getBoundingClientRect(),b=document.querySelector('.timeline-body').getBoundingClientRect();return{axis:a.bottom,flowTop:f.top,flowBottom:f.bottom,bottom:b.bottom}})()");
    assert.ok(layout.flowTop>=layout.axis&&layout.flowBottom<=layout.bottom,JSON.stringify(layout));
  }
  assert.deepEqual(errors,[]);
});

