    revealTimelineEvent(target);
    const key = navigationRow.rowType === "flow" ? `flow:${navigationRow.parentStreamKey ?? navigationRow.streamKey}::${navigationRow.flowKey}` : `stream:${navigationRow.streamKey}`;
    setSelectedTimelineRowKey(key);
