import type { EventLogItem, TimelineDataGap } from "./types/api";

/** Timeline coordinates retain fractional seconds; ordinary time selection may round separately. */
export function timelineTimeAtX(clientX: number, left: number, width: number, start: number, end: number) {
  if (width <= 0 || ![clientX, left, width, start, end].every(Number.isFinite) || end <= start) return null;
  return start + Math.min(1, Math.max(0, (clientX - left) / width)) * (end - start);
}

export type TimelineAnchorName = "A" | "B";
export type TimelineMeasurementPoint = { time: number; event?: EventLogItem };
export type TimelineMeasurement = {
  enabled: boolean;
  active: TimelineAnchorName;
  A: TimelineMeasurementPoint | null;
  B: TimelineMeasurementPoint | null;
};
export const EMPTY_TIMELINE_MEASUREMENT: TimelineMeasurement = { enabled: false, active: "A", A: null, B: null };

export function setTimelineMeasurementPoint(state: TimelineMeasurement, name: TimelineAnchorName, point: TimelineMeasurementPoint) {
  return { ...state, [name]: point, active: name === "A" && !state.A && !state.B ? "B" as const : name };
}

export function formatTimelineCursorTime(time: number) {
  return new Date(time * 1000).toLocaleString([], {
    hour12: false, year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", fractionalSecondDigits: 3
  });
}

export function formatTimelineDuration(from: number, to: number) {
  const signedMs = Math.round((to - from) * 1000);
  const ms = Math.abs(signedMs);
  const sign = signedMs < 0 ? "−" : signedMs > 0 ? "+" : "";
  if (ms < 1000) return `${sign}${ms} ms`;
  if (ms < 60000) return `${sign}${(ms / 1000).toFixed(3)} s`;
  const seconds = `${((ms % 60000) / 1000).toFixed(3).padStart(6, "0")} s`;
  const minutes = Math.floor(ms / 60000);
  return minutes < 60 ? `${sign}${minutes} m ${seconds}` : `${sign}${Math.floor(minutes / 60)} h ${minutes % 60} m ${seconds}`;
}

export function timelineIntervalGaps(from: number, to: number, gaps: TimelineDataGap[]) {
  const start = Math.min(from, to), end = Math.max(from, to);
  return start === end ? [] : [...new Set(gaps.filter(gap => gap.from < end && gap.to > start).map(gap => gap.reason))];
