const {test}=require('node:test');
const assert=require('node:assert/strict');
const {clientBrowser}=require('./helpers/client-browser.cjs');

test('Timeline starts measuring only explicitly and Esc hides results without changing time or saved A/B', {timeout:40000}, async t=>{
  const browser=await clientBrowser(t,`
    import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
    import {TimelinePane} from './client/src/components/TimelinePane';
    import {EMPTY_TIMELINE_MEASUREMENT} from './client/src/timelineCursor';
    import {I18nProvider} from './client/src/i18n';import {TooltipProvider} from './client/src/components/ui/TooltipProvider';
    const epoch=1700000000,scope={known:true,layers:[],interfaceId:0,interfaceName:'lo'};
    const stream={rowType:'stream',streamKey:'s',label:'fixture',proto:'RTP',kind:'RTP',scope,interfaceId:0,active:true,firstSeen:epoch,lastSeen:epoch+60,segments:[{start:epoch,end:null}]};
    const rows=[stream,{...stream,rowType:'flow',flowKey:'f',parentStreamKey:'s'}];
    const event={id:'e',time:epoch+16.001,type:'test',level:'warn',scope:'flow',streamKey:'s',flowKey:'f',message:'Fixture event'};
    window.timeCalls=0;
    function Fixture(){
      const[m,setM]=useState(EMPTY_TIMELINE_MEASUREMENT),[other,setOther]=useState(EMPTY_TIMELINE_MEASUREMENT);
      const[c,setC]=useState({time:null,span:60,hidden:false});window.state={m,other,time:c.time};window.configure=p=>setC(s=>({...s,...p}));
      const select=time=>{window.timeCalls++;setC(s=>({...s,time}));setM(s=>({...s,referenceActive:true}))};
      window.latest=()=>{setC(s=>({...s,time:null}));setM(s=>({...s,referenceActive:false}))};
      window.startOther=()=>setOther({...EMPTY_TIMELINE_MEASUREMENT,enabled:true,A:{time:epoch+5},B:{time:epoch+10}});
      const common={rows,nowSec:epoch+60,fadeSec:2,rangeStartSec:epoch,rangeEndSec:epoch+c.span,expandLevel:'flow'};
      return <><div data-pane='main' className='timeline-body' style={{width:1000,height:360}}>{!c.hidden&&<TimelinePane {...common} measurement={m} onChangeMeasurement={setM}
        selectedTimeSec={c.time} onSelectTime={select} events={[event]} onSelectEvent={e=>select(e.time)} />}</div>
        <div data-pane='other' className='timeline-body' style={{width:1000,height:240}}><TimelinePane {...common} measurement={other} onChangeMeasurement={setOther}/></div></>;
    }
    createRoot(document.getElementById('root')).render(<I18nProvider><TooltipProvider delayMs={0}><Fixture/></TooltipProvider></I18nProvider>);
  `);
  if(!browser)return;
  const {evaluate,wait,call,errors}=browser;
  const pane="[data-pane=main]";
  const click=async point=>{
    await call('Input.dispatchMouseEvent',{type:'mouseMoved',...point});
    await call('Input.dispatchMouseEvent',{type:'mousePressed',button:'left',clickCount:1,...point});
    await call('Input.dispatchMouseEvent',{type:'mouseReleased',button:'left',clickCount:1,...point});
  };
  const move=point=>call('Input.dispatchMouseEvent',{type:'mouseMoved',...point});
  const esc=()=>call('Input.dispatchKeyEvent',{type:'keyDown',key:'Escape',code:'Escape'});
  const button=selector=>evaluate(`document.querySelector('${pane} ${selector}').click()`);
  const none=async()=>assert.equal(await evaluate(`document.querySelectorAll('${pane} .timeline-interval,${pane} .timeline-anchor-handle,${pane} .timeline-hover-delta').length`),0);
  await wait(`!!document.querySelector('${pane} .timeline-row-flow')`);
  const a=await evaluate(`(()=>{const r=document.querySelector('${pane} .timeline-row-flow .timeline-row-track').getBoundingClientRect();return{x:r.left+r.width*.3,y:r.top+r.height/2}})()`);
  const b={...a,x:a.x+150};
  await move(a);await wait(`!!document.querySelector('${pane} .cursor-h')`);await none();
  await evaluate('configure({time:1700000012})');await move(b);await none();
  assert.equal(await evaluate('timeCalls'),0,'automatic/frozen timestamps do not count as explicit selection');
  await click(a);await move(b);await wait(`document.querySelector('${pane} .timeline-interval')?.getAttribute('aria-label').startsWith('H − P:')`);
  const selected=await evaluate('state.time'),calls=await evaluate('timeCalls');
  await esc();await wait('!state.m.referenceActive');await none();
  assert.equal(await evaluate('state.time'),selected,'Esc keeps Time travel selected time');
  await move(a);await move(b);await none();
  assert.equal(await evaluate('timeCalls'),calls);
  await evaluate('configure({hidden:true})');await wait(`!document.querySelector('${pane} .timeline-chart')`);
  await evaluate('configure({hidden:false,span:120})');await wait(`!!document.querySelector('${pane} .timeline-chart')`);
  await move(a);await none();
  await click(b);await move(a);await wait(`!!document.querySelector('${pane} .timeline-interval')`);
  await button('.timeline-measure-toggle');await wait('!state.m.referenceActive');await none();
  await button('.timeline-measure-toggle');await wait('state.m.enabled');await move(a);await none();
  const beforeAB=await evaluate('timeCalls');
  await click(a);await move(b);await wait(`document.querySelector('${pane} .timeline-interval')?.getAttribute('aria-label').startsWith('H − A:')`);
  await click(b);await wait('!!state.m.B');
  assert.equal(await evaluate('timeCalls'),beforeAB,'A/B placement does not select Time travel');
  const saved=await evaluate('JSON.stringify([state.m.A,state.m.B])');
  await button('.timeline-measure-toggle');await wait('!state.m.enabled');await move(a);await none();
  assert.equal(await evaluate('JSON.stringify([state.m.A,state.m.B])'),saved);
  assert.equal(await evaluate(`document.querySelectorAll('${pane} .timeline-cursor-readout.cursor-a,${pane} .timeline-cursor-readout.cursor-b').length`),0);
  await click(b);await move(a);await wait(`document.querySelector('${pane} .timeline-interval')?.getAttribute('aria-label').startsWith('H − P:')`);
  assert.equal(await evaluate(`document.querySelectorAll('${pane} .timeline-anchor-handle').length`),0,'new time selection compares P/H without restoring hidden A/B');
  await button('.timeline-measure-toggle');await button('.timeline-measure-toggle');await wait(`!!document.querySelector('${pane} .anchor-a')`);
  assert.equal(await evaluate('JSON.stringify([state.m.A,state.m.B])'),saved,'Measure ON restores the exact saved points');
  await evaluate('startOther()');await wait('state.other.enabled');
  const handle=await evaluate(`(()=>{const r=document.querySelector('${pane} .anchor-a').getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);
  await call('Input.dispatchMouseEvent',{type:'mousePressed',button:'left',clickCount:1,...handle});
  await call('Input.dispatchMouseEvent',{type:'mouseMoved',button:'left',buttons:1,x:handle.x+30,y:handle.y});
  await wait(`JSON.stringify([state.m.A,state.m.B])!==${JSON.stringify(saved)}`);
  await esc();
  await call('Input.dispatchMouseEvent',{type:'mouseReleased',button:'left',clickCount:1,x:handle.x+30,y:handle.y});
  await wait(`JSON.stringify([state.m.A,state.m.B])===${JSON.stringify(saved)}`);
  assert.equal(await evaluate('state.m.enabled'),true,'first Esc cancels the drag, not measurement');
  await esc();await wait('!state.m.enabled');await none();
  assert.equal(await evaluate('state.other.enabled'),true,'Esc affects only the focused Timeline');
  await button('.timeline-event-marker');await wait(`!!document.querySelector('${pane} .timeline-event-bucket-popover')`);
  await button('.timeline-event-set-a');await wait('state.m.enabled');
  await evaluate(`document.querySelector('${pane} .timeline-event-set-a').focus()`);
  await esc();await wait(`!document.querySelector('${pane} .timeline-event-bucket-popover')`);
  assert.equal(await evaluate('state.m.enabled'),true,'first Esc closes a popup without ending measurement');
  await evaluate(`document.querySelector('${pane} .timeline-chart').focus()`);await esc();await wait('!state.m.enabled&&!state.m.referenceActive');await none();
  const timeBeforeLatest=await evaluate('timeCalls');
  await evaluate('latest()');await move(b);await none();
  assert.equal(await evaluate('state.time'),null);assert.equal(await evaluate('timeCalls'),timeBeforeLatest);
  await button('.timeline-measure-clear');await wait('!state.m.A&&!state.m.B');await none();
  assert.deepEqual(errors,[]);
});

