test('Timeline lifetime and fade use the same theme color for streams and flows', {timeout:30000}, async t=>{
  const browser=await clientBrowser(t,`
    import React from 'react';import {createRoot} from 'react-dom/client';
    import {TimelinePane} from './client/src/components/TimelinePane';
    import {I18nProvider} from './client/src/i18n';
    const epoch=1700000000,scope={known:true,layers:[],interfaceId:0,interfaceName:'lo'};
    const base={rowType:'stream',streamKey:'s',label:'Closed stream',kind:'RTP',proto:'RTP',scope,interfaceId:0,active:false,firstSeen:epoch,lastSeen:epoch+40,segments:[{start:epoch,end:epoch+40}]};
    const flow={...base,rowType:'flow',parentStreamKey:'s',flowKey:'f'};
    const short={...base,streamKey:'short',label:'Short lifetime',segments:[{start:epoch+45,end:epoch+46}]};
    const open={...base,streamKey:'open',label:'Open stream',active:true,segments:[{start:epoch+50,end:null}]};
    createRoot(document.getElementById('root')).render(<I18nProvider><div className='timeline-body' style={{height:500,width:1000}}><TimelinePane rows={[base,flow,short,open]} nowSec={epoch+60} rangeStartSec={epoch} rangeEndSec={epoch+60} fadeSec={5} expandLevel='flow' /></div></I18nProvider>);
  `);
  if(!browser)return;
  const {evaluate,wait,errors}=browser;
  await wait("!!document.querySelector('.timeline-row-flow .timeline-segment-split-fade')");
  for(const theme of ['light','dark']){
    await evaluate(`document.documentElement.dataset.theme='${theme}'`);
    for(const kind of ['stream','flow']){
      const colors=await evaluate(`(()=>{const solid=document.querySelector('.timeline-segment-${kind}.timeline-segment-split-solid'),fade=document.querySelector('.timeline-segment-${kind}.timeline-segment-split-fade');return {solid:getComputedStyle(solid).backgroundColor,fade:getComputedStyle(fade).backgroundImage}})()`);
      assert.ok(colors.fade.includes(colors.solid),`${theme}/${kind}: ${JSON.stringify(colors)}`);
      assert.match(colors.fade,/linear-gradient/);
    }
    const streamColors=await evaluate("(()=>{const open=document.querySelector('.timeline-segment-stream:not(.timeline-segment-fade):not(.timeline-segment-split-solid)'),short=document.querySelector('.timeline-segment-stream.timeline-segment-fade:not(.timeline-segment-split-fade)');return {open:getComputedStyle(open).backgroundColor,short:getComputedStyle(short).backgroundImage}})()");
    assert.ok(streamColors.short.includes(streamColors.open),`${theme}/short: ${JSON.stringify(streamColors)}`);
  }
  assert.deepEqual(errors,[]);
});
