const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const os=require('node:os');
const path=require('node:path');
const {clientBrowser}=require('./helpers/client-browser.cjs');

test('Timeline uses quiet theme bands with consistent fades and contrasting error markers', {timeout:30000}, async t=>{
  const browser=await clientBrowser(t,`
    import React from 'react';import {createRoot} from 'react-dom/client';
    import {TimelinePane} from './client/src/components/TimelinePane';
    import {I18nProvider} from './client/src/i18n';
    const epoch=1700000000,scope={known:true,layers:[],interfaceId:0,interfaceName:'lo'};
    const base={rowType:'stream',streamKey:'s',label:'Closed stream',kind:'RTP',proto:'RTP',scope,interfaceId:0,active:false,firstSeen:epoch,lastSeen:epoch+40,segments:[{start:epoch,end:epoch+40}]};
    const flow={...base,rowType:'flow',parentStreamKey:'s',flowKey:'f'};
    const short={...base,streamKey:'short',label:'Short lifetime',segments:[{start:epoch+45,end:epoch+46}]};
    const open={...base,streamKey:'open',label:'Open stream',active:true,segments:[{start:epoch+50,end:null}]};
    const extra=Array.from({length:6},(_,i)=>({...open,streamKey:'extra'+i,label:'Media stream '+i}));
    const events=[{id:'error',time:epoch+12,type:'test',level:'error',scope:'flow',streamKey:'s',flowKey:'f',message:'Packet loss'},
      {id:'warn',time:epoch+20,type:'test',level:'warn',scope:'flow',streamKey:'s',flowKey:'f',message:'Warning'}];
    createRoot(document.getElementById('root')).render(<I18nProvider><div className='timeline-body' style={{height:500,width:1000}}><TimelinePane rows={[base,flow,short,open,...extra]} nowSec={epoch+60} rangeStartSec={epoch} rangeEndSec={epoch+60} fadeSec={5} expandLevel='flow' events={events}/></div></I18nProvider>);
  `);
  if(!browser)return;
  const {evaluate,wait,call,errors}=browser;
  await call('Emulation.setDeviceMetricsOverride',{width:1100,height:700,deviceScaleFactor:1,mobile:false});
  const screenshots=fs.mkdtempSync(path.join(os.tmpdir(),'stm-timeline-colors-'));
  await wait("!!document.querySelector('.timeline-row-flow .timeline-segment-split-fade')");
  const checkPalette=async()=>{
    const colors=await evaluate(`(()=>{
      const root=getComputedStyle(document.documentElement),ctx=document.createElement('canvas').getContext('2d');
      const rgba=color=>{ctx.clearRect(0,0,1,1);ctx.fillStyle=color;ctx.fillRect(0,0,1,1);return Array.from(ctx.getImageData(0,0,1,1).data)};
      const luminance=color=>{const c=rgba(color).slice(0,3).map(v=>v/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722};
      const contrast=(a,b)=>(Math.max(luminance(a),luminance(b))+.05)/(Math.min(luminance(a),luminance(b))+.05);
      const error=getComputedStyle(document.querySelector('.timeline-row-flow .timeline-row-event-marker.error')).color;
      const warning=getComputedStyle(document.querySelector('.timeline-row-flow .timeline-row-event-marker.warn')).color;
      return {error:rgba(error),danger:rgba(root.getPropertyValue('--danger')),warning:rgba(warning),warningToken:rgba(root.getPropertyValue('--warning')),
        bands:['stream','flow','interface','scope','proto'].map(kind=>{
          const elements=Array.from(document.querySelectorAll('.timeline-segment-'+kind+':not(.timeline-segment-fade)'));
          const token=root.getPropertyValue('--timeline-band-'+(kind==='stream'||kind==='flow'?kind:'parent'));
          return {kind,expected:rgba(token),colors:elements.map(e=>rgba(getComputedStyle(e).backgroundColor)),contrasts:elements.map(e=>({error:contrast(error,getComputedStyle(e).backgroundColor),warning:contrast(warning,getComputedStyle(e).backgroundColor)}))};
        })};
    })()`);
    assert.deepEqual(colors.error,colors.danger,'error remains the semantic danger color');
    assert.deepEqual(colors.warning,colors.warningToken,'warning remains the semantic warning color');
    for(const band of colors.bands){
      assert.ok(band.colors.length>0,band.kind);
      for(const color of band.colors)assert.deepEqual(color,band.expected,band.kind+' active and closed bands share the dedicated palette');
      for(const ratio of band.contrasts)assert.ok(ratio.error>=3&&ratio.warning>=3,JSON.stringify({kind:band.kind,...ratio}));
    }
  };
  for(const theme of ['light','dark']){
    await evaluate(`document.documentElement.dataset.theme='${theme}'`);
    await evaluate("document.querySelector('.timeline-interface-label').click()");
    await wait("!document.querySelector('.timeline-row-flow.selected')");
    await call('Input.dispatchMouseEvent',{type:'mouseMoved',x:0,y:0});
    await checkPalette();
    for(const kind of ['stream','flow']){
      const colors=await evaluate(`(()=>{const solid=document.querySelector('.timeline-segment-${kind}.timeline-segment-split-solid'),fade=document.querySelector('.timeline-segment-${kind}.timeline-segment-split-fade');return {solid:getComputedStyle(solid).backgroundColor,fade:getComputedStyle(fade).backgroundImage}})()`);
      assert.ok(colors.fade.includes(colors.solid),`${theme}/${kind}: ${JSON.stringify(colors)}`);
      assert.match(colors.fade,/linear-gradient/);
    }
    const streamColors=await evaluate("(()=>{const open=document.querySelector('.timeline-segment-stream:not(.timeline-segment-fade):not(.timeline-segment-split-solid)'),short=document.querySelector('.timeline-segment-stream.timeline-segment-fade:not(.timeline-segment-split-fade)');return {open:getComputedStyle(open).backgroundColor,short:getComputedStyle(short).backgroundImage}})()");
    assert.ok(streamColors.short.includes(streamColors.open),`${theme}/short: ${JSON.stringify(streamColors)}`);
    const point=await evaluate("(()=>{const r=document.querySelector('.timeline-row-flow .timeline-row-track').getBoundingClientRect();return {x:r.left+r.width*.8,y:r.top+r.height/2}})()");
    await call('Input.dispatchMouseEvent',{type:'mouseMoved',...point});
    await wait("!!document.querySelector('.timeline-row-flow.timeline-row-hovered')");
    await checkPalette();
    await evaluate("document.querySelector('.timeline-row-flow .timeline-row-label').click()");
    await wait("!!document.querySelector('.timeline-row-flow.selected')");
    await checkPalette();
    assert.match(await evaluate("getComputedStyle(document.querySelector('.timeline-row-flow .timeline-row-label')).boxShadow"),/4px/,'selection keeps the leading accent stripe');
    const capture=await call('Page.captureScreenshot',{format:'png'});
    fs.writeFileSync(path.join(screenshots,theme+'.png'),Buffer.from(capture.data,'base64'));
  }
  t.diagnostic('Screenshots: '+screenshots);
  assert.deepEqual(errors,[]);
});
