import { useId, type ReactNode } from "react";
import { useI18n } from "../i18n";
import { formatTimelineCursorTime, formatTimelineDuration, timelineIntervalGaps, type TimelineMeasurementInterval } from "../timelineCursor";
import type { TimelineDataGap } from "../types/api";
import type { EventLogItem } from "../types/api";

type Props = {
  reference: number;
  hover: number | null;
  range: { start: number; end: number };
  gaps: TimelineDataGap[];
  width: number;
  controls?: ReactNode;
  points?: Array<{ name: string; time: number; description?: string; event?: EventLogItem }>;
  interval: TimelineMeasurementInterval | null;
  hint: string;
  showReferenceDelta?: boolean;
  handles?: ReactNode;
  onOpenEvents?: (time: number, event?: EventLogItem) => void;
};

/** Shares the chart's scale, but never overlays the time ticks or event hit targets. */
export function TimelineCursorReadout({ reference, hover, range, gaps, width, controls, points, interval: span, hint, showReferenceDelta = false, handles, onOpenEvents }: Props) {
  const { t } = useI18n();
  const id = useId().replace(/:/g, "");
  const visiblePoints = points ?? [{ name: "P", time: reference }, ...(hover === null ? [] : [{ name: "H", time: hover }])];
  const at = (time: number) => ((time - range.start) / (range.end - range.start)) * width;
  const inside = (time: number) => time >= range.start && time <= range.end;
  const label = span ? `${span.label}: ${formatTimelineDuration(span.from, span.to)}` : "";
  const reasons = span ? timelineIntervalGaps(span.from, span.to, gaps) : [];
  const warning = reasons.map(reason => t(reason === "observation-unknown" ? "timeline.measure.unknown" : "timeline.measure.unavailable")).join(" / ");
  const left = span ? Math.max(0, Math.min(width, at(Math.min(span.from, span.to)))) : 0;
  const right = span ? Math.max(0, Math.min(width, at(Math.max(span.from, span.to)))) : 0;
  const textWidth = Math.min(width, Math.max(80, label.length * 6.8 + 12));
  const narrow = right - left < textWidth + 20;
  const preferredLabelX = narrow && width - right >= textWidth + 14 ? right + textWidth / 2 + 14
    : narrow && left >= textWidth + 14 ? left - textWidth / 2 - 14 : (left + right) / 2;
  const labelX = Math.max(textWidth / 2, Math.min(width - textWidth / 2, preferredLabelX));
  const outside = span && (!inside(span.from) || !inside(span.to));
  return <>
    <div className="timeline-measure-label">
      {controls ?? <strong>{t("timeline.measure.interval")}</strong>}
      <span className="timeline-measure-summary" data-tooltip={label || hint}>{label || hint}</span>
      {warning && <span className="timeline-measure-warning" role="status">{warning}</span>}
      {outside && <span className="timeline-measure-warning">{t("timeline.measure.partialCoverage")}</span>}
    </div>
    <div className="timeline-measure-scale">
      <div className="timeline-cursor-readouts">
        {visiblePoints.map(point => <span key={point.name} className={`timeline-cursor-readout cursor-${point.name.toLowerCase()}`} data-tooltip={[formatTimelineCursorTime(point.time), point.description].filter(Boolean).join("\n")}>
          <b>{point.name}</b> {(point.name === "H" || (point.name === "A" || point.name === "B") && !point.event) && <span data-tooltip={t("timeline.measure.approximate")}>≈</span>} {formatTimelineCursorTime(point.time)} {!inside(point.time) && <em>{t(point.time < range.start ? "timeline.measure.before" : "timeline.measure.after")}</em>}
          {point.description && <span className="timeline-anchor-event"> · {point.description}</span>}
          {onOpenEvents && (point.name === "A" || point.name === "B") && <button type="button" className={`timeline-open-${point.name.toLowerCase()}-events`} onClick={() => onOpenEvents(point.time, point.event)}>{t("timeline.navigation.events")}</button>}
        </span>)}
        {showReferenceDelta && span && span.label !== "H − P" && hover !== null && <span className="timeline-hover-delta">H − P: {formatTimelineDuration(reference, hover)}</span>}
      </div>
      {span && width > 0 && <svg className="timeline-interval" width="100%" height="28" role="img" aria-label={label}>
        <defs><marker id={`${id}-arrow`} viewBox="0 0 8 8" refX="4" refY="4" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 L8 4 L0 8" fill="none" stroke="currentColor" /></marker></defs>
        {right > left && <line x1={left} x2={right} y1="19" y2="19" markerStart={inside(Math.min(span.from, span.to)) ? `url(#${id}-arrow)` : undefined} markerEnd={inside(Math.max(span.from, span.to)) ? `url(#${id}-arrow)` : undefined} />}
        <rect x={labelX - textWidth / 2} y={narrow ? 0 : 11} width={textWidth} height="16" rx="3" />
        <text x={labelX} y={narrow ? 12 : 23} textAnchor="middle">{label}</text>
      </svg>}
      {handles}
    </div>
  </>;
}
          setCursorSec(Math.min(range.end, Math.max(range.start, selectedTimeSec ?? nowSec)));
        }}
        onPointerLeave={() => {
          setIsPointerInside(false);
          setIsCtrlPressed(false);
          if (scrubPointerIdRef.current !== null) return;
          setIsHoveringCursor(false);
          setCursorSec(Math.min(range.end, Math.max(range.start, nowSec)));
        }}
      >
      <div className={`timeline-axis${navigationTarget ? " has-navigation" : ""}`}>
        {navigationTarget && <div className="timeline-navigation-status" role="status">
          {t("timeline.navigation.time", { time: formatEventTime(navigationTarget.time) })}
          {navigationOutsideFilter && <span>{t("timeline.navigation.filtered")}</span>}
          {navigationLoading ? <span>{t("common.loadingTimeline")}</span> : navigationError ? <span>{navigationError}</span> : navigationEvent && !navigationRow && <span>{t(navigationEvent.streamKey || navigationEvent.flowKey ? "timeline.navigation.missing" : "timeline.navigation.noTarget")}</span>}
        </div>}
        <div className="timeline-axis-label">
          {stickyContext.length > 0 ? (
            <div className="timeline-sticky-context" aria-label="Current timeline hierarchy">{stickyContext.map((item, index) => <span className="stream-context-segment" key={`${item.kind}:${item.label}:${index}`}>
              {index > 0 && <span className="stream-context-separator" aria-hidden="true">›</span>}
              <span className={`stream-context-chip stream-context-${item.kind}${item.kind === "proto" ? " stream-context-proto-" + timelineContextProtoClass(item.proto) : ""}`} data-tooltip={item.title ?? item.label}>{item.label}</span>
            </span>)}</div>
          ) : null}
        </div>
        <div className="timeline-axis-scale" ref={axisScaleRef}>
          <TimelineGapBands gaps={gaps} range={range} label />
          {range.ticks.map((tick) => (
            <div key={tick} className="timeline-axis-tick" style={{ left: `${percent(tick, range.start, range.end)}%` }}>
              <span>{formatTick(tick, range.end - range.start)}</span>
            </div>
          ))}
        </div>
        <div className="timeline-event-rail-label">
          <span>Events</span>
          <div className="timeline-event-step-controls">
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(-1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === 0} aria-label="Previous warning or error event" data-tooltip-key="tooltip.previousEvent">Prev</button>
            <button type="button" className="timeline-event-step" onClick={() => moveToAdjacentMarker(1)} disabled={markerEvents.length === 0 || selectedMarkerIndex === markerEvents.length - 1} aria-label="Next warning or error event" data-tooltip-key="tooltip.nextEvent">Next</button>
          </div>
        </div>
        <TimelineEventRail buckets={eventRailBuckets} gaps={gaps} range={range} cursorPercent={cursorPercent} selectedEventId={selectedEventId} activeBucketEventIds={activeBucketEventIds} previewedEventId={previewedEventId} onActivateBucket={activateTimelineEventBucket} />
        <TimelineCursorReadout reference={displayedCursorSec} hover={isHoveringCursor ? cursorSec : null} range={range} gaps={gaps} width={axisWidth}
          controls={<div className="timeline-measure-controls">
            <button type="button" className="timeline-measure-toggle" aria-pressed={isMeasuring} data-tooltip={t(isMeasuring ? "timeline.measure.stop" : "timeline.measure.start")} onClick={() => changeMeasurement(isMeasuring ? stopTimelineMeasurement(measurement) : { ...measurement, enabled: true })}>{t("timeline.measure.mode")}</button>
            {(["A", "B"] as const).map(name => <button key={name} type="button" className={`timeline-measure-select cursor-${name.toLowerCase()}`} aria-pressed={measurement.enabled && measurement.active === name} onClick={() => changeMeasurement({ ...measurement, enabled: true, active: name })}>{name}</button>)}
            <button type="button" className="timeline-measure-clear" disabled={!measurement.A && !measurement.B} onClick={() => changeMeasurement({ ...measurement, active: "A", A: null, B: null })}>{t("timeline.measure.clear")}</button>
            {onOpenEvents && <button type="button" className="timeline-open-events" onClick={() => onOpenEvents(displayedCursorSec)} data-tooltip={t("timeline.navigation.events")}>P→Events</button>}
          </div>}
          points={[
            { name: "P", time: displayedCursorSec },
            ...(isHoveringCursor ? [{ name: "H", time: cursorSec }] : []),
            ...(["A", "B"] as const).flatMap(name => measurement.enabled && measurement[name] ? [{ name, time: measurement[name]!.time, description: measurement[name]!.event?.message, event: measurement[name]!.event }] : [])
          ]}
          interval={timelineMeasurementInterval(measurement, displayedCursorSec, isHoveringCursor ? cursorSec : null)}
          hint={t(measurement.enabled ? "timeline.measure.placeHint" : measurement.referenceActive ? "timeline.measure.hoverHint" : "timeline.measure.idleHint", { name: measurement.active })}
          showReferenceDelta={measurement.referenceActive}
          handles={(["A", "B"] as const).map(name => {
            const point = measurement[name];
            if (!measurement.enabled || !point || point.time < range.start || point.time > range.end) return null;
            return <button key={name} type="button" className={`timeline-anchor-handle anchor-${name.toLowerCase()}`} aria-label={t("timeline.measure.move", { name })} aria-pressed={measurement.enabled && measurement.active === name}
              style={{ left: `${percent(point.time, range.start, range.end)}%` }}
              onClick={event => { event.stopPropagation(); if (skipAnchorClickRef.current) { skipAnchorClickRef.current = false; return; } changeMeasurement({ ...measurement, enabled: true, active: name }); }}
              onPointerDown={event => {
                if (event.button !== 0) return;
                event.stopPropagation();
                skipAnchorClickRef.current = false;
                anchorDragRef.current = { name, pointerId: event.pointerId, original: measurement, startX: event.clientX, moved: false };
                event.currentTarget.setPointerCapture(event.pointerId);
                changeMeasurement({ ...measurement, enabled: true, active: name });
              }}
              onPointerMove={event => {
                if (anchorDragRef.current?.pointerId !== event.pointerId) return;
                event.stopPropagation();
                if (!anchorDragRef.current.moved && Math.abs(event.clientX - anchorDragRef.current.startX) < 2) return;
                anchorDragRef.current.moved = true;
                const time = timeFromClientX(event.clientX, false);
                if (time !== null) changeMeasurement({ ...setTimelineMeasurementPoint(measurementRef.current, name, { time }), active: name });
              }}
              onPointerUp={event => {
                event.stopPropagation();
                if (anchorDragRef.current?.moved) {
                  const time = timeFromClientX(event.clientX, false);
                  if (time !== null) changeMeasurement({ ...setTimelineMeasurementPoint(measurementRef.current, name, { time }), enabled: true, active: name });
                }
                anchorDragRef.current = null; skipAnchorClickRef.current = true;
              }}
              onPointerCancel={() => { if (anchorDragRef.current) changeMeasurement(anchorDragRef.current.original); anchorDragRef.current = null; skipAnchorClickRef.current = true; }}
              onKeyDown={event => {
