function TimelineTreeGuideLines({ guide }: { guide: TimelineTreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);

  return <span className="timeline-tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`timeline-tree-guide-line timeline-tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`timeline-tree-guide-line timeline-tree-guide-depth-${guide.depth} timeline-tree-guide-${segment}`} />)}
  </span>;
}

export function TimelinePane({ rows, gaps = [], nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, onPanBySec, onZoom, events = [], selectedEventId = null, onSelectEvent, onInspectTarget, interfaceNames, measurement: controlledMeasurement, onChangeMeasurement, navigationTarget, navigationOutsideFilter = false, navigationLoading = false, navigationError, onOpenEvents }: TimelinePaneProps) {
  const { t } = useI18n();
  const hasTimelineContent = rows.some(row => row.rowType === "stream") || gaps.length > 0 || Boolean(navigationTarget);
  const [localMeasurement, setLocalMeasurement] = useState(EMPTY_TIMELINE_MEASUREMENT);
  const measurement = controlledMeasurement ?? localMeasurement;
  const changeMeasurement = onChangeMeasurement ?? setLocalMeasurement;
  const isMeasuring = measurement.enabled || measurement.referenceActive;
  const measurementRef = useRef(measurement);
