          "--timeline-b-left": measurement.enabled && measurement.B && measurement.B.time >= range.start && measurement.B.time <= range.end ? `${percent(measurement.B.time, range.start, range.end)}%` : "-10px"
        } as CSSProperties}
        tabIndex={0}
        onKeyDown={(event) => {
