const {test} = require('node:test');
const assert = require('node:assert/strict');
const {clientBrowser} = require('./helpers/client-browser.cjs');

test('Timeline hover timestamp follows H in a reserved sticky lane without covering events or measurement', {timeout:40000}, async t => {
  const browser = await clientBrowser(t, `
    import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
    import {TimelinePane} from './client/src/components/TimelinePane';
    import {EMPTY_TIMELINE_MEASUREMENT} from './client/src/timelineCursor';
    import {I18nProvider} from './client/src/i18n';
    const epoch=1700000000,scope={known:true,layers:[],interfaceId:0,interfaceName:'lo'};
    const stream={rowType:'stream',streamKey:'s',label:'fixture',proto:'RTP',kind:'RTP',scope,interfaceId:0,active:true,firstSeen:epoch,lastSeen:epoch+60,segments:[{start:epoch,end:null}]};
    const rows=[stream,...Array.from({length:20},(_,i)=>({...stream,rowType:'flow',flowKey:'f'+i,parentStreamKey:'s',label:'Flow '+i}))];
    const event={id:'e',time:epoch+16.001,type:'test',level:'warn',scope:'flow',streamKey:'s',flowKey:'f0',message:'Fixture event'};
    window.timeCalls=0;window.panCalls=0;
    function Fixture(){
      const[c,setC]=useState({span:60,offset:0,width:1000,time:null}),[m,setM]=useState(EMPTY_TIMELINE_MEASUREMENT);
      window.state={...c,m};window.configure=p=>setC(s=>({...s,...p}));
      return <div className='timeline-body' style={{width:c.width,height:400}}><TimelinePane rows={rows} nowSec={epoch+60} fadeSec={2}
        rangeStartSec={epoch+c.offset} rangeEndSec={epoch+c.offset+c.span} expandLevel='flow' selectedTimeSec={c.time}
        measurement={m} onChangeMeasurement={setM} events={[event]}
        onSelectTime={time=>{window.timeCalls++;setC(s=>({...s,time}));setM(s=>({...s,referenceActive:true}))}}
        onPanBySec={delta=>{window.panCalls++;setC(s=>({...s,offset:s.offset+delta}))}} /></div>;
    }
    createRoot(document.getElementById('root')).render(<I18nProvider><Fixture/></I18nProvider>);
  `);
  if (!browser) return;
  const {evaluate,wait,call,errors} = browser;
  const move = point => call('Input.dispatchMouseEvent',{type:'mouseMoved',...point});
  const click = async point => {
    await move(point);
    await call('Input.dispatchMouseEvent',{type:'mousePressed',button:'left',clickCount:1,...point});
    await call('Input.dispatchMouseEvent',{type:'mouseReleased',button:'left',clickCount:1,...point});
  };
  const position = fraction => evaluate(`(()=>{const a=document.querySelector('.timeline-axis-scale').getBoundingClientRect(),r=document.querySelector('.timeline-row-stream .timeline-row-track').getBoundingClientRect();return{x:a.left+a.width*${fraction},y:r.top+r.height/2}})()`);
  const geometry = () => evaluate(`(()=>{
    const rect=s=>{const r=document.querySelector(s).getBoundingClientRect();return{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height}};
    return {axis:rect('.timeline-axis'),lane:rect('.timeline-hover-time-scale'),measure:rect('.timeline-measure-scale'),rail:rect('.timeline-event-rail'),rows:rect('.timeline-rows'),tag:rect('.timeline-hover-time-tag'),tip:rect('.timeline-hover-time-tip')};
  })()`);
  await wait("!!document.querySelector('.timeline-row-stream .timeline-row-track')");
  await move({x:0,y:0});
  assert.equal(await evaluate("!!document.querySelector('.timeline-hover-time-tag')"),false);
  const baseline = await evaluate("({height:document.querySelector('.timeline-axis').getBoundingClientRect().height,rows:document.querySelector('.timeline-rows').getBoundingClientRect().top})");
  const middle = await position(.365432);
  await move(middle);await wait("!!document.querySelector('.timeline-hover-time-tag')");
  const tagTime = await evaluate("document.querySelector('.timeline-hover-time-tag').dateTime");
  assert.ok(Math.abs(Date.parse(tagTime)/1000-(1700000000+60*.365432))<.1,'the tag retains fractional hover time');
  assert.match(await evaluate("document.querySelector('.timeline-hover-time-tag').textContent"),/^\d{2}:\d{2}:\d{2}\.\d{3}$/);
  assert.equal(await evaluate('timeCalls'),0);
  assert.equal(await evaluate('state.m.enabled||state.m.referenceActive'),false);
  assert.equal(await evaluate("!!document.querySelector('.timeline-interval')"),false,'standard hovering never starts measurement');
  const g = await geometry();
  assert.equal(g.lane.height,24);assert.equal(g.axis.height,baseline.height);assert.equal(g.rows.top,baseline.rows);
  assert.ok(g.rail.bottom<=g.lane.top&&g.measure.bottom<=g.lane.top&&g.lane.bottom<=g.rows.top,'the tag has its own lane below events and A/B');
  assert.ok(Math.abs((g.tag.left+g.tag.right)/2-middle.x)<1);
  assert.ok(Math.abs((g.tip.left+g.tip.right)/2-middle.x)<1);
  assert.equal(await evaluate("getComputedStyle(document.querySelector('.timeline-hover-time-tag')).pointerEvents"),'none');

  for (const theme of ['light','dark']) {
    await evaluate(`document.documentElement.dataset.theme='${theme}'`);
    for (const fraction of [.001,.999]) {
      const point=await position(fraction);await move(point);
      await wait(`Math.abs(parseFloat(getComputedStyle(document.querySelector('.timeline-chart')).getPropertyValue('--timeline-hover-left'))-${fraction*100})<.1`);
      const edge=await geometry();
      assert.ok(edge.tag.left>=edge.lane.left-.1&&edge.tag.right<=edge.lane.right+.1,'box stays inside chart');
      assert.ok(Math.abs((edge.tip.left+edge.tip.right)/2-point.x)<1,'clamping the box does not move the true time tip');
    }
  }
  await move(middle);await wait(`document.querySelector('.timeline-hover-time-tag').dateTime===${JSON.stringify(tagTime)}`);
  await evaluate('configure({offset:2.75})');
  await wait(`document.querySelector('.timeline-hover-time-tag').dateTime!==${JSON.stringify(tagTime)}`);
  const shifted=await evaluate("document.querySelector('.timeline-hover-time-tag').dateTime");
  assert.ok(Math.abs(Date.parse(shifted)-Date.parse(tagTime)-2750)<2,'a stationary pointer follows panned time');
  await evaluate('configure({span:120})');
  await wait(`document.querySelector('.timeline-hover-time-tag').dateTime!==${JSON.stringify(shifted)}`);
  const wider=await evaluate("document.querySelector('.timeline-hover-time-tag').dateTime");
  assert.ok(Math.abs(Date.parse(wider)/1000-(1700000000+2.75+120*.365432))<.1,'Range uses the new scale');
  await evaluate('configure({time:1700000010})');
  await move(await position(.6));
  await wait("document.querySelector('.timeline-hover-time-tag').dateTime!=="+JSON.stringify(wider));
  assert.equal(await evaluate('state.time'),1700000010,'H remains movable while Time travel is fixed');

  await evaluate("document.querySelector('.timeline-event-marker').click()");
  await wait("!!document.querySelector('.timeline-event-set-a')");
  await evaluate("document.querySelector('.timeline-event-set-a').click()");
  await call('Input.dispatchKeyEvent',{type:'keyDown',key:'Escape',code:'Escape'});
  await wait("!document.querySelector('.timeline-event-bucket-popover')");
  await move(middle);await wait("!!document.querySelector('.timeline-hover-time-tag')&&!!document.querySelector('.timeline-interval')");
  const ab=await geometry();
  assert.ok(await evaluate(`document.querySelector('.anchor-a').getBoundingClientRect().bottom<=${ab.lane.top}`),'A/B handles remain above the tag');
  const saved=await evaluate('JSON.stringify(state.m.A)');
  await call('Input.dispatchKeyEvent',{type:'keyDown',key:'Escape',code:'Escape'});
  await wait('!state.m.enabled');
  assert.ok(await evaluate("!!document.querySelector('.timeline-hover-time-tag')"),'ending measurement does not hide H timestamp');
  assert.equal(await evaluate('JSON.stringify(state.m.A)'),saved);

  await evaluate("document.querySelector('.timeline-body').scrollTop=80");
  await wait("document.querySelector('.timeline-body').scrollTop===80");
  const lanePoint=await evaluate("(()=>{const r=document.querySelector('.timeline-hover-time-scale').getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+10}})()");
  await move(lanePoint);await wait("!!document.querySelector('.timeline-hover-time-tag')");
  const scrolled=await geometry();
  assert.ok(Math.abs(scrolled.axis.top-g.axis.top)<1&&Math.abs(scrolled.lane.top-g.lane.top)<1,'timestamp lane stays with the sticky rails');
  assert.equal(await evaluate(`document.elementFromPoint(${lanePoint.x},${lanePoint.y}).className`),'timeline-hover-time-scale','the tag passes pointer input through to the time area');
  await click(lanePoint);await wait('timeCalls===1');
  const selected=await evaluate('state.time');
  await call('Input.dispatchMouseEvent',{type:'mousePressed',button:'left',clickCount:1,...lanePoint});
  await call('Input.dispatchMouseEvent',{type:'mouseMoved',button:'left',buttons:1,x:lanePoint.x+30,y:lanePoint.y});
  await call('Input.dispatchMouseEvent',{type:'mouseReleased',button:'left',clickCount:1,x:lanePoint.x+30,y:lanePoint.y});
  await wait('panCalls>0');assert.equal(await evaluate('timeCalls'),1);assert.equal(await evaluate('state.time'),selected);
  await evaluate('configure({width:500})');
  await wait("document.querySelector('.timeline-hover-time-scale').getBoundingClientRect().width<300");
  await move(await evaluate("(()=>{const r=document.querySelector('.timeline-hover-time-scale').getBoundingClientRect();return{x:r.right-1,y:r.top+10}})()"));
  await wait("parseFloat(getComputedStyle(document.querySelector('.timeline-chart')).getPropertyValue('--timeline-hover-left'))>99");
  const small=await geometry();assert.ok(small.tag.right<=small.lane.right+.1&&small.tag.left>=small.lane.left-.1);
  await move({x:0,y:0});await wait("!document.querySelector('.timeline-hover-time-tag')");
  assert.equal(await evaluate("document.querySelector('.timeline-axis').getBoundingClientRect().height"),baseline.height,'leaving the chart does not resize the header');
  assert.deepEqual(errors,[]);
});

