const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const {spawn} = require('node:child_process');
const {once} = require('node:events');
const esbuild = require('../../server/node_modules/esbuild');
const WebSocket = require('../../node_modules/ws');
const root = path.resolve(__dirname, '../..');
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

exports.clientBrowser = async (t, fixture) => {
  const chromePath = process.env.CHROME_PATH || '/root/.cache/puppeteer/chrome/linux-138.0.7204.157/chrome-linux64/chrome';
  if (!fs.existsSync(chromePath)) { t.skip('Set CHROME_PATH to a Chromium executable'); return null; }
  const bundle = await esbuild.build({stdin:{resolveDir:root,loader:'tsx',contents:fixture},bundle:true,write:false,platform:'browser',jsx:'automatic'});
  const css = ['styles.css','styles/tokens.css','styles/base.css','styles/panes.css','styles/streams.css','styles/timeline.css','styles/events.css','styles/tooltip.css']
    .map(file=>fs.readFileSync(path.join(root,'client/src',file),'utf8')).join('\n');
  const server = http.createServer((req,res)=>{
    if(req.url==='/fixture.js'){res.setHeader('Content-Type','application/javascript');return res.end(bundle.outputFiles[0].text);}
    if(req.url==='/locales/strings.json'){res.setHeader('Content-Type','application/json');return res.end(fs.readFileSync(path.join(root,'locales/strings.json')));}
    res.setHeader('Content-Type','text/html');res.end(`<html><head><style>${css}</style></head><body><div id="root"></div><script src="/fixture.js"></script></body></html>`);
  });
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const chrome=spawn(chromePath,['--headless','--no-sandbox','--disable-dev-shm-usage','--remote-debugging-port=0','about:blank'],{stdio:['ignore','ignore','pipe']});
  let log='',socket;chrome.stderr.on('data',data=>log+=data);
  t.after(async()=>{socket?.close();chrome.kill('SIGTERM');if(chrome.exitCode===null)await once(chrome,'exit');await new Promise(resolve=>server.close(resolve));});
  for(let i=0;i<100&&!log.includes('DevTools listening');i++)await sleep(30);
  const port=log.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/)?.[1];assert.ok(port,log);
  const tab=await(await fetch(`http://127.0.0.1:${port}/json/new?http://127.0.0.1:${server.address().port}`,{method:'PUT'})).json();
  socket=new WebSocket(tab.webSocketDebuggerUrl);await once(socket,'open');
  let sequence=0;const pending=new Map(),errors=[];
  socket.on('message',raw=>{const m=JSON.parse(raw);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}if(m.method==='Runtime.exceptionThrown')errors.push(m.params);});
  const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});socket.send(JSON.stringify({id,method,params}));});
  const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});assert.ok(!r.exceptionDetails,JSON.stringify(r.exceptionDetails));return r.result.value;};
  const wait=async expression=>{for(let i=0;i<150;i++){if(await evaluate(expression))return;await sleep(30);}assert.fail(expression+'; exceptions: '+JSON.stringify(errors));};
  await call('Runtime.enable');
  return {call,evaluate,wait,errors};
};
