/* Tree selection follows Streams: accent fill with a 4px leading bar. */
.timeline-scope-row.selected,
.timeline-interface-header.selected,
.timeline-proto-row.selected,
.timeline-row.selected {
  background: var(--accent-soft);
}

.timeline-scope-row.selected .timeline-scope-label,
.timeline-interface-header.selected .timeline-interface-label,
.timeline-proto-row.selected .timeline-proto-label,
.timeline-row.selected .timeline-row-label {
  background: var(--accent-soft);
  box-shadow: inset 4px 0 0 var(--accent);
}

.timeline-virtual-item:has(.selected) .timeline-tree-guide-line {
  background: color-mix(in srgb, var(--accent) 58%, var(--muted));
}

/* The context occupies the axis label column, leaving the time scale unobscured. */
.timeline-sticky-context {
  min-width: 0;
  overflow: hidden;
  color: var(--text-strong);
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}

/* Projected metrics availability bounds these lanes; hatch means state is unknown. */
.timeline-gap-band {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 2;
  border-inline: 1px solid color-mix(in srgb, var(--muted) 42%, transparent);
  background: repeating-linear-gradient(
    135deg,
    color-mix(in srgb, var(--surface) 78%, var(--muted)) 0 5px,
    color-mix(in srgb, var(--surface-muted) 88%, var(--muted)) 5px 10px
  );
  pointer-events: auto;
}

.timeline-gap-band.timeline-gap-unknown {
  border-inline-style: dashed;
  background: radial-gradient(circle at 1px 1px, color-mix(in srgb, var(--muted) 44%, transparent) 1px, transparent 1.2px)
    0 0 / 5px 5px, color-mix(in srgb, var(--surface) 94%, var(--muted));
}

.timeline-axis-scale .timeline-gap-band {
  z-index: 1;
}

.timeline-axis-tick,
.timeline-segment {
  z-index: 1;
}

.timeline-axis-tick {
  z-index: 2;
}

.timeline-cursor-line {
  z-index: 3;
}

/* Sticky event rail shares the time scale and remains visible above scrolling lanes. */
.timeline-axis {
  position: sticky;
  top: 0;
